window.IDX=[{"u":"g-overview.html","t":"A quick tour of the app","a":"Everyday jobs","k":"tour start begin new basics overview around app intro introduction help everything learn show","v":1},{"u":"g-overview.html#s1","t":"My day","a":"A quick tour of the app","x":"Every morning starts here: your appointments, follow-ups due, new requests, jobs waiting on a permit and who is on site."},{"u":"g-overview.html#s2","t":"Search everything","a":"A quick tour of the app","x":"Type a name, phone, street or an EST-, JOB- or INV- number. \u2318K jumps here from any screen."},{"u":"g-overview.html#s3","t":"Ask for help any time","a":"A quick tour of the app","x":"Tell it what you want to do and it shows you, step by step, like this."},{"u":"g-overview.html#s4","t":"Customers","a":"A quick tour of the app","x":"Every customer and lead. One screen each: phones, addresses, notes, estimates, jobs, invoices."},{"u":"g-overview.html#s5","t":"Estimates","a":"A quick tour of the app","x":"Every estimate and its follow-ups. Won ones become jobs in one step."},{"u":"g-overview.html#s6","t":"Schedule","a":"A quick tour of the app","x":"Crews down the side, days across. Drag work onto a crew; drag it again to move it."},{"u":"g-overview.html#s7","t":"Invoices","a":"A quick tour of the app","x":"Bills, payments, card declines and month-end billing."},{"u":"g-overview.html#s8","t":"The Guide","a":"A quick tour of the app","x":"Every how-to in one place. Each one has a tour like this."},{"u":"g-call.html","t":"Book a visit, a call back or a task for a customer","a":"Everyday jobs","k":"book booking appointment visit site estimate call phone callback customer caller schedule salesperson ticket new meet","v":1},{"u":"g-call.html#s1","t":"Find the customer","a":"Book a visit, a call back or a task for a customer","x":"Search by name, phone or street."},{"u":"g-call.html#s2","t":"A new caller?","a":"Book a visit, a call back or a task for a customer","x":"New customer: name, phones, address (the zip fills the town), CSR and salesperson on one screen, and \"Book the first appointment now\"."},{"u":"g-call.html#s3","t":"Open the customer","a":"Book a visit, a call back or a task for a customer","x":"Click the customer to open them."},{"u":"g-call.html#s4","t":"Book it from the customer","a":"Book a visit, a call back or a task for a customer","x":"Appointment: their name, phone and address come with it."},{"u":"g-call.html#s5","t":"Visit, phone call or task","a":"Book a visit, a call back or a task for a customer","x":"A visit has a time and a place, a phone call shows the number to call, a task is any to-do."},{"u":"g-call.html#s6","t":"When","a":"Book a visit, a call back or a task for a customer","x":"The day, and a time from / to, or leave it at Any time."},{"u":"g-call.html#s7","t":"Who goes","a":"Book a visit, a call back or a task for a customer","x":"Only the people who take appointments are listed (set on Team & crews)."},{"u":"g-call.html#s8","t":"Save it","a":"Book a visit, a call back or a task for a customer","x":"Book it puts it on their My day and on their phone. The tour doesn't save anything: press it yourself when it's real."},{"u":"g-task.html","t":"Give someone a task (to-do, internal meeting)","a":"Everyday jobs","k":"task todo to-do meeting internal assign tech technician crew reminder follow up job","v":1},{"u":"g-task.html#s1","t":"New appointment","a":"Give someone a task (to-do, internal meeting)","x":"Tasks, visits and calls all start here (or from a customer)."},{"u":"g-task.html#s2","t":"Choose Task","a":"Give someone a task (to-do, internal meeting)","x":"A task is any to-do: an internal meeting, an order to place, a follow-up."},{"u":"g-task.html#s3","t":"Anyone, crews included","a":"Give someone a task (to-do, internal meeting)","x":"Give it to anyone in the company. It shows on their phone under My appointments until they mark it done."},{"u":"g-task.html#s4","t":"Save it","a":"Give someone a task (to-do, internal meeting)","x":"Book it when it's real. The tour doesn't save anything."},{"u":"g-estimate.html","t":"Write and send an estimate","a":"Everyday jobs","k":"estimate quote proposal price pricing write measure measurement tax taxable exempt optional addon add-on send email print pdf section material","v":1},{"u":"g-estimate.html#s1","t":"A new estimate","a":"Write and send an estimate","x":"Start here, or from the customer with New estimate."},{"u":"g-estimate.html#s2","t":"Open one","a":"Write and send an estimate","x":"Let's look inside an estimate."},{"u":"g-estimate.html#s3","t":"One section per scope","a":"Write and send an estimate","x":"Paver patio, Lighting, Walls \u2026 The customer sees each section with its total; materials inside stay hidden unless you tick them."},{"u":"g-estimate.html#s4","t":"Taxable or tax exempt","a":"Write and send an estimate","x":"One click switches the section between Taxable and Tax exempt; the tax follows."},{"u":"g-estimate.html#s5","t":"Measure on the aerial photo","a":"Write and send an estimate","x":"Trace the patio, driveway, beds or wall line; the areas go onto the estimate in one click."},{"u":"g-estimate.html#s6","t":"Pavers and colours","a":"Write and send an estimate","x":"The customer's picks, and the Selection sheet for them to sign."},{"u":"g-estimate.html#s7","t":"What the customer gets","a":"Write and send an estimate","x":"Open or print exactly what the customer receives."},{"u":"g-estimate.html#s8","t":"Send it","a":"Write and send an estimate","x":"Top right: Email it (or Email the link again / Send the update once it has gone out) and Print / PDF. Follow-ups due then show on My day."},{"u":"g-won.html","t":"The customer said yes: contract, payment schedule and job","a":"Everyday jobs","k":"won win accepted yes sold sale signed contract job create payment schedule deposit 30 60 10 50","v":1},{"u":"g-won.html#s1","t":"Open the estimate","a":"The customer said yes: contract, payment schedule and job","x":"The one the customer accepted."},{"u":"g-won.html#s2","t":"Won","a":"The customer said yes: contract, payment schedule and job","x":"Press Won when they accept: on the phone, by email or in person."},{"u":"g-won.html#s3","t":"One step makes it all","a":"The customer said yes: contract, payment schedule and job","x":"The contract, the payment schedule and the job, with a work item per section. Tick the add-ons they took."},{"u":"g-won.html#s4","t":"Create the job","a":"The customer said yes: contract, payment schedule and job","x":"Press it when it's real: the job then waits on the Schedule. The tour doesn't press it."},{"u":"g-schedule.html","t":"Schedule work, assign crews, move it (rain days)","a":"Everyday jobs","k":"schedule calendar board dispatch crew crews assign drag drop move reschedule rain day month week colour color start date","v":1},{"u":"g-schedule.html#s1","t":"Waiting to be scheduled","a":"Schedule work, assign crews, move it (rain days)","x":"Every sold piece of work waits here until it has a crew and a start day."},{"u":"g-schedule.html#s2","t":"Drag it onto a crew","a":"Schedule work, assign crews, move it (rain days)","x":"Drag it onto a crew's start day (or click it, then the day). The days come from the crew-hours \u00f7 the crew size."},{"u":"g-schedule.html#s3","t":"Move it any time","a":"Schedule work, assign crews, move it (rain days)","x":"Drag a block to another day or crew; a multi-day job moves together. A lock means it waits on a permit."},{"u":"g-schedule.html#s4","t":"Month view","a":"Schedule work, assign crews, move it (rain days)","x":"The whole month, coloured by crew."},{"u":"g-schedule.html#s5","t":"What the colours mean","a":"Schedule work, assign crews, move it (rain days)","x":"Each job its own colour on the board; each crew its own colour in the month."},{"u":"g-money.html","t":"Invoice, record a payment, chase what's owed","a":"Everyday jobs","k":"invoice bill billing payment pay paid record check cash card ach balance deposit owed owing collection collections late overdue call list receivable","v":1},{"u":"g-money.html#s1","t":"Open an invoice","a":"Invoice, record a payment, chase what's owed","x":"Invoices come from the job: a payment-schedule step, the balance, or a change order."},{"u":"g-money.html#s2","t":"Record a payment","a":"Invoice, record a payment, chase what's owed","x":"Check, cash, ACH or card. A card payment adds the card fee as its own line; the job's balance updates."},{"u":"g-money.html#s3","t":"Who owes what","a":"Invoice, record a payment, chase what's owed","x":"Open invoices by customer and by age: 0\u201330, 31\u201360, 61\u201390, 90+."},{"u":"g-money.html#s4","t":"The call list","a":"Invoice, record a payment, chase what's owed","x":"Print it every couple of weeks for the office to call."},{"u":"g-signups.html","t":"Spring / Fall cleanup sign-ups","a":"Everyday jobs","k":"spring fall cleanup clean up signup sign-up sign form forms request requests google leaves mulch queue order received","v":1},{"u":"g-signups.html#s1","t":"Cleanup sign-ups","a":"Spring / Fall cleanup sign-ups","x":"Your Spring and Fall forms and everyone who signed up."},{"u":"g-signups.html#s2","t":"Your forms","a":"Spring / Fall cleanup sign-ups","x":"See the form shows it exactly as customers see it."},{"u":"g-signups.html#s3","t":"Someone calls instead","a":"Spring / Fall cleanup sign-ups","x":"The same questions; they get their place in line."},{"u":"g-signups.html#s4","t":"Work the list from #1","a":"Spring / Fall cleanup sign-ups","x":"Accept books the visit or the stop-by quote; an auto-pay \"call me\" becomes a call for the office."},{"u":"g-permit.html","t":"Permits: no start before the township approves","a":"Everyday jobs","k":"permit permits township approval approve approved inspection municipality hold start lbt","v":1},{"u":"g-permit.html#s1","t":"Open a job","a":"Permits: no start before the township approves","x":"Permits are kept on the job."},{"u":"g-permit.html#s2","t":"The job folder","a":"Permits: no start before the township approves","x":"Tick \"Needs a township permit\" and fill in the township and dates. The crew can't start until you press \"Mark the permit approved\"; the job shows a lock on the schedule meanwhile."},{"u":"g-commission.html","t":"Commissions report","a":"Everyday jobs","k":"commission commissions salesperson salespeople sales report rep paid full earn","v":1},{"u":"g-commission.html#s1","t":"Commissions","a":"Commissions report","x":"Completed, paid-in-full jobs per salesperson (\"sold by\" on the estimate), with the rate and the amount."},{"u":"g-commission.html#s2","t":"For Excel","a":"Commissions report","x":"Export it for payroll."},{"u":"g-selections.html","t":"Material selections and the selection sheet","a":"Everyday jobs","k":"selection selections paver pavers colour color style manufacturer cedar bridge sheet sign approval approve wall block caps","v":1},{"u":"g-selections.html#s1","t":"Open the estimate","a":"Material selections and the selection sheet","x":"Selections live on the estimate."},{"u":"g-selections.html#s2","t":"The customer's picks","a":"Material selections and the selection sheet","x":"Add selections: field and border paver, wall block, caps, steps, coping, upgrades. Record approval when they sign."},{"u":"g-s_home.html","t":"Everything on My day","a":"Sell","k":"home my day today morning start dashboard overview appointments overdue numbers kpi estimates out won month to schedule overdue crews on site website requests follow ups followups automations timesheets clock out fleet trucks notifications bell search help latest activity","v":0},{"u":"g-s_home.html#s1","t":"My day: where every morning starts","a":"Everything on My day","x":"Today's date, how many appointments you have today, anything overdue and how many crews are on site. Everything on this screen is about you and today."},{"u":"g-s_home.html#s2","t":"Search everything","a":"Everything on My day","x":"Type a name, phone, street, or an EST-, JOB- or INV- number and pick the result to open it. \u2318K (Ctrl+K) jumps here from any screen."},{"u":"g-s_home.html#s3","t":"Help","a":"Everything on My day","x":"Ask how to do something in your own words. It finds the tour that fits and shows you on the screen, like this one."},{"u":"g-s_home.html#s4","t":"Notifications","a":"Everything on My day","x":"New assignments, wins and payments for you. The red number counts the unread ones. Click one to open it; Mark all read clears them."},{"u":"g-s_home.html#s5","t":"Crews out today","a":"Everything on My day","x":"How many crews are on a job today, out of all your crews. If you see money, this month's wins and the value of estimates out with customers sit beside it."},{"u":"g-s_home.html#s6","t":"New customer","a":"Everything on My day","x":"Opens the New customer form right here: name, phones, address, salesperson, and the first appointment if you like. Saving opens the new customer."},{"u":"g-s_home.html#s7","t":"New appointment","a":"Everything on My day","x":"Book a visit, a phone call or a task for anyone. It goes straight onto that person's day. The Appointments tours walk every field."},{"u":"g-s_home.html#s8","t":"Schedule","a":"Everything on My day","x":"Opens the Schedule board: crews down the side, days across, and the sold work waiting for a date."},{"u":"g-s_home.html#s9","t":"Estimates out","a":"Everything on My day","x":"Sent estimates still waiting on the customer: the value, or the count if you don't see money. Click the box to open Estimates."},{"u":"g-s_home.html#s10","t":"Won this month","a":"Everything on My day","x":"Estimates won since the 1st of the month and how many jobs they made. Click the box to open Jobs."},{"u":"g-s_home.html#s11","t":"To schedule","a":"Everything on My day","x":"Pieces of sold work with no crew or start day yet. Click the box to open the Schedule and give them a date."},{"u":"g-s_home.html#s12","t":"Overdue invoices","a":"Everything on My day","x":"What customers owe past the due date, and on how many invoices. Click the box to open Invoices. People who don't see money get Crews out today here."},{"u":"g-s_home.html#s13","t":"My day","a":"Everything on My day","x":"Your appointments and tasks for today, with anything overdue at the top in red. Add books a new one for you or for someone else."},{"u":"g-s_home.html#s14","t":"Open an appointment","a":"Everything on My day","x":"Each line shows the time, what it's for, the customer, place and phone, and the type. A camera means the visit sent notes or photos. Click a line to open it."},{"u":"g-s_home.html#s15","t":"The appointment","a":"Everything on My day","x":"When, with whom, the customer (click the name to open them), phone, address and office notes. Below: notes, measurements and photos saved on the visit from the phone."},{"u":"g-s_home.html#s16","t":"Edit, visit done, mark done","a":"Everything on My day","x":"Edit changes it. Visit done \u00b7 estimate pending keeps an estimate visit open as the reminder to write the quote. Mark done closes it. The tour presses none of them."},{"u":"g-s_home.html#s17","t":"Close it","a":"Everything on My day","x":"The X closes the appointment without changing anything."},{"u":"g-s_home.html#s18","t":"Edit from the list","a":"Everything on My day","x":"The pencil opens the appointment's form straight away, to change the day, time, person or details."},{"u":"g-s_home.html#s19","t":"Mark it done","a":"Everything on My day","x":"The tick marks it done and takes it off your day. Use it once the visit, call or task has happened."},{"u":"g-s_home.html#s20","t":"Next 7 days","a":"Everything on My day","x":"Your appointments for the coming week, day by day, so you can plan office time. The lines work the same as in My day."},{"u":"g-s_home.html#s21","t":"What needs you","a":"Everything on My day","x":"Cards here appear only when there is something to do: New from the website, Waiting on a permit (the township hasn't approved yet) and Waiting on a quote (visit done, no estimate)."},{"u":"g-s_home.html#s22","t":"New from the website","a":"Everything on My day","x":"Website requests waiting for someone. Accept makes the lead (or finds the existing customer) plus a ticket, and opens them. All opens Marketing."},{"u":"g-s_home.html#s23","t":"Follow-ups","a":"Everything on My day","x":"Sent estimates with no answer yet: click one to open it; Sent or Called records the follow-up. When none are due it says the automatic follow-ups are handling them."},{"u":"g-s_home.html#s24","t":"On site today","a":"Everything on My day","x":"Which crew is on which job today, with the customer, place and \"day 3 of 5\" on longer jobs. Click a line to open the job."},{"u":"g-s_home.html#s25","t":"Automations","a":"Everything on My day","x":"Messages the automations sent today, how many are waiting to go and any that failed (red). Click it to open Automations."},{"u":"g-s_home.html#s26","t":"Missed clock-outs","a":"Everything on My day","x":"Shows up when someone on a crew forgot to clock out. Fix it on Timesheets before payroll: click it to go there."},{"u":"g-s_home.html#s27","t":"Fleet","a":"Everything on My day","x":"Truck problems the crews reported from the phone, and trucks overdue for service. Click it to open Fleet."},{"u":"g-s_home.html#s28","t":"Latest across the business","a":"Everything on My day","x":"The eight latest things that happened across all customers. Click a name to open that customer."},{"u":"g-s_customers.html","t":"Everything on Customers","a":"Sell","k":"customers customer list leads lead clients find search new add create caller export excel filter stage active inactive rep salesperson town zip owes balance monthly do not market demo phone","v":0},{"u":"g-s_customers.html#s1","t":"Customers","a":"Everything on Customers","x":"Every customer and lead in one list. The line under the title counts your customers and your leads."},{"u":"g-s_customers.html#s2","t":"Export","a":"Everything on Customers","x":"Saves the list as it is filtered right now as a file for Excel: code, name, phone, email, address, stage, rep and source. Handy for mailings."},{"u":"g-s_customers.html#s3","t":"New customer","a":"Everything on Customers","x":"Opens the New customer form above the list. Let's look at it; the tour doesn't save anything."},{"u":"g-s_customers.html#s4","t":"Name","a":"Everything on Customers","x":"First and last name, or a Company for businesses (leave Company blank for homeowners). Only a name is required."},{"u":"g-s_customers.html#s5","t":"Phones and email","a":"Everything on Customers","x":"Cell phone, another phone and email. Search finds the customer by any of them later."},{"u":"g-s_customers.html#s6","t":"Property address","a":"Everything on Customers","x":"Where the work is: street and number."},{"u":"g-s_customers.html#s7","t":"The zip fills the town","a":"Everything on Customers","x":"Type the 5-digit zip and Town and State fill themselves. You can still change them."},{"u":"g-s_customers.html#s8","t":"Billing address","a":"Everything on Customers","x":"Ticked, invoices go to the property. Untick it to add a different Bill to name and billing address."},{"u":"g-s_customers.html#s9","t":"Source, salesperson, CSR","a":"Everything on Customers","x":"Where the lead came from and who referred them, the Salesperson who owns them and the CSR in the office who looks after them."},{"u":"g-s_customers.html#s10","t":"Stage, type, invoicing, terms","a":"Everything on Customers","x":"Lead, Customer or Inactive; Residential or Commercial; invoiced when work is done or monthly (month-end run); Due on receipt or Net 30."},{"u":"g-s_customers.html#s11","t":"Payment and flags","a":"Everything on Customers","x":"Check or card, the card's last 4 digits only, Do not market (no seasonal emails) and Tax exempt."},{"u":"g-s_customers.html#s12","t":"Office notes","a":"Everything on Customers","x":"Gate codes, dogs, best time to call. They show on the customer's screen."},{"u":"g-s_customers.html#s13","t":"Book the first appointment","a":"Everything on Customers","x":"Tick it to book their first visit in the same step. It goes straight onto that person's day, no second step."},{"u":"g-s_customers.html#s14","t":"When and with whom","a":"Everything on Customers","x":"Date, From and To, and who goes; under it, what it's for and the type. With follows the Salesperson you picked."},{"u":"g-s_customers.html#s15","t":"Save customer","a":"Everything on Customers","x":"Saves the customer (and the appointment) and opens them. Press it yourself when it's real; the tour doesn't save."},{"u":"g-s_customers.html#s16","t":"Close the form","a":"Everything on Customers","x":"The X (or Cancel) closes the form without saving."},{"u":"g-s_customers.html#s17","t":"Search customers","a":"Everything on Customers","x":"Type part of a name, a phone (the last 4 digits work), street, email or C-code. It searches every customer, not only this page."},{"u":"g-s_customers.html#s18","t":"Active, leads, customers\u2026","a":"Everything on Customers","x":"Active is leads and customers together. Leads, Customers, Inactive and All narrow the list; the numbers are the counts."},{"u":"g-s_customers.html#s19","t":"Leads only","a":"Everything on Customers","x":"Let's switch to Leads."},{"u":"g-s_customers.html#s20","t":"New lead","a":"Everything on Customers","x":"On Leads the button says New lead and the form starts as a lead. On Customers it starts as a customer."},{"u":"g-s_customers.html#s21","t":"By salesperson","a":"Everything on Customers","x":"Only the customers of one salesperson."},{"u":"g-s_customers.html#s22","t":"By town","a":"Everything on Customers","x":"Only one town. The number beside each town is how many customers are there."},{"u":"g-s_customers.html#s23","t":"Quick filters","a":"Everything on Customers","x":"Owes money (if you see money), Billed monthly, Open estimates, Do not market, or Demo records."},{"u":"g-s_customers.html#s24","t":"The list","a":"Everything on Customers","x":"Name, address and code, phone, stage, rep, open estimates, balance (money roles: red owed, green credit) and last activity. 50 a page, with Previous / Next below."},{"u":"g-s_customers.html#s25","t":"Open a customer","a":"Everything on Customers","x":"Click anyone to open their screen: details, history, estimates, jobs, invoices and more. \"Everything on a customer\" shows it all."},{"u":"g-customer_actions.html","t":"Book, log a call or edit a customer","a":"Sell","k":"customer edit change details update stage lead customer inactive log call note email phone conversation timeline appointment book visit estimate quote start","v":1},{"u":"g-customer_actions.html#s1","t":"Open the customer","a":"Book, log a call or edit a customer","x":"It all starts from their screen. Let's open Bayview Marina."},{"u":"g-customer_actions.html#s2","t":"Book an appointment","a":"Book, log a call or edit a customer","x":"Appointment opens the booking form for this customer."},{"u":"g-customer_actions.html#s3","t":"Visit, phone call or task","a":"Book, log a call or edit a customer","x":"Pick what it is first and the fields follow: a call has a call time and who calls, a task can go to anyone. Then What for, Date, time and Notes."},{"u":"g-customer_actions.html#s4","t":"Who and where come along","a":"Book, log a call or edit a customer","x":"Their name, phone and address are filled in already, and With starts as their salesperson."},{"u":"g-customer_actions.html#s5","t":"Close it","a":"Book, log a call or edit a customer","x":"Close it without booking. Book it would put it on that person's day."},{"u":"g-customer_actions.html#s6","t":"Log a call","a":"Book, log a call or edit a customer","x":"Log call writes a conversation down on their Timeline."},{"u":"g-customer_actions.html#s7","t":"Call, note or email","a":"Book, log a call or edit a customer","x":"Phone call, Note or Email: pick what it was."},{"u":"g-customer_actions.html#s8","t":"What was said","a":"Book, log a call or edit a customer","x":"A line or two on what was said or agreed."},{"u":"g-customer_actions.html#s9","t":"Save it","a":"Book, log a call or edit a customer","x":"Save adds it to the Timeline with your name and the time. The tour doesn't press it."},{"u":"g-customer_actions.html#s10","t":"Close it","a":"Book, log a call or edit a customer","x":"The X closes it without saving."},{"u":"g-customer_actions.html#s11","t":"Edit their details","a":"Book, log a call or edit a customer","x":"Edit opens everything about them in one form."},{"u":"g-customer_actions.html#s12","t":"Change stage and billing","a":"Book, log a call or edit a customer","x":"The same fields as New customer. Move a lead to Customer or Inactive here, switch to monthly invoicing, change terms, salesperson or CSR."},{"u":"g-customer_actions.html#s13","t":"Save changes","a":"Book, log a call or edit a customer","x":"Saves and updates their screen. The tour doesn't save."},{"u":"g-customer_actions.html#s14","t":"Close it","a":"Book, log a call or edit a customer","x":"Closes the form; nothing changed."},{"u":"g-customer_actions.html#s15","t":"Start an estimate","a":"Book, log a call or edit a customer","x":"Estimate makes a new draft estimate for them and opens it to write. Press it when you're ready to quote."},{"u":"g-s_customer.html","t":"Everything on a customer","a":"Sell","k":"customer record profile account history timeline estimates jobs invoices appointments photos files permits messages emails texts balance owes credit containers dumpster maintenance plan surveys contact notes rep csr opt out","v":0},{"u":"g-s_customer.html#s1","t":"Open a customer","a":"Everything on a customer","x":"Click a customer on the list to open their screen. Let's open Bayview Marina."},{"u":"g-s_customer.html#s2","t":"Who they are","a":"Everything on a customer","x":"Code (and Commercial), name and stage, then the property address, phone and email at a glance."},{"u":"g-s_customer.html#s3","t":"Back to the list","a":"Everything on a customer","x":"Goes back to the Customers list."},{"u":"g-s_customer.html#s4","t":"Appointment","a":"Everything on a customer","x":"Books a visit, call or task for them: their name, phone and address come along, and With starts as their salesperson."},{"u":"g-s_customer.html#s5","t":"Estimate","a":"Everything on a customer","x":"Starts a new draft estimate for this customer and opens it. The tour doesn't press it, because it makes the draft."},{"u":"g-s_customer.html#s6","t":"Log call","a":"Everything on a customer","x":"Writes down a phone call, a note or an email on their Timeline."},{"u":"g-s_customer.html#s7","t":"Edit","a":"Everything on a customer","x":"Opens their details in the same form as New customer. The tour \"Book, log a call or edit a customer\" opens these forms."},{"u":"g-s_customer.html#s8","t":"Key facts","a":"Everything on a customer","x":"Rep, CSR, where they came from, customer since, monthly invoicing and card on file. Do not market and Tax exempt show here in colour when set."},{"u":"g-s_customer.html#s9","t":"Timeline","a":"Everything on a customer","x":"Everything that happened with them, newest first: calls, appointments, estimates, emails, invoices and payments."},{"u":"g-s_customer.html#s10","t":"Estimates","a":"Everything on a customer","x":"Their estimates: number, status, any follow-up due, rep, total and date. Click one to open it."},{"u":"g-s_customer.html#s11","t":"Jobs","a":"Everything on a customer","x":"Their jobs: status, when it runs and the value. Click one to open the job."},{"u":"g-s_customer.html#s12","t":"Invoices","a":"Everything on a customer","x":"Their invoices: date issued, status, total and what's still open. Click one to open it."},{"u":"g-s_customer.html#s13","t":"Appointments","a":"Everything on a customer","x":"Their visits, calls and tasks. The number on the tab counts the open ones."},{"u":"g-s_customer.html#s14","t":"New appointment","a":"Everything on a customer","x":"Books one for this customer, the same as the Appointment button at the top."},{"u":"g-s_customer.html#s15","t":"Open one","a":"Everything on a customer","x":"Click a row to see it: when, who, notes and what came back from the visit (notes, photos), with Edit and Mark done."},{"u":"g-s_customer.html#s16","t":"Edit it here","a":"Everything on a customer","x":"The pencil changes it right here, without going to the Appointments screen."},{"u":"g-s_customer.html#s17","t":"Mark done","a":"Everything on a customer","x":"The tick closes it. A done one shows a Reopen arrow instead, to open it again."},{"u":"g-s_customer.html#s18","t":"Photos","a":"Everything on a customer","x":"Property photos and files kept on the customer, not buried in a job: permits, surveys, drawings."},{"u":"g-s_customer.html#s19","t":"Add photos and files","a":"Everything on a customer","x":"Take photo or Upload file adds one. Each file has Open, and the bin takes it off the customer (the file itself is kept)."},{"u":"g-s_customer.html#s20","t":"Messages","a":"Everything on a customer","x":"Every email and text sent to them: follow-ups, reminders, notices, campaigns. Each shows Sent, Queued (with when it goes) or Failed."},{"u":"g-s_customer.html#s21","t":"Account balance","a":"Everything on a customer","x":"What they owe across all open invoices (or their credit), each open invoice (click one to open it) and what they've paid to date."},{"u":"g-s_customer.html#s22","t":"Containers","a":"Everything on a customer","x":"Dumpsters at this customer now: unit, size, address and days out. Drop one books a drop and Pickup books a pickup, both on Deliveries."},{"u":"g-s_customer.html#s23","t":"Maintenance plans","a":"Everything on a customer","x":"Recurring work like lawn care, beds or snow: how often, price and next visit. Add plan (money roles) opens Maintenance for this customer."},{"u":"g-s_customer.html#s24","t":"What they get from us","a":"Everything on a customer","x":"Seasonal marketing emails, payment reminders and text messages. A switch saves the moment you flip it, so change one only when the customer asks."},{"u":"g-s_customer.html#s25","t":"Surveys","a":"Everything on a customer","x":"Their latest survey scores out of 5, with comments. 3 or less shows in red."},{"u":"g-s_customer.html#s26","t":"Coming up","a":"Everything on a customer","x":"Their next open appointments. The tick marks one done."},{"u":"g-s_customer.html#s27","t":"Contact","a":"Everything on a customer","x":"Cell, other phone, email, property, bill-to address and terms. Office notes and other contacts show below when there are any."},{"u":"g-s_tickets.html","t":"Everything on Appointments","a":"Sell","k":"appointments appointment tickets ticket agenda visits visit calls call back callback collection tasks task to-do mine everyone overdue done waiting quote estimate pending reopen mark done filter type person","v":0},{"u":"g-s_tickets.html#s1","t":"Appointments","a":"Everything on Appointments","x":"Sales visits, call-backs, collections and tasks for everyone. Each one sits on someone's day, so nothing is left without a date."},{"u":"g-s_tickets.html#s2","t":"New appointment","a":"Everything on Appointments","x":"Opens the booking form. Let's have a look."},{"u":"g-s_tickets.html#s3","t":"Visit, phone call or task","a":"Everything on Appointments","x":"Pick what it is, then the customer, what for, date, time and who. The tour \"Book a visit, a phone call or a task\" walks every field."},{"u":"g-s_tickets.html#s4","t":"Close it","a":"Everything on Appointments","x":"Close it without booking."},{"u":"g-s_tickets.html#s5","t":"Mine","a":"Everything on Appointments","x":"Your own open appointments and tasks. The numbers on the tabs are counts."},{"u":"g-s_tickets.html#s6","t":"Search","a":"Everything on Appointments","x":"Find one by subject, customer or place."},{"u":"g-s_tickets.html#s7","t":"By type","a":"Everything on Appointments","x":"Estimate visit, Site visit, Call back, Collection, Service or Other."},{"u":"g-s_tickets.html#s8","t":"Grouped by day","a":"Everything on Appointments","x":"Overdue first in red, then Today, Tomorrow and the days after, with how many on each."},{"u":"g-s_tickets.html#s9","t":"One appointment","a":"Everything on Appointments","x":"The time (or Any time), what it's for, the customer, place and phone, a camera if the visit sent notes or photos, the type and who has it."},{"u":"g-s_tickets.html#s10","t":"Open it","a":"Everything on Appointments","x":"Click the line to open it."},{"u":"g-s_tickets.html#s11","t":"The details","a":"Everything on Appointments","x":"When, with whom, the customer (click the name to open them), phone, address and the office notes."},{"u":"g-s_tickets.html#s12","t":"From the visit","a":"Everything on Appointments","x":"Notes, measurements and photos the salesperson saved on the visit from the phone. Until then it says nothing came back yet."},{"u":"g-s_tickets.html#s13","t":"Edit, visit done, mark done","a":"Everything on Appointments","x":"Edit changes it. Visit done \u00b7 estimate pending puts an estimate visit on Waiting on a quote. Mark done closes it. The tour presses none of them."},{"u":"g-s_tickets.html#s14","t":"Close it","a":"Everything on Appointments","x":"The X closes it."},{"u":"g-s_tickets.html#s15","t":"Edit","a":"Everything on Appointments","x":"The pencil opens the form to change the day, time, person or details."},{"u":"g-s_tickets.html#s16","t":"Mark done","a":"Everything on Appointments","x":"The tick marks it done. It moves to Done \u00b7 30 days."},{"u":"g-s_tickets.html#s17","t":"Everyone","a":"Everything on Appointments","x":"Every open appointment, whoever has it."},{"u":"g-s_tickets.html#s18","t":"By person","a":"Everything on Appointments","x":"Pick one person to see only theirs. It isn't on Mine, which is always yours."},{"u":"g-s_tickets.html#s19","t":"Waiting on a quote","a":"Everything on Appointments","x":"Estimate visits marked Visit done \u00b7 estimate pending: the quote is still to write. Mark the visit done once the estimate has gone out."},{"u":"g-s_tickets.html#s20","t":"Overdue","a":"Everything on Appointments","x":"Everything past its date and still open, for everyone. Call, move it with the pencil, or mark it done."},{"u":"g-s_tickets.html#s21","t":"Done \u00b7 30 days","a":"Everything on Appointments","x":"What was finished in the last 30 days, newest first. The arrow on a line reopens it."},{"u":"g-tickets_new.html","t":"Book a visit, a phone call or a task","a":"Sell","k":"book booking new appointment visit site estimate visit call phone callback call back collection task todo to-do meeting internal assign who with date time priority urgent notes form","v":1},{"u":"g-tickets_new.html#s1","t":"New appointment","a":"Book a visit, a phone call or a task","x":"Opens the booking form. Visits, phone calls and tasks all start here (or from a customer, with their details filled in)."},{"u":"g-tickets_new.html#s2","t":"What is it?","a":"Book a visit, a phone call or a task","x":"Start with what it is: a Visit, a Phone call or a Task. The form changes to fit."},{"u":"g-tickets_new.html#s3","t":"Visit","a":"Book a visit, a phone call or a task","x":"A visit has a place and a time: estimate visits, site visits and service calls."},{"u":"g-tickets_new.html#s4","t":"The customer","a":"Book a visit, a phone call or a task","x":"Type a name, phone or street and pick them. Leave it empty for an internal task or meeting."},{"u":"g-tickets_new.html#s5","t":"What for","a":"Book a visit, a phone call or a task","x":"A short line everyone understands, like \"Estimate visit \u00b7 back patio\". It's required."},{"u":"g-tickets_new.html#s6","t":"Type","a":"Book a visit, a phone call or a task","x":"Estimate visit, Site visit or Service. After an estimate visit it can be marked Visit done \u00b7 estimate pending."},{"u":"g-tickets_new.html#s7","t":"Priority","a":"Book a visit, a phone call or a task","x":"Low, Normal, High or Urgent. High and Urgent show a red tag on the lists."},{"u":"g-tickets_new.html#s8","t":"Date","a":"Book a visit, a phone call or a task","x":"The day it happens. It's also the due date, so it's on that person's day straight away."},{"u":"g-tickets_new.html#s9","t":"From and To","a":"Book a visit, a phone call or a task","x":"Pick a start and the end follows an hour later, or leave it at Any time."},{"u":"g-tickets_new.html#s10","t":"With","a":"Book a visit, a phone call or a task","x":"Who goes. Only people who take appointments are listed (set on Team & crews)."},{"u":"g-tickets_new.html#s11","t":"Notes","a":"Book a visit, a phone call or a task","x":"Anything the person should know: a gate code, what the customer asked for."},{"u":"g-tickets_new.html#s12","t":"Phone call","a":"Book a visit, a phone call or a task","x":"Now let's make it a phone call."},{"u":"g-tickets_new.html#s13","t":"Call at and who calls","a":"Book a visit, a phone call or a task","x":"A call has one time (15 minutes) and Who calls. Its type is Call back or Collection, and the call's subject goes in What the call is about."},{"u":"g-tickets_new.html#s14","t":"Task","a":"Book a visit, a phone call or a task","x":"And a task: any to-do, an internal meeting, an order to place."},{"u":"g-tickets_new.html#s15","t":"Anyone, crews included","a":"Book a visit, a phone call or a task","x":"A task can go to anyone in the company. It shows on their My day and their phone until they mark it done."},{"u":"g-tickets_new.html#s16","t":"Book it","a":"Book a visit, a phone call or a task","x":"Book it saves it onto that person's day; Cancel throws it away. The tour doesn't save anything."},{"u":"g-tickets_new.html#s17","t":"Close it","a":"Book a visit, a phone call or a task","x":"The X closes the form without booking."},{"u":"g-s_estimates.html","t":"Everything on Estimates","a":"Sell","k":"estimates estimate list pipeline quotes quote proposals drafts draft sent won lost follow-ups followup close rate rep salesperson search filter new","v":0},{"u":"g-s_estimates.html#s1","t":"Estimates","a":"Everything on Estimates","x":"Every estimate in one list, from the first visit to the won job: drafts, ones out with customers, follow-ups, won and lost."},{"u":"g-s_estimates.html#s2","t":"Start a new estimate","a":"Everything on Estimates","x":"New estimate first asks who it is for. The tour opens it to show you."},{"u":"g-s_estimates.html#s3","t":"Find the customer","a":"Everything on Estimates","x":"Type a name, phone or street and click the customer: a new draft estimate opens for them straight away."},{"u":"g-s_estimates.html#s4","t":"Not a customer yet?","a":"Everything on Estimates","x":"Add a new customer opens the customer form right here. Saving it adds the customer and opens their new estimate."},{"u":"g-s_estimates.html#s5","t":"Name","a":"Everything on Estimates","x":"First and last name, or a company name for commercial work. Only a name is required."},{"u":"g-s_estimates.html#s6","t":"Phones and email","a":"Everything on Estimates","x":"Cell phone, other phone and email. The email is where the estimate and its follow-ups go."},{"u":"g-s_estimates.html#s7","t":"Property address","a":"Everything on Estimates","x":"Where the work is. Type the zip and the town fills itself in. Untick \"Bill to the property address\" if the bill goes somewhere else."},{"u":"g-s_estimates.html#s8","t":"Source, salesperson and CSR","a":"Everything on Estimates","x":"How they found you, who referred them, their salesperson and the office CSR. Stage, type, invoicing and payment terms sit just below."},{"u":"g-s_estimates.html#s9","t":"Book the visit in the same go","a":"Everything on Estimates","x":"Tick it to put the estimate visit on the salesperson's day with the same save: date, time, who goes and what for."},{"u":"g-s_estimates.html#s10","t":"Save customer","a":"Everything on Estimates","x":"Saves the customer and opens their new estimate. The tour doesn't save anything."},{"u":"g-s_estimates.html#s11","t":"Close the form","a":"Everything on Estimates","x":"The x closes the form without saving."},{"u":"g-s_estimates.html#s12","t":"Drafts","a":"Everything on Estimates","x":"Estimates written but not sent yet, and what they are worth. Click it to see them on the Open tab."},{"u":"g-s_estimates.html#s13","t":"Out with customers","a":"Everything on Estimates","x":"Sent and waiting on a yes or no, with their total value."},{"u":"g-s_estimates.html#s14","t":"In follow-up","a":"Everything on Estimates","x":"Sent estimates with a follow-up due or planned. With automatic follow-ups on, the reminder emails go by themselves."},{"u":"g-s_estimates.html#s15","t":"Won this year","a":"Everything on Estimates","x":"What you won this year, how many jobs that is, and your close rate (won out of won plus lost)."},{"u":"g-s_estimates.html#s16","t":"Open","a":"Everything on Estimates","x":"The list starts on Open: drafts, and sent estimates still waiting on an answer. The number is how many."},{"u":"g-s_estimates.html#s17","t":"Follow-ups","a":"Everything on Estimates","x":"Sent estimates with a follow-up due, or the next automatic email planned."},{"u":"g-s_estimates.html#s18","t":"Who to chase","a":"Everything on Estimates","x":"The Status column says Follow up, 2nd follow-up or Call them, and shows the next automatic step with its date."},{"u":"g-s_estimates.html#s19","t":"Won","a":"Everything on Estimates","x":"Every estimate the customer said yes to."},{"u":"g-s_estimates.html#s20","t":"Straight to the job","a":"Everything on Estimates","x":"Job opens the job that was made from that estimate."},{"u":"g-s_estimates.html#s21","t":"Lost","a":"Everything on Estimates","x":"Lost and expired estimates, with the reason given when they were marked lost."},{"u":"g-s_estimates.html#s22","t":"All","a":"Everything on Estimates","x":"Every estimate, whatever its status."},{"u":"g-s_estimates.html#s23","t":"Search","a":"Everything on Estimates","x":"Type an estimate number, a title, the customer or the town: the list narrows as you type."},{"u":"g-s_estimates.html#s24","t":"Filter by rep","a":"Everything on Estimates","x":"Show one salesperson's estimates only. Any rep shows everyone's."},{"u":"g-s_estimates.html#s25","t":"The columns","a":"Everything on Estimates","x":"Estimate number, title and customer; status; rep; total; and when it was sent. A long list shows 50 at a time with Previous and Next."},{"u":"g-s_estimates.html#s26","t":"Open one","a":"Everything on Estimates","x":"Click any row to open the estimate. The tour \"Everything on an estimate\" walks through it."},{"u":"g-s_estimate.html","t":"Everything on an estimate","a":"Sell","k":"estimate quote proposal open builder sections materials totals customer view copy pdf print send won lost measure duplicate copy contract terms online link follow-ups margin selections details","v":0},{"u":"g-s_estimate.html#s1","t":"Open an estimate","a":"Everything on an estimate","x":"Click a row to open the estimate. The tour opens this one."},{"u":"g-s_estimate.html#s2","t":"Back to the customer","a":"Everything on an estimate","x":"The customer's name above the title opens their page: phones, notes, and all their estimates, jobs and invoices."},{"u":"g-s_estimate.html#s3","t":"Where it stands","a":"Everything on an estimate","x":"The number and status sit above the title. Here: the status (Draft, Sent, Won, Lost), any follow-up due, the address, phone and when it was sent."},{"u":"g-s_estimate.html#s4","t":"Customer view","a":"Everything on an estimate","x":"Switch to see the estimate exactly as the customer gets it."},{"u":"g-s_estimate.html#s5","t":"The real document","a":"Everything on an estimate","x":"The saved copy the customer receives by email, as a PDF or on paper: sections, totals, add-ons and terms. Print / PDF is just above it."},{"u":"g-s_estimate.html#s6","t":"Back to Build","a":"Everything on an estimate","x":"Build is where you write the estimate."},{"u":"g-s_estimate.html#s7","t":"Save","a":"Everything on an estimate","x":"Saves sections, prices and details. \"Unsaved changes\" shows beside it until you do. \u2318S or Ctrl+S saves too."},{"u":"g-s_estimate.html#s8","t":"Send","a":"Everything on an estimate","x":"Opens the send choices: email the online link (best), email it, print or save as PDF, or \"I sent it another way\". Each marks it Sent and starts the follow-ups."},{"u":"g-s_estimate.html#s9","t":"Won","a":"Everything on an estimate","x":"When the customer says yes. One step makes the contract, the payment schedule and the job. The tour \"Mark an estimate won or lost\" shows it."},{"u":"g-s_estimate.html#s10","t":"Lost","a":"Everything on an estimate","x":"When they say no: pick why (price, someone else, timing\u2026). It stays for the close-rate report, and Reopen brings it back as a draft."},{"u":"g-s_estimate.html#s11","t":"Measure","a":"Everything on an estimate","x":"Opens a satellite photo of the property. Trace the patio, driveway, beds or wall line; back here a Measured card turns each area into a section."},{"u":"g-s_estimate.html#s12","t":"Duplicate","a":"Everything on an estimate","x":"Copies this estimate as a new draft for the same customer, e.g. a second option, and opens the copy."},{"u":"g-s_estimate.html#s13","t":"Sections","a":"Everything on an estimate","x":"Each section is one line the customer sees (Patio, Walls, Lighting\u2026) with its own total. The labor price and the materials go inside it."},{"u":"g-s_estimate.html#s14","t":"Taxable or Tax exempt","a":"Everything on an estimate","x":"One click switches the section between Taxable and Tax exempt; the sales tax in Totals follows."},{"u":"g-s_estimate.html#s15","t":"Materials, hidden or shown","a":"Everything on an estimate","x":"The materials in a section. Unticked lines are hidden: the customer sees only the section total. Cost and price give you the margin."},{"u":"g-s_estimate.html#s16","t":"Optional add-ons","a":"Everything on an estimate","x":"A dashed section is an optional add-on: priced on its own and left out of the total until the customer takes it."},{"u":"g-s_estimate.html#s17","t":"Add a section","a":"Everything on an estimate","x":"Search the catalogue: a service brings its price, unit, crew-hours, tax setting and its kit of materials. Blank section starts an empty one."},{"u":"g-s_estimate.html#s18","t":"Totals","a":"Everything on an estimate","x":"Subtotal, sales tax at this estimate's rate and the total. Optional add-ons are shown apart, not in the total."},{"u":"g-s_estimate.html#s19","t":"Customer copy","a":"Everything on an estimate","x":"Open the customer copy shows the document full width; Print / PDF prints it or saves a PDF you can attach to your own email."},{"u":"g-s_estimate.html#s20","t":"Contract terms","a":"Everything on an estimate","x":"The payment schedule the contract gets, what each payment comes to, and the NJ ST-8 capital improvement switch (no sales tax)."},{"u":"g-s_estimate.html#s21","t":"Online estimate","a":"Everything on an estimate","x":"The customer's link: Sent, Opened, Signed. They tick add-ons, initial the terms and sign; signing makes the job, contract and deposit invoice."},{"u":"g-s_estimate.html#s22","t":"Follow-ups","a":"Everything on an estimate","x":"What the automatic follow-up does next and when, with an on / off switch for this estimate. Emails and texts about it are listed here."},{"u":"g-s_estimate.html#s23","t":"Margin","a":"Everything on an estimate","x":"Materials at cost plus crew-hours at your labor cost: cost, gross profit, margin % and crew-hours. Never shown to the customer."},{"u":"g-s_estimate.html#s24","t":"Material selections","a":"Everything on an estimate","x":"What the customer picked at the supplier: pavers, wall block, caps, steps\u2026 It goes on the selection sheet, the proposal and the work order."},{"u":"g-s_estimate.html#s25","t":"Details","a":"Everything on an estimate","x":"Title, salesperson, valid until, tax %, a message to the customer, an office note they never see, and terms. Save keeps your changes."},{"u":"g-estimate_sections.html","t":"Build an estimate: sections, materials, add-ons","a":"Sell","k":"estimate build write sections section materials material line lines kit kits catalogue catalog service price labor labour quantity unit crew hours taxable exempt tax optional addon add-on hidden show move reorder up down remove blank note crew","v":1},{"u":"g-estimate_sections.html#s1","t":"Open an estimate","a":"Build an estimate: sections, materials, add-ons","x":"Sections are built on the estimate. The tour opens this one."},{"u":"g-estimate_sections.html#s2","t":"The section bar","a":"Build an estimate: sections, materials, add-ons","x":"Each section is one line on the estimate. Its bar holds the name, the tax switch, the section total and the tools to fold, move or remove it."},{"u":"g-estimate_sections.html#s3","t":"Fold it away","a":"Build an estimate: sections, materials, add-ons","x":"The arrow folds a section to one line so a long estimate is easy to read. The tax switch and the total stay visible."},{"u":"g-estimate_sections.html#s4","t":"Section name","a":"Build an estimate: sections, materials, add-ons","x":"What the customer reads as the line title, e.g. Paver patio. Every section needs a name before you can save."},{"u":"g-estimate_sections.html#s5","t":"Taxable or Tax exempt","a":"Build an estimate: sections, materials, add-ons","x":"One click switches it; the sales tax follows. The Taxable tick inside the section does the same. Catalogue services bring their own setting."},{"u":"g-estimate_sections.html#s6","t":"Section total","a":"Build an estimate: sections, materials, add-ons","x":"Quantity \u00d7 labor price, plus every material line at its price. It updates as you type."},{"u":"g-estimate_sections.html#s7","t":"Move up or down","a":"Build an estimate: sections, materials, add-ons","x":"The arrows change the order the customer reads the sections in. Nothing is deleted."},{"u":"g-estimate_sections.html#s8","t":"Remove a section","a":"Build an estimate: sections, materials, add-ons","x":"Takes the section and its materials off (it asks first). Nothing is final until you press Save."},{"u":"g-estimate_sections.html#s9","t":"What the customer reads","a":"Build an estimate: sections, materials, add-ons","x":"Describe the work in plain words. This text is printed under the section name on the estimate."},{"u":"g-estimate_sections.html#s10","t":"Quantity and unit","a":"Build an estimate: sections, materials, add-ons","x":"How many, and of what (sq ft, job, ea, ft). After you measure, \"Use a measurement\" buttons appear here and fill both in one click."},{"u":"g-estimate_sections.html#s11","t":"Labor price per unit","a":"Build an estimate: sections, materials, add-ons","x":"Your price for the work, per unit. The materials below are added on top."},{"u":"g-estimate_sections.html#s12","t":"Crew-hours (budget)","a":"Build an estimate: sections, materials, add-ons","x":"How long the crew needs. It sizes the job on the Schedule and feeds the Margin card."},{"u":"g-estimate_sections.html#s13","t":"Optional add-on","a":"Build an estimate: sections, materials, add-ons","x":"Tick it for an extra the customer can choose, like lighting. It's priced apart and kept out of the total until they take it."},{"u":"g-estimate_sections.html#s14","t":"Note for the crew","a":"Build an estimate: sections, materials, add-ons","x":"Gas line, access, where to dump spoils\u2026 It goes on the job and the work order, never on the customer's copy."},{"u":"g-estimate_sections.html#s15","t":"Materials","a":"Build an estimate: sections, materials, add-ons","x":"Material, quantity, unit, your cost, the customer's price and the line amount. Cost stays inside the office; it drives the margin."},{"u":"g-estimate_sections.html#s16","t":"Hidden or shown lines","a":"Build an estimate: sections, materials, add-ons","x":"Unticked (the default), a line is hidden: the customer sees only the section total. Tick Show to list it on their copy, without its price."},{"u":"g-estimate_sections.html#s17","t":"Reorder or remove lines","a":"Build an estimate: sections, materials, add-ons","x":"The arrows move a line up or down; the x removes it."},{"u":"g-estimate_sections.html#s18","t":"Add a material","a":"Build an estimate: sections, materials, add-ons","x":"Search the catalogue by name or category and pick one: it comes in with its unit, cost and price."},{"u":"g-estimate_sections.html#s19","t":"Blank line","a":"Build an estimate: sections, materials, add-ons","x":"For a material that isn't in the catalogue: type the name, quantity, cost and price yourself."},{"u":"g-estimate_sections.html#s20","t":"An optional add-on","a":"Build an estimate: sections, materials, add-ons","x":"Dashed and marked Optional. The customer ticks it on the online link, or you tick it when you press Won."},{"u":"g-estimate_sections.html#s21","t":"Add a section from the catalogue","a":"Build an estimate: sections, materials, add-ons","x":"Pick a service: it brings its price, unit, crew-hours and tax setting, plus its kit of materials (hidden unless the kit says show)."},{"u":"g-estimate_sections.html#s22","t":"Blank section","a":"Build an estimate: sections, materials, add-ons","x":"An empty section to fill in yourself."},{"u":"g-estimate_sections.html#s23","t":"Totals","a":"Build an estimate: sections, materials, add-ons","x":"Subtotal, sales tax on the taxable sections and the total, plus \"Optional add-ons (not in total)\"."},{"u":"g-estimate_sections.html#s24","t":"Margin","a":"Build an estimate: sections, materials, add-ons","x":"Cost, gross profit, margin % and crew-hours, as you build. Never shown to the customer."},{"u":"g-estimate_sections.html#s25","t":"Save it","a":"Build an estimate: sections, materials, add-ons","x":"Nothing is kept until you press Save (or \u2318S / Ctrl+S); \"Unsaved changes\" reminds you. The tour doesn't save."},{"u":"g-estimate_send.html","t":"Send an estimate and follow it up","a":"Sell","k":"send email estimate proposal quote pdf print customer copy online link sign signature signed opened viewed follow up followup reminder automatic resend again update","v":1},{"u":"g-estimate_send.html#s1","t":"Open the estimate","a":"Send an estimate and follow it up","x":"Sending starts on the estimate. The tour opens this one."},{"u":"g-estimate_send.html#s2","t":"Send (or Send again)","a":"Send an estimate and follow it up","x":"Opens: Email the online link (best: they sign on their phone), Email it, Print / save as PDF, or I sent it another way. Each marks it Sent."},{"u":"g-estimate_send.html#s3","t":"Check it first","a":"Send an estimate and follow it up","x":"The Customer copy card shows exactly what they will get."},{"u":"g-estimate_send.html#s4","t":"Open the customer copy","a":"Send an estimate and follow it up","x":"The tour opens it to show you."},{"u":"g-estimate_send.html#s5","t":"The customer's copy","a":"Send an estimate and follow it up","x":"Your letterhead, each section with its total, shown materials, optional add-ons and the terms: exactly what they receive."},{"u":"g-estimate_send.html#s6","t":"Print / PDF","a":"Send an estimate and follow it up","x":"Opens the print window. Choose Save as PDF to attach it to your own email."},{"u":"g-estimate_send.html#s7","t":"Close it","a":"Send an estimate and follow it up","x":"The x closes the copy."},{"u":"g-estimate_send.html#s8","t":"The online estimate","a":"Send an estimate and follow it up","x":"The best way to send: the customer opens a link, ticks the add-ons they want, initials the terms and signs."},{"u":"g-estimate_send.html#s9","t":"Sent, Opened, Signed","a":"Send an estimate and follow it up","x":"Where the customer is. Signing makes the job, the contract and the deposit invoice by itself."},{"u":"g-estimate_send.html#s10","t":"The link","a":"Send an estimate and follow it up","x":"How many add-ons it offers, and the link itself."},{"u":"g-estimate_send.html#s11","t":"Copy the link","a":"Send an estimate and follow it up","x":"Copies it, to paste into a text message or your own email."},{"u":"g-estimate_send.html#s12","t":"See it as they do","a":"Send an estimate and follow it up","x":"Opens the link as the customer sees it."},{"u":"g-estimate_send.html#s13","t":"Email the link again","a":"Send an estimate and follow it up","x":"Re-sends the same link. If you change the estimate after it went out, a yellow note offers Send the update, which replaces their link."},{"u":"g-estimate_send.html#s14","t":"Follow-ups","a":"Send an estimate and follow it up","x":"After sending, reminders go by themselves: email 1, email 2, then a call ticket for the office. Days are set in Automations."},{"u":"g-estimate_send.html#s15","t":"Automatic on or off","a":"Send an estimate and follow it up","x":"Switch automatic follow-ups off for this estimate only; it takes effect at once. The company-wide switch is on Automations."},{"u":"g-estimate_send.html#s16","t":"What happens next","a":"Send an estimate and follow it up","x":"The next automatic step and when it goes. Messages already sent are listed under it. Follow-ups due also show on My day."},{"u":"g-estimate_won.html","t":"Mark an estimate won or lost","a":"Sell","k":"won win accepted yes sold sale lost lose declined no reason reopen expired contract job create add-ons addon payment schedule close rate","v":1},{"u":"g-estimate_won.html#s1","t":"Open the estimate","a":"Mark an estimate won or lost","x":"The one the customer answered. The tour opens this one."},{"u":"g-estimate_won.html#s2","t":"They said yes","a":"Mark an estimate won or lost","x":"Press Won when they accept on the phone, by email or in person. It saves your changes first. The tour opens it to show you."},{"u":"g-estimate_won.html#s3","t":"Which add-ons they took","a":"Mark an estimate won or lost","x":"Tick each optional add-on they want. The contract total and the payments below change as you tick."},{"u":"g-estimate_won.html#s4","t":"What one step creates","a":"Mark an estimate won or lost","x":"The contract (signature required over the amount set in Settings), the payment schedule with each amount, and a job with one work item per section."},{"u":"g-estimate_won.html#s5","t":"Create the job","a":"Mark an estimate won or lost","x":"Press it when it's real: the job opens next and waits on the Schedule. The tour doesn't press it."},{"u":"g-estimate_won.html#s6","t":"Close","a":"Mark an estimate won or lost","x":"Cancel or the x closes it; nothing changes."},{"u":"g-estimate_won.html#s7","t":"They said no","a":"Mark an estimate won or lost","x":"Lost asks why (price, went with someone else, timing / next year, no response, changed plans, other) plus details. It counts in the close rate."},{"u":"g-estimate_won.html#s8","t":"Won estimates","a":"Mark an estimate won or lost","x":"Now one that was won."},{"u":"g-estimate_won.html#s9","t":"Open a won estimate","a":"Mark an estimate won or lost","x":"The tour opens this one."},{"u":"g-estimate_won.html#s10","t":"The won banner","a":"Mark an estimate won or lost","x":"When it was won and the job number. The job, the contract and the payment schedule were all made from it."},{"u":"g-estimate_won.html#s11","t":"Open the job","a":"Mark an estimate won or lost","x":"Goes to the job: schedule it, order materials, follow the payments."},{"u":"g-estimate_won.html#s12","t":"A record now","a":"Mark an estimate won or lost","x":"A won estimate is locked: sections read as a record and each add-on says taken or not taken. Duplicate it if more work comes up."},{"u":"g-estimate_won.html#s13","t":"Lost estimates","a":"Mark an estimate won or lost","x":"And one that was lost."},{"u":"g-estimate_won.html#s14","t":"Open a lost estimate","a":"Mark an estimate won or lost","x":"The tour opens this one."},{"u":"g-estimate_won.html#s15","t":"Why it was lost","a":"Mark an estimate won or lost","x":"The day it was marked lost and the reason given."},{"u":"g-estimate_won.html#s16","t":"Reopen","a":"Mark an estimate won or lost","x":"If they come back (or it expired), Reopen makes it a draft again so you can update it and send it. The tour doesn't press it."},{"u":"g-estimate_terms.html","t":"Payment schedule, tax and ST-8 on an estimate","a":"Sell","k":"payment schedule deposit installments 30 60 10 50 custom split contract terms tax sales taxable exempt st-8 st8 capital improvement new construction valid until expiry","v":1},{"u":"g-estimate_terms.html#s1","t":"Open the estimate","a":"Payment schedule, tax and ST-8 on an estimate","x":"Terms are set on each estimate. The tour opens this one."},{"u":"g-estimate_terms.html#s2","t":"Contract terms","a":"Payment schedule, tax and ST-8 on an estimate","x":"What the customer signs up to if they accept: the payment schedule and whether sales tax applies."},{"u":"g-estimate_terms.html#s3","t":"Pick the payment schedule","a":"Payment schedule, tax and ST-8 on an estimate","x":"The schedules from Settings; the default for this kind of work is already picked. Choosing one saves it on the estimate."},{"u":"g-estimate_terms.html#s4","t":"Each payment, worked out","a":"Payment schedule, tax and ST-8 on an estimate","x":"Deposit, start of work, completion\u2026 with what each comes to and when it's due. They follow the total as you edit."},{"u":"g-estimate_terms.html#s5","t":"A custom split","a":"Payment schedule, tax and ST-8 on an estimate","x":"\"Custom for this estimate\u2026\" opens an editor: start from 30/60/10, 50/50 or deposit + final; set %, fixed $ or the balance, and when each is due."},{"u":"g-estimate_terms.html#s6","t":"NJ ST-8: no sales tax","a":"Payment schedule, tax and ST-8 on an estimate","x":"Switch on for new construction (patio, wall, driveway): no sales tax, and the customer signs an ST-8 to keep on the job. It takes effect at once."},{"u":"g-estimate_terms.html#s7","t":"Terms added from Settings","a":"Payment schedule, tax and ST-8 on an estimate","x":"The standard terms from Settings that print on this estimate. Click the line to read them."},{"u":"g-estimate_terms.html#s8","t":"Tax in the totals","a":"Payment schedule, tax and ST-8 on an estimate","x":"Sales tax is the estimate's Tax % on the taxable sections only. Tax exempt sections, and ST-8 jobs, pay none."},{"u":"g-estimate_terms.html#s9","t":"Tax %","a":"Payment schedule, tax and ST-8 on an estimate","x":"The sales tax rate for this estimate. Change it only for a special case."},{"u":"g-estimate_terms.html#s10","t":"Valid until","a":"Payment schedule, tax and ST-8 on an estimate","x":"How long the price holds. It prints on the estimate."},{"u":"g-estimate_terms.html#s11","t":"Terms for this estimate","a":"Payment schedule, tax and ST-8 on an estimate","x":"Extra terms for this estimate only, printed with it. Press Save to keep them."},{"u":"g-estimate_selections.html","t":"Material selections and approval","a":"Sell","k":"selections selection materials material pavers paver colour color style manufacturer cedar bridge wall block caps steps coping edging stone veneer upgrades sheet sign signed approval approve approved","v":1},{"u":"g-estimate_selections.html#s1","t":"Open the estimate","a":"Material selections and approval","x":"Selections are kept on the estimate. The tour opens one that has some."},{"u":"g-estimate_selections.html#s2","t":"Material selections","a":"Material selections and approval","x":"The customer's picks at the supplier (the Cedar Bridge form). Anyone working on the estimate can fill them in."},{"u":"g-estimate_selections.html#s3","t":"The picks, group by group","a":"Material selections and approval","x":"Pavers, Walls & steps, Stone, edging & extras, and Upgrades. Empty groups are left out."},{"u":"g-estimate_selections.html#s4","t":"The customer's approval","a":"Material selections and approval","x":"Waiting on the customer until they approve. If the picks change after that, they go back for a new approval."},{"u":"g-estimate_selections.html#s5","t":"Record their approval","a":"Material selections and approval","x":"Opens a short form for when they approve. The tour opens it to show you."},{"u":"g-estimate_selections.html#s6","t":"Who approved","a":"Material selections and approval","x":"Their name, filled in with the customer's."},{"u":"g-estimate_selections.html#s7","t":"When and how","a":"Material selections and approval","x":"The date, and how: signed form, email, in person, by phone or online."},{"u":"g-estimate_selections.html#s8","t":"Save approval","a":"Material selections and approval","x":"Keeps it; the card then shows Approved, by whom and how, with Undo. The tour doesn't save."},{"u":"g-estimate_selections.html#s9","t":"Cancel","a":"Material selections and approval","x":"Closes the form without saving."},{"u":"g-estimate_selections.html#s10","t":"The selection sheet","a":"Material selections and approval","x":"The selection form in your letterhead, for the customer to check and sign. The tour opens it."},{"u":"g-estimate_selections.html#s11","t":"Check it","a":"Material selections and approval","x":"Every pick, laid out like the supplier's form. Print / PDF prints it or saves a PDF to email."},{"u":"g-estimate_selections.html#s12","t":"Close it","a":"Material selections and approval","x":"The x closes the sheet."},{"u":"g-estimate_selections.html#s13","t":"Edit the picks","a":"Material selections and approval","x":"Edit (Add selections when there are none) opens the whole form above the estimate."},{"u":"g-estimate_selections.html#s14","t":"Pavers","a":"Material selections and approval","x":"Manufacturer, style, colour, the field paver and the border paver."},{"u":"g-estimate_selections.html#s15","t":"Walls and steps","a":"Material selections and approval","x":"Wall block, wall caps, step treads and pool coping."},{"u":"g-estimate_selections.html#s16","t":"Stone, edging and extras","a":"Material selections and approval","x":"Stepping stones, stone veneer, edge / curbstone, property stone and any extras."},{"u":"g-estimate_selections.html#s17","t":"Upgrades","a":"Material selections and approval","x":"Paver or wall block upgrades, the upgrade colour (Standard, Plus, Premier) and size, or any other upgrade."},{"u":"g-estimate_selections.html#s18","t":"Attach the signed form","a":"Material selections and approval","x":"Upload the customer's signed sheet; it's kept with the selections when you save."},{"u":"g-estimate_selections.html#s19","t":"Save selections","a":"Material selections and approval","x":"Keeps the picks on the estimate, the proposal and the work order. The tour doesn't save."},{"u":"g-estimate_selections.html#s20","t":"Close the form","a":"Material selections and approval","x":"The x (or Cancel) closes it without saving."},{"u":"g-s_measure.html","t":"Everything on Measure","a":"Sell","k":"measure measuring measurement area square feet sq ft length feet aerial satellite photo map trace draw patio driveway walkway lawn beds mulch wall edging cut-out property","v":0},{"u":"g-s_measure.html#s1","t":"Open the estimate","a":"Everything on Measure","x":"Measuring starts from an estimate. The tour opens this one."},{"u":"g-s_measure.html#s2","t":"Measure","a":"Everything on Measure","x":"Opens the Measure screen for this estimate (it saves your changes first). The tour opens it."},{"u":"g-s_measure.html#s3","t":"Which estimate","a":"Everything on Measure","x":"The estimate number and the customer you are measuring for."},{"u":"g-s_measure.html#s4","t":"The property address","a":"Everything on Measure","x":"The satellite photo opens on this address. With no address on the customer, search for the house on the map instead."},{"u":"g-s_measure.html#s5","t":"Back to the estimate","a":"Everything on Measure","x":"Goes back to the estimate. What you drew is kept only if you save it first with Save and go to the estimate, under the map."},{"u":"g-s_measure.html#s6","t":"Customer","a":"Everything on Measure","x":"Opens the customer: phones, notes, gate codes."},{"u":"g-s_measure.html#s7","t":"How to draw","a":"Everything on Measure","x":"Under this note is the satellite photo. Pick what you are measuring, then tap the corners. Tap the first corner again to close the shape."},{"u":"g-s_measure.html#s8","t":"What you can measure","a":"Everything on Measure","x":"Patio / pavers, Driveway, Walkway, Lawn and Beds / mulch as areas in square feet; Wall / edging as a line in feet. Search moves the map."},{"u":"g-s_measure.html#s9","t":"Fix and cut out","a":"Everything on Measure","x":"Drag a corner to adjust a shape. Use Cut-out to take a pool, the house or a bed out of an area."},{"u":"g-s_measure.html#s10","t":"Save it onto the estimate","a":"Everything on Measure","x":"Under the map, What you measured adds it up by kind as you draw. Save and go to the estimate keeps it and takes you back."},{"u":"g-s_measure.html#s11","t":"Then, on the estimate","a":"Everything on Measure","x":"A Measured card lists each area: Add makes it a section, or \"Use a measurement\" in a section fills its quantity. Open comes back here."},{"u":"g-s_marketing.html","t":"Everything on Marketing","a":"Sell","k":"marketing campaign campaigns email emails newsletter season seasonal spring fall cleanup sign-ups signups form forms website requests request leads opted out unsubscribe","v":0},{"u":"g-s_marketing.html#s1","t":"Marketing","a":"Everything on Marketing","x":"Seasonal emails to the right customers, your Spring and Fall cleanup sign-ups, and requests from your website, on one screen."},{"u":"g-s_marketing.html#s2","t":"The numbers","a":"Everything on Marketing","x":"Customers you can reach by email, how many opted out, campaigns sent, cleanup sign-ups waiting and new website requests."},{"u":"g-s_marketing.html#s3","t":"New campaign","a":"Everything on Marketing","x":"Owner and office: starts a blank campaign. Most start from a season card instead. \"Write and send an email campaign\" walks through it."},{"u":"g-s_marketing.html#s4","t":"Live email is off","a":"Everything on Marketing","x":"While this shows, you can write and test campaigns but nothing goes to customers. Live email is switched on in Automations \u2192 Sending setup."},{"u":"g-s_marketing.html#s5","t":"Campaigns","a":"Everything on Marketing","x":"Every campaign you've written, and the season starters."},{"u":"g-s_marketing.html#s6","t":"A campaign","a":"Everything on Marketing","x":"Name, status (Draft, Scheduled, Sending, Sent, Stopped), subject, who made it and when. While sending, a bar shows how many went, wait or failed."},{"u":"g-s_marketing.html#s7","t":"Open a draft","a":"Everything on Marketing","x":"Opens a draft to finish it. While one is going out, Stop is here instead: emails already sent stay sent, the rest are cancelled."},{"u":"g-s_marketing.html#s8","t":"Duplicate","a":"Everything on Marketing","x":"Copies a campaign as a new draft: last fall's email, ready for this fall."},{"u":"g-s_marketing.html#s9","t":"Delete a draft","a":"Everything on Marketing","x":"Deletes a draft you don't need (it asks first). Only drafts can be deleted."},{"u":"g-s_marketing.html#s10","t":"Start from a season","a":"Everything on Marketing","x":"Spring or fall cleanup, paver sealing, next year's project, \"still thinking it over?\" and maintenance plans: each brings its wording and who should get it."},{"u":"g-s_marketing.html#s11","t":"Cleanup sign-ups","a":"Everything on Marketing","x":"Your Spring and Fall Service Request Forms and everyone who signed up, in the order received."},{"u":"g-s_marketing.html#s12","t":"Your forms","a":"Everything on Marketing","x":"One card per season with the sign-ups waiting. The link for your website and emails, with Copy link, appears here once the online forms are on."},{"u":"g-s_marketing.html#s13","t":"See the form","a":"Everything on Marketing","x":"Shows the form question for question, as customers see it. The tour opens it."},{"u":"g-s_marketing.html#s14","t":"What customers fill in","a":"Everything on Marketing","x":"Name, phone, address, the services they want, meet a manager or just a quote, the date they'd like, and any billing or contact changes."},{"u":"g-s_marketing.html#s15","t":"Close it","a":"Everything on Marketing","x":"The x closes the preview."},{"u":"g-s_marketing.html#s16","t":"Someone calls instead","a":"Everything on Marketing","x":"Take a phone sign-up asks the same questions and puts them in line. \"Take a cleanup sign-up on the phone\" shows the form."},{"u":"g-s_marketing.html#s17","t":"Spring or Fall","a":"Everything on Marketing","x":"Switches the list below between the Spring and the Fall sign-ups."},{"u":"g-s_marketing.html#s18","t":"In the order received","a":"Everything on Marketing","x":"Number in line, when and how it came in, the customer, what they want, estimate style, preferred date, and flags: auto-pay call, billing change, note."},{"u":"g-s_marketing.html#s19","t":"Accept","a":"Everything on Marketing","x":"Makes the visit: \"meet a manager\" becomes an estimate visit to book, \"just send a quote\" a stop-by. New people are added as leads."},{"u":"g-s_marketing.html#s20","t":"Dismiss","a":"Everything on Marketing","x":"The x takes a sign-up off the list (a duplicate, a test)."},{"u":"g-s_marketing.html#s21","t":"Website requests","a":"Everything on Marketing","x":"Requests from the form on your website and from campaign buttons."},{"u":"g-s_marketing.html#s22","t":"The request form","a":"Everything on Marketing","x":"Its link, for your website and campaign buttons, with Copy link. It shows once the public form is switched on."},{"u":"g-s_marketing.html#s23","t":"A new request","a":"Everything on Marketing","x":"Name, town, phone, email, the services they want, their message and the best time. Ones that look like spam are flagged."},{"u":"g-s_marketing.html#s24","t":"Accept","a":"Everything on Marketing","x":"Matches an existing customer or adds a new lead, makes a ticket for the visit, and opens the customer."},{"u":"g-s_marketing.html#s25","t":"Dismiss","a":"Everything on Marketing","x":"Spam or not for you. Accepted and dismissed requests move to a Handled list below, with who handled them."},{"u":"g-marketing_campaign.html","t":"Write and send an email campaign","a":"Sell","k":"campaign email emails newsletter blast marketing season seasonal spring fall cleanup promotion write design layout colour color photo picture headline audience segment towns who send test draft","v":1},{"u":"g-marketing_campaign.html#s1","t":"Campaigns","a":"Write and send an email campaign","x":"Campaigns are written here."},{"u":"g-marketing_campaign.html#s2","t":"Start from a season","a":"Write and send an email campaign","x":"Each card brings the wording, a button and who should get it. New campaign starts blank; Open finishes a draft. The tour opens this one."},{"u":"g-marketing_campaign.html#s3","t":"The email","a":"Write and send an email campaign","x":"What the customer reads. The preview on the right changes as you type."},{"u":"g-marketing_campaign.html#s4","t":"Campaign name","a":"Write and send an email campaign","x":"Only the office sees it, e.g. Spring cleanup 2027."},{"u":"g-marketing_campaign.html#s5","t":"Subject line","a":"Write and send an email campaign","x":"What they see in their inbox. {first_name} becomes each customer's first name."},{"u":"g-marketing_campaign.html#s6","t":"The message","a":"Write and send an email campaign","x":"Your own wording. A blank line starts a new paragraph; {first_name}, {company} and {company_phone} are filled in for each customer."},{"u":"g-marketing_campaign.html#s7","t":"The button","a":"Write and send an email campaign","x":"The big button in the email, e.g. Book a spring cleanup, and its link: your request form once it is set up."},{"u":"g-marketing_campaign.html#s8","t":"Design","a":"Write and send an email campaign","x":"How it looks in the inbox: layout, colour, pictures and headline."},{"u":"g-marketing_campaign.html#s9","t":"Layout","a":"Write and send an email campaign","x":"Photo header puts a wide photo of your work on top; Colour banner a coloured band with the headline; Plain is a simple letter."},{"u":"g-marketing_campaign.html#s10","t":"Header picture","a":"Write and send an email campaign","x":"Paste a picture link or press Upload. A wide landscape photo, at least 1200 px across, looks best."},{"u":"g-marketing_campaign.html#s11","t":"Colour banner","a":"Write and send an email campaign","x":"The tour puts the starter's colour banner back."},{"u":"g-marketing_campaign.html#s12","t":"Colour","a":"Write and send an email campaign","x":"Six brand colours for the banner and the button: bay navy, paver red, lawn green, sand gold, slate and violet."},{"u":"g-marketing_campaign.html#s13","t":"Headline","a":"Write and send an email campaign","x":"The big words at the top, and a line under them (e.g. Reserve your spot before April)."},{"u":"g-marketing_campaign.html#s14","t":"A picture in the message","a":"Write and send an email campaign","x":"An optional photo in the body, from a link or Upload. Once it's added, a Caption box appears."},{"u":"g-marketing_campaign.html#s15","t":"Who gets it","a":"Write and send an email campaign","x":"Choose the customers. The count at the bottom updates as you go."},{"u":"g-marketing_campaign.html#s16","t":"Customers or leads","a":"Write and send an email campaign","x":"Customers, Leads, Both, or Inactive customers."},{"u":"g-marketing_campaign.html#s17","t":"Residential or commercial","a":"Write and send an email campaign","x":"Any, Residential or Commercial."},{"u":"g-marketing_campaign.html#s18","t":"Towns","a":"Write and send an email campaign","x":"Click towns to send only there; none picked means everywhere. The number is how many customers each town has."},{"u":"g-marketing_campaign.html#s19","t":"Narrow it down","a":"Write and send an email campaign","x":"Had a kind of work in the last N months, lost an estimate lately, no work lately, on a maintenance plan or not. Demo customers stay out."},{"u":"g-marketing_campaign.html#s20","t":"How many get it","a":"Write and send an email campaign","x":"The count, a few names and a bar by town. Customers who opted out, or have no email, are never included."},{"u":"g-marketing_campaign.html#s21","t":"Send a test first","a":"Write and send an email campaign","x":"Type your email and press Send test to see it in a real inbox. It saves the draft first."},{"u":"g-marketing_campaign.html#s22","t":"Save draft","a":"Write and send an email campaign","x":"Keeps the campaign as a draft to finish later. The tour doesn't save."},{"u":"g-marketing_campaign.html#s23","t":"Send it","a":"Write and send an email campaign","x":"Sends to everyone counted, paced per hour (it asks first, and you can Stop it while it goes out). Greyed out until live email is on."},{"u":"g-marketing_campaign.html#s24","t":"What they'll see","a":"Write and send an email campaign","x":"A live preview with a sample customer's name, updated as you type and design."},{"u":"g-marketing_campaign.html#s25","t":"Back to campaigns","a":"Write and send an email campaign","x":"Leaves the composer. Nothing is kept unless you pressed Save draft."},{"u":"g-marketing_phone_signup.html","t":"Take a cleanup sign-up on the phone","a":"Sell","k":"phone call caller signup sign-up sign up spring fall cleanup clean up request form queue line mulch shrub trimming autopay auto-pay","v":1},{"u":"g-marketing_phone_signup.html#s1","t":"Cleanup sign-ups","a":"Take a cleanup sign-up on the phone","x":"Phone sign-ups are taken here."},{"u":"g-marketing_phone_signup.html#s2","t":"Take a phone sign-up","a":"Take a cleanup sign-up on the phone","x":"On the season's card. The tour opens the Spring one."},{"u":"g-marketing_phone_signup.html#s3","t":"Who is calling","a":"Take a cleanup sign-up on the phone","x":"Name, phone and email. Name and phone are required."},{"u":"g-marketing_phone_signup.html#s4","t":"Where and when","a":"Take a cleanup sign-up on the phone","x":"The service address and town, and their preferred date or time frame (a range, now, a month, no preference)."},{"u":"g-marketing_phone_signup.html#s5","t":"What they want","a":"Take a cleanup sign-up on the phone","x":"Tick the services from your form; Other is for anything not on the list."},{"u":"g-marketing_phone_signup.html#s6","t":"Estimate style","a":"Take a cleanup sign-up on the phone","x":"Meet a manager (an estimate visit is booked) or just send a quote (a stop-by to quote)."},{"u":"g-marketing_phone_signup.html#s7","t":"Auto-pay call","a":"Take a cleanup sign-up on the phone","x":"Spring form: would they like a call about auto-pay? Yes turns into a separate call for the office."},{"u":"g-marketing_phone_signup.html#s8","t":"Billing changes and notes","a":"Take a cleanup sign-up on the phone","x":"A separate billing address or new contact details, and anything else they mention."},{"u":"g-marketing_phone_signup.html#s9","t":"Add to the list","a":"Take a cleanup sign-up on the phone","x":"Adds them in line with their number, like the online form. The tour doesn't save."},{"u":"g-marketing_phone_signup.html#s10","t":"Close the form","a":"Take a cleanup sign-up on the phone","x":"The x (or Cancel) closes it without saving."},{"u":"g-marketing_phone_signup.html#s11","t":"Work the list from #1","a":"Take a cleanup sign-up on the phone","x":"Accept books the estimate visit or the stop-by quote; the x dismisses. Requests are handled in the order received."},{"u":"g-s_jobs.html","t":"Everything on Jobs","a":"Build","k":"jobs job list all sold won project projects status scheduled progress complete completed invoiced paid search find filter tab tabs crew crews value open","v":0},{"u":"g-s_jobs.html#s1","t":"Jobs","a":"Everything on Jobs","x":"Every sold job, from \"to schedule\" to \"paid\". A job is made when an estimate is marked Won, with one work item per estimate section."},{"u":"g-s_jobs.html#s2","t":"Schedule board","a":"Everything on Jobs","x":"Opens the crew board, where each piece of work gets its crew and its days."},{"u":"g-s_jobs.html#s3","t":"To schedule","a":"Everything on Jobs","x":"Jobs with work that has no crew or start day yet. Click the box to list just those jobs."},{"u":"g-s_jobs.html#s4","t":"Scheduled","a":"Everything on Jobs","x":"Jobs on the board, waiting for the crew to start."},{"u":"g-s_jobs.html#s5","t":"In progress","a":"Everything on Jobs","x":"Jobs a crew has started (the crew lead presses Start on the phone, or the office does on the job)."},{"u":"g-s_jobs.html#s6","t":"To invoice","a":"Everything on Jobs","x":"Jobs whose work is all complete but not fully billed yet. Click the box to list them."},{"u":"g-s_jobs.html#s7","t":"Active jobs","a":"Everything on Jobs","x":"The list opens on Active: sold, scheduled and in progress. The number on each tab is how many jobs are in it."},{"u":"g-s_jobs.html#s8","t":"To schedule tab","a":"Everything on Jobs","x":"Jobs with work still to put on the board, approved change orders included."},{"u":"g-s_jobs.html#s9","t":"Complete","a":"Everything on Jobs","x":"Finished jobs waiting to be invoiced."},{"u":"g-s_jobs.html#s10","t":"Invoiced / paid","a":"Everything on Jobs","x":"Jobs that are billed, and the ones paid in full."},{"u":"g-s_jobs.html#s11","t":"All","a":"Everything on Jobs","x":"Every job, whatever its status."},{"u":"g-s_jobs.html#s12","t":"Search the list","a":"Everything on Jobs","x":"Type a job number, title, customer or town. The list filters as you type, inside the tab you are on."},{"u":"g-s_jobs.html#s13","t":"Job, customer, town","a":"Everything on Jobs","x":"The job number and title, with the customer and the town under it."},{"u":"g-s_jobs.html#s14","t":"Status and flags","a":"Everything on Jobs","x":"Sold, Scheduled, In progress, Complete, Invoiced or Paid. Tags: \"1 to schedule\" = work not on the board yet; a red Permit hold = it can't start yet."},{"u":"g-s_jobs.html#s15","t":"Crews","a":"Everything on Jobs","x":"The crews doing the work, each with its colour from the board."},{"u":"g-s_jobs.html#s16","t":"When","a":"Everything on Jobs","x":"The first and last day on the board, or \"not scheduled\"."},{"u":"g-s_jobs.html#s17","t":"Work done","a":"Everything on Jobs","x":"The ring shows work items complete out of the total: 1/3 means one of three is done."},{"u":"g-s_jobs.html#s18","t":"Value","a":"Everything on Jobs","x":"The contract value. Only people who see money see this column and the next one."},{"u":"g-s_jobs.html#s19","t":"Paid so far","a":"Everything on Jobs","x":"How much of the value is paid. The bar turns green when it is paid in full."},{"u":"g-s_jobs.html#s20","t":"Open a job","a":"Everything on Jobs","x":"Click a row to open the job: work, crews, change orders, costs, payments and the folder. The list shows 50 at a time, with Previous / Next under it."},{"u":"g-s_job.html","t":"Everything on a job","a":"Build","k":"job project open detail page work items crew change order orders costing costs profit payment payments schedule folder permit contract terms signature signed working days weekend timeline photos crew time work order print","v":0},{"u":"g-s_job.html#s1","t":"Open the job","a":"Everything on a job","x":"Jobs open from the Jobs list, the Schedule board, the customer or search. Let's open one."},{"u":"g-s_job.html#s2","t":"The job at a glance","a":"Everything on a job","x":"Job number, the estimate it came from, the title, address, phone and who sold it. The link above it goes back to the customer."},{"u":"g-s_job.html#s3","t":"Work order","a":"Everything on a job","x":"Prints the crew's work order: the address, each work item, the crew notes and the materials."},{"u":"g-s_job.html#s4","t":"Schedule board","a":"Everything on a job","x":"Opens the board on the week this job starts."},{"u":"g-s_job.html#s5","t":"Where the job is","a":"Everything on a job","x":"Sold \u2192 Scheduled \u2192 In progress \u2192 Complete \u2192 Invoiced \u2192 Paid. It moves on by itself as work starts, finishes and is billed."},{"u":"g-s_job.html#s6","t":"Contract and signature","a":"Everything on a job","x":"The contract number and whether it is signed. Mark signed records a paper signature (it asks first). Email signing link sends an online one when it is set up."},{"u":"g-s_job.html#s7","t":"Value, billed, paid","a":"Everything on a job","x":"The contract plus approved change orders, what has been invoiced and what has been paid."},{"u":"g-s_job.html#s8","t":"Job costing","a":"Everything on a job","x":"Is this job making money? Margin, profit so far, and estimate vs actual for hours, labor and materials. Tour: \"Check a job's profit and enter its costs\"."},{"u":"g-s_job.html#s9","t":"Work","a":"Everything on a job","x":"One work item per estimate section, each with its crew, hours and days. Schedule, Start and Complete are here. Tour: \"Schedule, start and complete work\"."},{"u":"g-s_job.html#s10","t":"Change orders","a":"Everything on a job","x":"Extra work the customer asks for, priced and signed on its own. Approved ones become work items and add to the job's value. Tour: \"Price and approve a change order\"."},{"u":"g-s_job.html#s11","t":"Costs","a":"Everything on a job","x":"Material bills, vendor invoices, subcontractors, equipment, dump fees and permits bought for this job. They feed the profit above."},{"u":"g-s_job.html#s12","t":"Crew time","a":"Everything on a job","x":"Each person's hours on this job, day by day: time on site plus their share of the yard, loading and travel time."},{"u":"g-s_job.html#s13","t":"From the crew","a":"Everything on a job","x":"What the crew lead's phone recorded: start and finish with the time, photos and how far they were from the address."},{"u":"g-s_job.html#s14","t":"Job timeline","a":"Everything on a job","x":"Everything that happened on the job, newest first: scheduled, moved, started, change orders, invoices, payments."},{"u":"g-s_job.html#s15","t":"Payments","a":"Everything on a job","x":"The payment schedule: invoice each step in one click, see what is paid and what is due next. Tour: \"Invoice a job's payment schedule\"."},{"u":"g-s_job.html#s16","t":"Job folder","a":"Everything on a job","x":"The paper cover sheet, ticked by itself as things happen: start date, contract emailed and signed, payments, permit, final bill, inspection."},{"u":"g-s_job.html#s17","t":"Contract terms","a":"Everything on a job","x":"The payment schedule in words, the NJ ST-8 for a capital improvement (no sales tax), and whether the customer gets \"you're on the schedule\" emails."},{"u":"g-s_job.html#s18","t":"Working days","a":"Everything on a job","x":"Long jobs skip weekends unless you switch Saturdays or Sundays on for this job. Tour: \"Keep the job folder, permit and terms\"."},{"u":"g-s_job.html#s19","t":"Cards that come and go","a":"Everything on a job","x":"Only when they apply: a red Permit hold banner, Maintenance plan, Bill tracked time, Material selections, Customer survey. Help lists a tour for each part of the job."},{"u":"g-job_work.html","t":"Schedule, start and complete work on a job","a":"Build","k":"work item items schedule reschedule start started complete completed finish finished done reopen crew crews crew-hours hours days add extra remove materials crew note capacity job","v":1},{"u":"g-job_work.html#s1","t":"Open the job","a":"Schedule, start and complete work on a job","x":"Work items live on the job. Let's open one."},{"u":"g-job_work.html#s2","t":"Work items","a":"Schedule, start and complete work on a job","x":"One item per estimate section and per approved change order, each with its own crew, crew-hours and days."},{"u":"g-job_work.html#s3","t":"Add work","a":"Schedule, start and complete work on a job","x":"For extra work that is not on the estimate."},{"u":"g-job_work.html#s4","t":"What","a":"Schedule, start and complete work on a job","x":"Say what the work is, e.g. Extra steps."},{"u":"g-job_work.html#s5","t":"Crew-hours","a":"Schedule, start and complete work on a job","x":"The hours the crew needs in total. The board turns them into days using the crew's hours a day."},{"u":"g-job_work.html#s6","t":"Crew","a":"Schedule, start and complete work on a job","x":"Who does it. You can leave it and pick the crew when you schedule it."},{"u":"g-job_work.html#s7","t":"Add it","a":"Schedule, start and complete work on a job","x":"Add puts it on the job and in the \"To schedule\" list on the board. The tour doesn't press it."},{"u":"g-job_work.html#s8","t":"Close the form","a":"Schedule, start and complete work on a job","x":"The x closes the form without saving anything."},{"u":"g-job_work.html#s9","t":"One work item","a":"Schedule, start and complete work on a job","x":"Crew colour, the name, work order number, crew, crew-hours, hours the crew logged and photos, then its status."},{"u":"g-job_work.html#s10","t":"Its days","a":"Schedule, start and complete work on a job","x":"The days it is booked. A red \"over\" day means the crew has more hours than it can do that day: move this or the other work."},{"u":"g-job_work.html#s11","t":"Reopen","a":"Schedule, start and complete work on a job","x":"On a finished item: puts it back in progress when the crew has to go back."},{"u":"g-job_work.html#s12","t":"Complete","a":"Schedule, start and complete work on a job","x":"Marks the item done. When the last item is done the job turns Complete, ready to invoice. The crew lead can also do it on the phone."},{"u":"g-job_work.html#s13","t":"Materials","a":"Schedule, start and complete work on a job","x":"Click Materials to see what this item needs. A tick means the crew loaded it."},{"u":"g-job_work.html#s14","t":"Reschedule","a":"Schedule, start and complete work on a job","x":"Opens the schedule form for this item. On an item not on the board yet the button says Schedule."},{"u":"g-job_work.html#s15","t":"Crew","a":"Schedule, start and complete work on a job","x":"Pick the crew; each shows its speciality."},{"u":"g-job_work.html#s16","t":"Start day","a":"Schedule, start and complete work on a job","x":"The first day on site."},{"u":"g-job_work.html#s17","t":"Budgeted crew-hours","a":"Schedule, start and complete work on a job","x":"The hours budgeted. The days are these hours \u00f7 the crew's hours a day."},{"u":"g-job_work.html#s18","t":"Or set the days","a":"Schedule, start and complete work on a job","x":"Leave 0 to work the days out from the hours, or type the number of days."},{"u":"g-job_work.html#s19","t":"The days it takes","a":"Schedule, start and complete work on a job","x":"A preview of the days. Weekends are skipped unless the job works them (Working days card)."},{"u":"g-job_work.html#s20","t":"Take it off the board","a":"Schedule, start and complete work on a job","x":"Puts the item back in the To schedule list."},{"u":"g-job_work.html#s21","t":"Book the days","a":"Schedule, start and complete work on a job","x":"Schedule books it and tells you if the crew goes over capacity on any day. The tour doesn't press it."},{"u":"g-job_work.html#s22","t":"Close the form","a":"Schedule, start and complete work on a job","x":"The x closes the form without saving anything."},{"u":"g-job_work.html#s23","t":"Not on the board yet","a":"Schedule, start and complete work on a job","x":"An item with no days says \"Not on the schedule yet\" and has a Schedule button: the same form."},{"u":"g-job_work.html#s24","t":"Remove an item","a":"Schedule, start and complete work on a job","x":"The bin removes an item that has not started (it asks first). It comes off the schedule too."},{"u":"g-job_work.html#s25","t":"Crew note","a":"Schedule, start and complete work on a job","x":"A note for the crew on this item, from the estimate or a change order. It shows on their phone."},{"u":"g-job_work.html#s26","t":"Open the job","a":"Schedule, start and complete work on a job","x":"Now a job that is booked but not started, to see Start."},{"u":"g-job_work.html#s27","t":"Start","a":"Schedule, start and complete work on a job","x":"Marks the item in progress (the crew lead usually does it on the phone). A job on Permit hold shows a red tag instead and can't start."},{"u":"g-job_changes.html","t":"Price and approve a change order","a":"Build","k":"change order orders co extra additional more work price priced sign signed approve approved decline declined print customer extension","v":1},{"u":"g-job_changes.html#s1","t":"Open the job","a":"Price and approve a change order","x":"Change orders live on the job. Let's open one."},{"u":"g-job_changes.html#s2","t":"Change orders","a":"Price and approve a change order","x":"Extra work the customer asks for, each priced and signed on its own and kept apart from the original contract."},{"u":"g-job_changes.html#s3","t":"Start one","a":"Price and approve a change order","x":"New change order starts a draft on this job straight away (CO-1, CO-2 \u2026), ready to fill in. The tour doesn't press it."},{"u":"g-job_changes.html#s4","t":"An approved one","a":"Price and approve a change order","x":"The stamp shows its state: Draft, With customer, Approved or Declined. Then the lines, crew-hours, who approved it and how it is billed."},{"u":"g-job_changes.html#s5","t":"Print it","a":"Price and approve a change order","x":"Prints the approved change order. If it was billed on its own invoice, a button opens that invoice."},{"u":"g-job_changes.html#s6","t":"A draft","a":"Price and approve a change order","x":"A draft, or one with the customer, can still change: Edit, Print, Approved, and the x for declined."},{"u":"g-job_changes.html#s7","t":"Edit","a":"Price and approve a change order","x":"Opens it to write the lines."},{"u":"g-job_changes.html#s8","t":"Title","a":"Price and approve a change order","x":"A short name the customer understands, e.g. Patio extension."},{"u":"g-job_changes.html#s9","t":"Estimated crew-hours","a":"Price and approve a change order","x":"Becomes the crew's hour budget on the work item once it is approved."},{"u":"g-job_changes.html#s10","t":"The lines","a":"Price and approve a change order","x":"What changes, quantity, price, your cost (never shown to the customer) and the Tax tick. The x removes a line; the total before tax is under it."},{"u":"g-job_changes.html#s11","t":"Add a line","a":"Price and approve a change order","x":"Adds another line."},{"u":"g-job_changes.html#s12","t":"Save it","a":"Price and approve a change order","x":"Saves the lines. Tax follows the job (none on an ST-8 job). The tour doesn't press it."},{"u":"g-job_changes.html#s13","t":"Close without saving","a":"Price and approve a change order","x":"Cancel closes the editor."},{"u":"g-job_changes.html#s14","t":"Give it to the customer","a":"Price and approve a change order","x":"Print prints it and marks it \"With customer\"."},{"u":"g-job_changes.html#s15","t":"The customer agreed","a":"Price and approve a change order","x":"Approved asks who approved it and how to bill it: with the final invoice, now on its own invoice, in the final payment or spread over the payments left."},{"u":"g-job_changes.html#s16","t":"The customer said no","a":"Price and approve a change order","x":"Marks it Declined (it asks first). It stays on the job; a declined one can be deleted."},{"u":"g-job_changes.html#s17","t":"It becomes work","a":"Price and approve a change order","x":"Once approved it is a CO work item with its own hours, scheduled like any other work. Its price adds to the job. You can attach the signed copy when approving."},{"u":"g-job_costing.html","t":"Check a job's profit and enter its costs","a":"Build","k":"costing cost costs profit margin money making losing labor labour material materials subcontractor sub vendor bill bills receipt expense burn rate crew time hours estimate actual budget over","v":1},{"u":"g-job_costing.html#s1","t":"Open the job","a":"Check a job's profit and enter its costs","x":"Profit and costs are on the job. Let's open one."},{"u":"g-job_costing.html#s2","t":"Job costing","a":"Check a job's profit and enter its costs","x":"Running numbers while the job is on, final numbers once it is complete. They move as the crew logs time and costs come in."},{"u":"g-job_costing.html#s3","t":"Margin and profit","a":"Check a job's profit and enter its costs","x":"The ring is the margin. Beside it: gross profit so far (or the estimated profit before work starts), the revenue with change orders, and the estimated margin."},{"u":"g-job_costing.html#s4","t":"Where the money goes","a":"Check a job's profit and enter its costs","x":"The top bar is actual: labor, materials, subs, other, and what is left as profit. The bar under it is the estimate. The colour key is below."},{"u":"g-job_costing.html#s5","t":"Estimate vs actual","a":"Check a job's profit and enter its costs","x":"Crew hours, labor, materials, subcontractors, other and total cost: estimated, actual and the difference (red = over the estimate)."},{"u":"g-job_costing.html#s6","t":"By work item","a":"Check a job's profit and enter its costs","x":"Opens the same comparison for each work item; change orders are marked CO."},{"u":"g-job_costing.html#s7","t":"Profit report","a":"Check a job's profit and enter its costs","x":"Opens Reports \u2192 Job costing with every job side by side. The burn rates that price labor are set there."},{"u":"g-job_costing.html#s8","t":"Costs","a":"Check a job's profit and enter its costs","x":"Everything bought for this job. Add bills as they come in and the profit above updates."},{"u":"g-job_costing.html#s9","t":"Add a cost","a":"Check a job's profit and enter its costs","x":"Opens the cost form."},{"u":"g-job_costing.html#s10","t":"Kind","a":"Check a job's profit and enter its costs","x":"Materials, Subcontractor, Equipment, Dump / disposal, Permit or Other."},{"u":"g-job_costing.html#s11","t":"Vendor","a":"Check a job's profit and enter its costs","x":"Who you paid, e.g. Cedar Bridge Landscape Supply."},{"u":"g-job_costing.html#s12","t":"Amount","a":"Check a job's profit and enter its costs","x":"What it cost. A credit can go in as a minus amount."},{"u":"g-job_costing.html#s13","t":"Their invoice # and date","a":"Check a job's profit and enter its costs","x":"The vendor's invoice number (you are warned if it is on this job twice) and the date beside it."},{"u":"g-job_costing.html#s14","t":"For (optional)","a":"Check a job's profit and enter its costs","x":"Leave it on the whole job, or charge it to one work item or an approved change order."},{"u":"g-job_costing.html#s15","t":"Description","a":"Check a job's profit and enter its costs","x":"What it was, e.g. 12 pallets Techo-Bloc, 4 t stone dust."},{"u":"g-job_costing.html#s16","t":"Attach receipt","a":"Check a job's profit and enter its costs","x":"Attach a photo or PDF of the bill."},{"u":"g-job_costing.html#s17","t":"Save the cost","a":"Check a job's profit and enter its costs","x":"Add cost saves it against the job. The tour doesn't press it."},{"u":"g-job_costing.html#s18","t":"Close the form","a":"Check a job's profit and enter its costs","x":"The x closes the form without saving anything."},{"u":"g-job_costing.html#s19","t":"Change a cost","a":"Check a job's profit and enter its costs","x":"The pencil opens a cost to correct it."},{"u":"g-job_costing.html#s20","t":"Remove a cost","a":"Check a job's profit and enter its costs","x":"The bin takes it off the job's costs (it asks first)."},{"u":"g-job_costing.html#s21","t":"Crew time by person","a":"Check a job's profit and enter its costs","x":"Each day, each person: hours on site + their share of yard and travel time, and what it cost."},{"u":"g-job_payments.html","t":"Invoice a job's payment schedule","a":"Build","k":"payment payments schedule deposit milestone milestones invoice invoices bill billing balance paid owed due next step edit percent signing completion final","v":1},{"u":"g-job_payments.html#s1","t":"Open the job","a":"Invoice a job's payment schedule","x":"The payment schedule is on the job. Let's open one."},{"u":"g-job_payments.html#s2","t":"Payments","a":"Invoice a job's payment schedule","x":"The payment schedule from the contract. Invoice each payment in one click when it is due."},{"u":"g-job_payments.html#s3","t":"The totals","a":"Invoice a job's payment schedule","x":"Contract (with change orders), invoiced, paid and remaining, then the next payment due and when."},{"u":"g-job_payments.html#s4","t":"Each payment","a":"Invoice a job's payment schedule","x":"A tick once paid, then the name, the %, when it is due, Invoiced or Not invoiced yet, and the amount."},{"u":"g-job_payments.html#s5","t":"Open its invoice","a":"Invoice a job's payment schedule","x":"Once a payment is invoiced, this opens the invoice to send it or record a payment."},{"u":"g-job_payments.html#s6","t":"Invoice a payment","a":"Invoice a job's payment schedule","x":"Makes a draft invoice for that payment and opens it to check and send. Once the job is complete, \"Invoice the balance\" bills what is left."},{"u":"g-job_payments.html#s7","t":"Change the schedule","a":"Invoice a job's payment schedule","x":"Edit schedule re-plans the payments still to bill (owner and office)."},{"u":"g-job_payments.html#s8","t":"Invoiced ones are locked","a":"Invoice a job's payment schedule","x":"Payments already invoiced stay as they are. The ones below share what is still to bill."},{"u":"g-job_payments.html#s9","t":"Start from a preset","a":"Invoice a job's payment schedule","x":"One click fills a common schedule; then adjust it."},{"u":"g-job_payments.html#s10","t":"One payment","a":"Invoice a job's payment schedule","x":"Its name; the arrows move it up or down and x removes it. Then % of the rest, a fixed $ or the balance, and when it is due."},{"u":"g-job_payments.html#s11","t":"Add a payment","a":"Invoice a job's payment schedule","x":"Adds another payment."},{"u":"g-job_payments.html#s12","t":"Save it","a":"Invoice a job's payment schedule","x":"Checks it adds up to what is left, then saves. The tour doesn't press it."},{"u":"g-job_payments.html#s13","t":"Leave it as it was","a":"Invoice a job's payment schedule","x":"Cancel closes the editor."},{"u":"g-job_payments.html#s14","t":"Invoices on this job","a":"Invoice a job's payment schedule","x":"Every invoice for this job with its status. Click one to open it."},{"u":"g-job_payments.html#s15","t":"Also in the job folder","a":"Invoice a job's payment schedule","x":"The folder lists each payment again with how it was paid, for the paper file."},{"u":"g-job_folder.html","t":"Keep the job folder, permit and terms","a":"Build","k":"folder cover sheet permit permits township approval approved inspection final municipality lbt st-8 st8 tax exempt capital improvement contract terms notify email date weekend weekends saturday sunday working days time billing tracked account tagged","v":1},{"u":"g-job_folder.html#s1","t":"Open the job","a":"Keep the job folder, permit and terms","x":"The folder is on the job. Let's open one."},{"u":"g-job_folder.html#s2","t":"The job folder","a":"Keep the job folder, permit and terms","x":"The paper cover sheet, kept up to date by itself from the contract, payments and invoices. You tick the rest here."},{"u":"g-job_folder.html#s3","t":"Filled in by itself","a":"Keep the job folder, permit and terms","x":"Start date, contract emailed, signed contract, the ST-8, each payment and the final bill tick themselves as they happen."},{"u":"g-job_folder.html#s4","t":"Ticked by you","a":"Keep the job folder, permit and terms","x":"Account tagged, the permit and the final inspection are filled in with the pencil (Edit the folder)."},{"u":"g-job_folder.html#s5","t":"Contract and payments","a":"Keep the job folder, permit and terms","x":"The contract plus change orders, then each payment: paid (and how), part paid or not paid yet."},{"u":"g-job_folder.html#s6","t":"Print the cover sheet","a":"Keep the job folder, permit and terms","x":"Prints it like the paper one, for the job file."},{"u":"g-job_folder.html#s7","t":"Edit the folder","a":"Keep the job folder, permit and terms","x":"Dates the system can't know go in here."},{"u":"g-job_folder.html#s8","t":"Account tagged","a":"Keep the job folder, permit and terms","x":"Tick it once the account is tagged."},{"u":"g-job_folder.html#s9","t":"Permit needed","a":"Keep the job folder, permit and terms","x":"Then the job can't start until the permit is approved: a red Permit hold banner on the job (Mark the permit approved) and a lock on the board."},{"u":"g-job_folder.html#s10","t":"Time and materials","a":"Keep the job folder, permit and terms","x":"Bills the crew's on-site man-hours. A \"Bill tracked time\" card then shows: enter the rate per man-hour, then Make the invoice (a line per day)."},{"u":"g-job_folder.html#s11","t":"Emailed contract on","a":"Keep the job folder, permit and terms","x":"Blank = the day the estimate went out. Type a date if the contract went another day."},{"u":"g-job_folder.html#s12","t":"Permit #","a":"Keep the job folder, permit and terms","x":"The township's permit number."},{"u":"g-job_folder.html#s13","t":"Permit fee","a":"Keep the job folder, permit and terms","x":"Goes on the final invoice, or press Bill now on the folder to bill it on its own."},{"u":"g-job_folder.html#s14","t":"Permit status","a":"Keep the job folder, permit and terms","x":"To apply for, Applied, Approved, Inspection booked, Passed, Failed inspection or Not needed."},{"u":"g-job_folder.html#s15","t":"Municipality","a":"Keep the job folder, permit and terms","x":"Long Beach Twp, Stafford, Ship Bottom \u2026"},{"u":"g-job_folder.html#s16","t":"Permit dates","a":"Keep the job folder, permit and terms","x":"Applied for on, Approved on, and the next inspection."},{"u":"g-job_folder.html#s17","t":"Inspection notes","a":"Keep the job folder, permit and terms","x":"What the inspector said, or what is booked."},{"u":"g-job_folder.html#s18","t":"Final inspection","a":"Keep the job folder, permit and terms","x":"Its date and your initials. A complete permit job without one shows \"Call for the final inspection\" on the folder."},{"u":"g-job_folder.html#s19","t":"Notes","a":"Keep the job folder, permit and terms","x":"Anything else for the folder."},{"u":"g-job_folder.html#s20","t":"Save the folder","a":"Keep the job folder, permit and terms","x":"Save folder keeps it. The tour doesn't press it."},{"u":"g-job_folder.html#s21","t":"Close the form","a":"Keep the job folder, permit and terms","x":"The x closes the form without saving anything."},{"u":"g-job_folder.html#s22","t":"Contract terms","a":"Keep the job folder, permit and terms","x":"The payment schedule in words. On a capital improvement an ST-8 box shows: no sales tax, so upload the customer's signed NJ ST-8 there."},{"u":"g-job_folder.html#s23","t":"Tell the customer their date","a":"Keep the job folder, permit and terms","x":"Auto follows the type of work. On or Off sets it for this job: On sends a \"you're on the schedule\" email when the date is set or moves. It saves at once."},{"u":"g-job_folder.html#s24","t":"Work weekends?","a":"Keep the job folder, permit and terms","x":"Switch on Saturdays or Sundays for this job. It saves at once and the scheduled days move to match."},{"u":"g-job_extras.html","t":"See a job's maintenance plan and survey","a":"Build","k":"maintenance plan visit visits recurring survey score rating review happy unhappy feedback customer selections selection material","v":1},{"u":"g-job_extras.html#s1","t":"Open the job","a":"See a job's maintenance plan and survey","x":"A maintenance plan keeps its visits on a job of its own. Let's open one."},{"u":"g-job_extras.html#s2","t":"Maintenance plan","a":"See a job's maintenance plan and survey","x":"The plan's number, service and how often. Each visit is a work item on this job. Open goes to the Maintenance screen."},{"u":"g-job_extras.html#s3","t":"One item per visit","a":"See a job's maintenance plan and survey","x":"The plan books each visit; Reschedule or Start it like any other work."},{"u":"g-job_extras.html#s4","t":"Finished jobs","a":"See a job's maintenance plan and survey","x":"Now a finished job."},{"u":"g-job_extras.html#s5","t":"Open the job","a":"See a job's maintenance plan and survey","x":"The survey shows once a job is done."},{"u":"g-job_extras.html#s6","t":"Customer survey","a":"See a job's maintenance plan and survey","x":"After the job the customer gets a survey. Their score shows here; 3 or less opens a ticket to call them."},{"u":"g-job_extras.html#s7","t":"Material selections","a":"See a job's maintenance plan and survey","x":"When the estimate has the customer's picks, a Material selections card shows above Working days: approved or not, Selection sheet and Print / PDF."},{"u":"g-s_schedule.html","t":"Everything on the Schedule","a":"Build","k":"schedule board calendar dispatch crew crews assign drag drop move reschedule rain week weeks month today capacity over overloaded legend colour colours color appointments waiting queue pick","v":0},{"u":"g-s_schedule.html#s1","t":"The Schedule board","a":"Everything on the Schedule","x":"Crews down the side, days across, two weeks at a time. Every sold piece of work gets its crew and its days here."},{"u":"g-s_schedule.html#s2","t":"Move through the weeks","a":"Everything on the Schedule","x":"The arrows go back or forward a week; Today comes back to this week."},{"u":"g-s_schedule.html#s3","t":"Board or month","a":"Everything on the Schedule","x":"Crews \u00b7 2 weeks is this board; Month shows the whole month. We'll look at Month at the end."},{"u":"g-s_schedule.html#s4","t":"To schedule","a":"Everything on the Schedule","x":"Every sold piece of work without a crew and a start day waits here, approved change orders too."},{"u":"g-s_schedule.html#s5","t":"Waiting work","a":"Everything on the Schedule","x":"Job colour, work name, customer, job number, town, crew-hours and when it was sold. A red Permit hold tag: it can be booked but can't start yet."},{"u":"g-s_schedule.html#s6","t":"Schedule it from here","a":"Everything on the Schedule","x":"The calendar button opens the schedule form."},{"u":"g-s_schedule.html#s7","t":"Crew","a":"Everything on the Schedule","x":"Pick the crew."},{"u":"g-s_schedule.html#s8","t":"Start","a":"Everything on the Schedule","x":"The first day on site."},{"u":"g-s_schedule.html#s9","t":"Budgeted crew-hours","a":"Everything on the Schedule","x":"Days = these hours \u00f7 the crew's hours a day. A preview of the days shows under the form."},{"u":"g-s_schedule.html#s10","t":"Days","a":"Everything on the Schedule","x":"Or type the number of days yourself (0 = from the hours)."},{"u":"g-s_schedule.html#s11","t":"Book it","a":"Everything on the Schedule","x":"Schedule books it and tells you if the crew goes over capacity on any day. The tour doesn't press it."},{"u":"g-s_schedule.html#s12","t":"Close the form","a":"Everything on the Schedule","x":"The x closes the form without saving anything."},{"u":"g-s_schedule.html#s13","t":"Or drag it","a":"Everything on the Schedule","x":"Drag a card onto a crew's start day and the form opens there. Or click the card to pick it, like this \u2026"},{"u":"g-s_schedule.html#s14","t":"\u2026 then click the day","a":"Everything on the Schedule","x":"\u2026 then click the crew's start day on the board: the form opens with that crew and day."},{"u":"g-s_schedule.html#s15","t":"Put it back","a":"Everything on the Schedule","x":"Click the picked card again to let go of it."},{"u":"g-s_schedule.html#s16","t":"Appointments row","a":"Everything on the Schedule","x":"How many sales visits and tasks there are each day, and whose. Hover for the times."},{"u":"g-s_schedule.html#s17","t":"A crew","a":"Everything on the Schedule","x":"Crew colour, name, lead and how many crew-hours it can do in a day."},{"u":"g-s_schedule.html#s18","t":"Booked work","a":"Everything on the Schedule","x":"One colour per job, the same every day it runs (\u21b3 = continues). Click it to open the job; drag it to another day or crew to move it. A multi-day job moves together."},{"u":"g-s_schedule.html#s19","t":"How full the day is","a":"Everything on the Schedule","x":"The line under a day is the crew's load against what it can do. Faded blocks are done; work that has started can't be dragged."},{"u":"g-s_schedule.html#s20","t":"Over capacity","a":"Everything on the Schedule","x":"A red outline: the crew is booked for more hours than it can do that day. Move something to another day or crew."},{"u":"g-s_schedule.html#s21","t":"What the colours mean","a":"Everything on the Schedule","x":"Bars: one colour per job, faded = done. Each crew's colour and hours a day, the red over-capacity outline, and the lock for a permit hold."},{"u":"g-s_schedule.html#s22","t":"Month view","a":"Everything on the Schedule","x":"Shows the whole month."},{"u":"g-s_schedule.html#s23","t":"The month","a":"Everything on the Schedule","x":"Here a colour is a crew (the key is above). Click a bar to open the job; drag it to another day to move it."},{"u":"g-s_schedule.html#s24","t":"Other months","a":"Everything on the Schedule","x":"The arrows go a month back or forward; This month comes back."},{"u":"g-s_schedule.html#s25","t":"Back to the board","a":"Everything on the Schedule","x":"Crews \u00b7 2 weeks goes back to the crew board."},{"u":"g-s_maintenance.html","t":"Everything on Maintenance","a":"Build","k":"maintenance recurring plan plans agreement agreements contract lawn mowing mow weekly cleanup cleanups spring fall bed beds snow visit visits skip rain season billing month end monthly increase price","v":0},{"u":"g-s_maintenance.html#s1","t":"Maintenance","a":"Everything on Maintenance","x":"Recurring work: lawn care, beds, spring and fall cleanups, snow. Plans put their own visits on the crew's schedule weeks ahead."},{"u":"g-s_maintenance.html#s2","t":"The numbers","a":"Everything on Maintenance","x":"Active plans and visits this week. People who see money also see the yearly value and what is ready to bill."},{"u":"g-s_maintenance.html#s3","t":"Yearly increase","a":"Everything on Maintenance","x":"Owner and office: raise every plan's price from a date and email each customer. Tour: \"Raise maintenance prices for the year\"."},{"u":"g-s_maintenance.html#s4","t":"New plan","a":"Everything on Maintenance","x":"Starts a plan; first pick the customer."},{"u":"g-s_maintenance.html#s5","t":"Find the customer","a":"Everything on Maintenance","x":"Type a name, phone or street and click them; the plan form opens. Tour: \"Set up or change a maintenance plan\"."},{"u":"g-s_maintenance.html#s6","t":"Close the form","a":"Everything on Maintenance","x":"The x closes it without starting a plan."},{"u":"g-s_maintenance.html#s7","t":"Plans","a":"Everything on Maintenance","x":"Every plan; the number on each tab is how many. Visits and Billing are next to it."},{"u":"g-s_maintenance.html#s8","t":"Customer","a":"Everything on Maintenance","x":"Who the plan is for, and where."},{"u":"g-s_maintenance.html#s9","t":"Service and how often","a":"Everything on Maintenance","x":"Weekly, every 2 weeks, monthly, quarterly, spring + fall or snow (on call), and the day of the week."},{"u":"g-s_maintenance.html#s10","t":"Season","a":"Everything on Maintenance","x":"The months it runs are green; the mark is this month. Visits only go on the schedule in season."},{"u":"g-s_maintenance.html#s11","t":"Crew","a":"Everything on Maintenance","x":"The crew that does the visits. With No crew, no visits get booked."},{"u":"g-s_maintenance.html#s12","t":"Price","a":"Everything on Maintenance","x":"Per visit, a month (fixed monthly fee), or not billed here."},{"u":"g-s_maintenance.html#s13","t":"Next visit","a":"Everything on Maintenance","x":"The next booked visit and how many are done this year, or on call, needs a crew, out of season."},{"u":"g-s_maintenance.html#s14","t":"Status","a":"Everything on Maintenance","x":"Active, Paused or Ended."},{"u":"g-s_maintenance.html#s15","t":"Open a plan","a":"Everything on Maintenance","x":"Click a plan to change it, move or skip a visit, pause or end it."},{"u":"g-s_maintenance.html#s16","t":"Visits","a":"Everything on Maintenance","x":"This week and next, day by day."},{"u":"g-s_maintenance.html#s17","t":"The visit board","a":"Everything on Maintenance","x":"Each visit is coloured by its crew; faded = done. Click a visit to open the customer."},{"u":"g-s_maintenance.html#s18","t":"Billing","a":"Everything on Maintenance","x":"Month-end billing for maintenance."},{"u":"g-s_maintenance.html#s19","t":"Bill up to","a":"Everything on Maintenance","x":"Finished visits and monthly fees up to this date. Change it and the list updates."},{"u":"g-s_maintenance.html#s20","t":"Who gets billed","a":"Everything on Maintenance","x":"One draft invoice per customer: a line per finished visit, or the monthly fee for each month in season."},{"u":"g-s_maintenance.html#s21","t":"Make the invoices","a":"Everything on Maintenance","x":"Creates the draft invoices; check and send them from Invoices. The tour doesn't press it."},{"u":"g-s_maintenance.html#s22","t":"Back to the plans","a":"Everything on Maintenance","x":"Plans is where most of the work is."},{"u":"g-maintenance_plan.html","t":"Set up or change a maintenance plan","a":"Build","k":"maintenance plan new add create set up lawn mowing mow weekly biweekly monthly quarterly cleanup spring fall season day weekday crew price billing skip move visit pause resume end stop snow catalogue","v":1},{"u":"g-maintenance_plan.html#s1","t":"New plan","a":"Set up or change a maintenance plan","x":"Starts a plan for a customer (a customer's page can start one too)."},{"u":"g-maintenance_plan.html#s2","t":"Pick the customer","a":"Set up or change a maintenance plan","x":"Type a name, phone or street and click the customer; the plan form opens."},{"u":"g-maintenance_plan.html#s3","t":"Close the form","a":"Set up or change a maintenance plan","x":"The x closes it without starting a plan."},{"u":"g-maintenance_plan.html#s4","t":"Open a plan","a":"Set up or change a maintenance plan","x":"An existing plan opens in the same form. Let's open one."},{"u":"g-maintenance_plan.html#s5","t":"Service","a":"Set up or change a maintenance plan","x":"What the plan is, e.g. Weekly lawn care."},{"u":"g-maintenance_plan.html#s6","t":"From the catalogue","a":"Set up or change a maintenance plan","x":"Click a catalogue item to fill in the service name and its price."},{"u":"g-maintenance_plan.html#s7","t":"How often","a":"Set up or change a maintenance plan","x":"Weekly, every 2 weeks, monthly, quarterly, spring + fall, or Snow (on call: add a visit when it snows; pricing is on the Snow screen)."},{"u":"g-maintenance_plan.html#s8","t":"Crew","a":"Set up or change a maintenance plan","x":"The crew that does the visits."},{"u":"g-maintenance_plan.html#s9","t":"Day of the week","a":"Set up or change a maintenance plan","x":"The day the visits fall on, or Any."},{"u":"g-maintenance_plan.html#s10","t":"Season","a":"Set up or change a maintenance plan","x":"Season from and to; the strip under it shows the months. No visits outside the season."},{"u":"g-maintenance_plan.html#s11","t":"Start and end","a":"Set up or change a maintenance plan","x":"When the plan starts, and an end date if it has one."},{"u":"g-maintenance_plan.html#s12","t":"Crew-hours a visit","a":"Set up or change a maintenance plan","x":"How long a visit takes. It counts against the crew's day on the board."},{"u":"g-maintenance_plan.html#s13","t":"Price","a":"Set up or change a maintenance plan","x":"The price per visit, or the monthly fee."},{"u":"g-maintenance_plan.html#s14","t":"Billing","a":"Set up or change a maintenance plan","x":"Each finished visit (billed at month end), a fixed monthly fee in season, or not billed here."},{"u":"g-maintenance_plan.html#s15","t":"Note for the crew","a":"Set up or change a maintenance plan","x":"Gate code, dog, what to skip \u2026 It shows on the crew's phone."},{"u":"g-maintenance_plan.html#s16","t":"Tell the customer","a":"Set up or change a maintenance plan","x":"Emails the customer the date of the first visit. Handy for cleanups; leave it off for weekly mowing."},{"u":"g-maintenance_plan.html#s17","t":"Next visits","a":"Set up or change a maintenance plan","x":"The next dates the plan will book. They change as you change the settings."},{"u":"g-maintenance_plan.html#s18","t":"Booked visits","a":"Set up or change a maintenance plan","x":"Visits already on the schedule."},{"u":"g-maintenance_plan.html#s19","t":"Move a visit","a":"Set up or change a maintenance plan","x":"Move puts a visit on another day (a rain day)."},{"u":"g-maintenance_plan.html#s20","t":"Skip a visit","a":"Set up or change a maintenance plan","x":"Skip drops that visit; it stays skipped and won't come back."},{"u":"g-maintenance_plan.html#s21","t":"Save the plan","a":"Set up or change a maintenance plan","x":"Save plan (Create plan for a new one) books its visits. The tour doesn't press it."},{"u":"g-maintenance_plan.html#s22","t":"Pause","a":"Set up or change a maintenance plan","x":"Pause takes the future visits off; Resume brings the plan back."},{"u":"g-maintenance_plan.html#s23","t":"End the plan","a":"Set up or change a maintenance plan","x":"Future visits come off the schedule; finished visits can still be billed. It asks first."},{"u":"g-maintenance_plan.html#s24","t":"Close the form","a":"Set up or change a maintenance plan","x":"The x closes the form without saving anything."},{"u":"g-maintenance_increase.html","t":"Raise maintenance prices for the year","a":"Build","k":"yearly annual increase uplift raise price prices rate rates maintenance plan plans agreement percent new year notice letter","v":1},{"u":"g-maintenance_increase.html#s1","t":"Yearly increase","a":"Raise maintenance prices for the year","x":"Raises every maintenance plan due its increase, in one go."},{"u":"g-maintenance_increase.html#s2","t":"Increase","a":"Raise maintenance prices for the year","x":"The % to add. Leave it blank to use each plan's own % (5% unless set)."},{"u":"g-maintenance_increase.html#s3","t":"Starting","a":"Raise maintenance prices for the year","x":"From this date visits not billed yet take the new price."},{"u":"g-maintenance_increase.html#s4","t":"Tell the customers","a":"Raise maintenance prices for the year","x":"Emails each customer who has an email their new price."},{"u":"g-maintenance_increase.html#s5","t":"Which plans","a":"Raise maintenance prices for the year","x":"Each plan due: last increase, price now, new price, %. Untick any to skip. Per-storm snow plans are left out."},{"u":"g-maintenance_increase.html#s6","t":"Apply it","a":"Raise maintenance prices for the year","x":"Apply the increase shows the yearly value before and after and asks first. The tour doesn't press it."},{"u":"g-maintenance_increase.html#s7","t":"Close the form","a":"Raise maintenance prices for the year","x":"The x closes the form without saving anything."},{"u":"g-s_deliveries.html","t":"Everything on Deliveries","a":"Build","k":"deliveries delivery driver drivers truck run runs material dumpster dumpsters container containers roll-off rolloff yard week calendar whiteboard drop pickup swap late","v":0},{"u":"g-s_deliveries.html#s1","t":"Deliveries","a":"Everything on Deliveries","x":"The drivers' week (instead of the Google Calendar and the whiteboard) and every dumpster: where it is and who has it."},{"u":"g-s_deliveries.html#s2","t":"Pick the week","a":"Everything on Deliveries","x":"The arrows go back or forward a week."},{"u":"g-s_deliveries.html#s3","t":"New run","a":"Everything on Deliveries","x":"Books a material delivery, or a container drop, pickup, swap or move. Tour: \"Book a delivery or container run\"."},{"u":"g-s_deliveries.html#s4","t":"Runs today","a":"Everything on Deliveries","x":"Runs still to do today, and which drivers have them."},{"u":"g-s_deliveries.html#s5","t":"This week","a":"Everything on Deliveries","x":"All the runs this week and how many are done."},{"u":"g-s_deliveries.html#s6","t":"Containers out","a":"Everything on Deliveries","x":"Containers at customers, out of all of them; the rest are in the yard."},{"u":"g-s_deliveries.html#s7","t":"Full or late","a":"Everything on Deliveries","x":"Containers the customer says are full, waiting for pickup. With none, it counts late runs: earlier days not done, also listed in a red banner."},{"u":"g-s_deliveries.html#s8","t":"The drivers' week","a":"Everything on Deliveries","x":"A row per driver, a column per day (Sunday only when a run is on it). Not assigned holds runs with no driver yet."},{"u":"g-s_deliveries.html#s9","t":"A run","a":"Everything on Deliveries","x":"Time, container number, customer, and what it is with the truck. The edge colour is the kind of run; done runs are faded with a tick."},{"u":"g-s_deliveries.html#s10","t":"Drag to move","a":"Everything on Deliveries","x":"Drag a run to another day or driver to move it; the driver's phone follows. Done runs stay put."},{"u":"g-s_deliveries.html#s11","t":"Add a run on a day","a":"Everything on Deliveries","x":"The + in a day starts a run for that driver and day."},{"u":"g-s_deliveries.html#s12","t":"Open a run","a":"Everything on Deliveries","x":"Click a run to see all of it."},{"u":"g-s_deliveries.html#s13","t":"The details","a":"Everything on Deliveries","x":"What, when, driver, truck, customer, address, container, job, load and notes; once done, who did it and when."},{"u":"g-s_deliveries.html#s14","t":"Edit","a":"Everything on Deliveries","x":"Changes the run (the same form as New run)."},{"u":"g-s_deliveries.html#s15","t":"Mark done","a":"Everything on Deliveries","x":"For when the driver couldn't on the phone. A drop asks which container went out; the container moves with the run."},{"u":"g-s_deliveries.html#s16","t":"Cancel run","a":"Everything on Deliveries","x":"Cancels the run (it asks first)."},{"u":"g-s_deliveries.html#s17","t":"Customer","a":"Everything on Deliveries","x":"Opens the customer."},{"u":"g-s_deliveries.html#s18","t":"Close the form","a":"Everything on Deliveries","x":"The x closes the form without saving anything."},{"u":"g-s_deliveries.html#s19","t":"Container yard","a":"Everything on Deliveries","x":"Every dumpster / roll-off: its number, size, where it is and what's next. Tour: \"Track dumpsters\"."},{"u":"g-s_deliveries.html#s20","t":"Out","a":"Everything on Deliveries","x":"Containers at customers, full ones too."},{"u":"g-s_deliveries.html#s21","t":"Yard","a":"Everything on Deliveries","x":"Ready to go."},{"u":"g-s_deliveries.html#s22","t":"Repair","a":"Everything on Deliveries","x":"Out of service."},{"u":"g-s_deliveries.html#s23","t":"All","a":"Everything on Deliveries","x":"Back to all of them."},{"u":"g-s_deliveries.html#s24","t":"Add container","a":"Everything on Deliveries","x":"A new dumpster: its number, size and notes."},{"u":"g-s_deliveries.html#s25","t":"A container","a":"Everything on Deliveries","x":"Size, number, status (In the yard, Out, Full \u00b7 pickup due, Repair), customer and address, days out and the next run. Click it for history and actions."},{"u":"g-deliveries_run.html","t":"Book a delivery or container run","a":"Build","k":"delivery deliver deliveries material materials pallets stone run runs book schedule driver truck dumpster container drop pickup pick up swap dump move haul customer address load","v":1},{"u":"g-deliveries_run.html#s1","t":"New run","a":"Book a delivery or container run","x":"Opens the run form."},{"u":"g-deliveries_run.html#s2","t":"What kind of run","a":"Book a delivery or container run","x":"Material delivery, drop a container, pick one up, swap (dump and bring it back), move one, or any other run."},{"u":"g-deliveries_run.html#s3","t":"Day","a":"Book a delivery or container run","x":"The day of the run."},{"u":"g-deliveries_run.html#s4","t":"Time","a":"Book a delivery or container run","x":"The start time."},{"u":"g-deliveries_run.html#s5","t":"Takes","a":"Book a delivery or container run","x":"How long it keeps the driver busy: 30 minutes up to all day."},{"u":"g-deliveries_run.html#s6","t":"Driver","a":"Book a delivery or container run","x":"Only drivers are listed. Leave it empty and the run goes under Not assigned."},{"u":"g-deliveries_run.html#s7","t":"Customer","a":"Book a delivery or container run","x":"Search by name, phone or street and pick them from the list; the address becomes theirs."},{"u":"g-deliveries_run.html#s8","t":"Address","a":"Book a delivery or container run","x":"Only if it is not the customer's address: a job site, a second property \u2026"},{"u":"g-deliveries_run.html#s9","t":"A container run","a":"Book a delivery or container run","x":"For a drop, pickup, swap or move the form asks which container."},{"u":"g-deliveries_run.html#s10","t":"Container","a":"Book a delivery or container run","x":"For a drop: one from the yard, or leave it for the driver. For a pickup, swap or move: the one at the customer."},{"u":"g-deliveries_run.html#s11","t":"Truck","a":"Book a delivery or container run","x":"Which truck (from Fleet)."},{"u":"g-deliveries_run.html#s12","t":"Load / what for","a":"Book a delivery or container run","x":"For a delivery, the load (6 pallets pavers, 22 t QP). For a container, what it is for."},{"u":"g-deliveries_run.html#s13","t":"Notes for the driver","a":"Book a delivery or container run","x":"Gate code, where to put it \u2026 The driver sees it on the phone."},{"u":"g-deliveries_run.html#s14","t":"Book it","a":"Book a delivery or container run","x":"Schedule run saves it and the driver sees it on the phone. You are warned if the truck or container is busy. The tour doesn't press it."},{"u":"g-deliveries_run.html#s15","t":"Close the form","a":"Book a delivery or container run","x":"The x closes the form without saving anything."},{"u":"g-deliveries_run.html#s16","t":"Quicker: + on a day","a":"Book a delivery or container run","x":"The + in a driver's day opens the same form for that day and driver."},{"u":"g-deliveries_run.html#s17","t":"From a container","a":"Book a delivery or container run","x":"A container's card books runs too: Schedule pickup or Swap for one that is out, Drop it at a customer for one in the yard."},{"u":"g-deliveries_containers.html","t":"Track dumpsters: drop, pick up, swap","a":"Build","k":"dumpster dumpsters container containers roll-off rolloff yard full pickup pick up swap drop repair service history where customer add number size","v":1},{"u":"g-deliveries_containers.html#s1","t":"Container yard","a":"Track dumpsters: drop, pick up, swap","x":"Every dumpster / roll-off, where it is and what is next."},{"u":"g-deliveries_containers.html#s2","t":"Filter","a":"Track dumpsters: drop, pick up, swap","x":"All, Out, Yard or Repair, with how many are in each."},{"u":"g-deliveries_containers.html#s3","t":"Add container","a":"Track dumpsters: drop, pick up, swap","x":"Adds a new dumpster."},{"u":"g-deliveries_containers.html#s4","t":"Number","a":"Track dumpsters: drop, pick up, swap","x":"Its own number, e.g. D-18."},{"u":"g-deliveries_containers.html#s5","t":"Size","a":"Track dumpsters: drop, pick up, swap","x":"10, 15, 20, 30 or 40 yards."},{"u":"g-deliveries_containers.html#s6","t":"Notes","a":"Track dumpsters: drop, pick up, swap","x":"Anything worth knowing about it."},{"u":"g-deliveries_containers.html#s7","t":"Save it","a":"Track dumpsters: drop, pick up, swap","x":"Save adds it to the yard. The tour doesn't press it."},{"u":"g-deliveries_containers.html#s8","t":"Close the form","a":"Track dumpsters: drop, pick up, swap","x":"The x closes the form without saving anything."},{"u":"g-deliveries_containers.html#s9","t":"One that is out","a":"Track dumpsters: drop, pick up, swap","x":"Click it to see where it is and what it has done."},{"u":"g-deliveries_containers.html#s10","t":"Where it is","a":"Track dumpsters: drop, pick up, swap","x":"Status, size, customer, address, job, out since (and how many days) and the next run."},{"u":"g-deliveries_containers.html#s11","t":"History","a":"Track dumpsters: drop, pick up, swap","x":"Every drop, pickup, swap, move and repair, with who and when."},{"u":"g-deliveries_containers.html#s12","t":"Schedule pickup","a":"Track dumpsters: drop, pick up, swap","x":"Books a pickup run with the customer and address filled in."},{"u":"g-deliveries_containers.html#s13","t":"Swap","a":"Track dumpsters: drop, pick up, swap","x":"Books a swap: dump it and bring it back."},{"u":"g-deliveries_containers.html#s14","t":"Customer says full","a":"Track dumpsters: drop, pick up, swap","x":"Marks it Full \u00b7 pickup due; it shows on the Full box at the top."},{"u":"g-deliveries_containers.html#s15","t":"Edit","a":"Track dumpsters: drop, pick up, swap","x":"Change the number, size or notes. Owner and office can remove one that is in the yard."},{"u":"g-deliveries_containers.html#s16","t":"Close the form","a":"Track dumpsters: drop, pick up, swap","x":"The x closes the form without saving anything."},{"u":"g-deliveries_containers.html#s17","t":"One in the yard","a":"Track dumpsters: drop, pick up, swap","x":"Ready to go."},{"u":"g-deliveries_containers.html#s18","t":"Drop it at a customer","a":"Track dumpsters: drop, pick up, swap","x":"Books a drop run with this container."},{"u":"g-deliveries_containers.html#s19","t":"Needs repair","a":"Track dumpsters: drop, pick up, swap","x":"Takes it out of service."},{"u":"g-deliveries_containers.html#s20","t":"Close the form","a":"Track dumpsters: drop, pick up, swap","x":"The x closes the form without saving anything."},{"u":"g-deliveries_containers.html#s21","t":"One in repair","a":"Track dumpsters: drop, pick up, swap","x":"Out of service."},{"u":"g-deliveries_containers.html#s22","t":"Back in service","a":"Track dumpsters: drop, pick up, swap","x":"Puts it back in the yard, ready to go."},{"u":"g-deliveries_containers.html#s23","t":"Close the form","a":"Track dumpsters: drop, pick up, swap","x":"The x closes the form without saving anything."},{"u":"g-deliveries_containers.html#s24","t":"Full \u00b7 pickup due","a":"Track dumpsters: drop, pick up, swap","x":"The customer says it is full. Book its pickup or a swap from its card."},{"u":"g-s_snow.html","t":"Everything on Snow","a":"Build","k":"snow ice plow plowing salt salting calcium walks shovel shoveling storm log logbook visit visits accumulation inches hourly bill billing invoice snowfall","v":0},{"u":"g-s_snow.html#s1","t":"Snow","a":"Everything on Snow","x":"The snow log and snow billing: how many properties, visits logged and what is ready to bill."},{"u":"g-s_snow.html#s2","t":"Log a visit","a":"Everything on Snow","x":"For a visit the crew didn't log on the phone, or from the paper snow log."},{"u":"g-s_snow.html#s3","t":"Property","a":"Everything on Snow","x":"The property, from its snow plan."},{"u":"g-s_snow.html#s4","t":"Date","a":"Everything on Snow","x":"The day of the visit."},{"u":"g-s_snow.html#s5","t":"Storm","a":"Everything on Snow","x":"Name the storm to group its visits (e.g. February 8 storm). Blank groups them by date."},{"u":"g-s_snow.html#s6","t":"Snowfall","a":"Everything on Snow","x":"Inches at the property. Snowfall pricing uses the biggest per storm."},{"u":"g-s_snow.html#s7","t":"Time in and out","a":"Everything on Snow","x":"When the crew arrived and left, and how many men; hourly pricing uses them."},{"u":"g-s_snow.html#s8","t":"Truck, driver, crew","a":"Everything on Snow","x":"Which plow truck, who drove, and the crew."},{"u":"g-s_snow.html#s9","t":"What was done","a":"Everything on Snow","x":"Plowed the lot, Salted, Shoveled walks, Calcium."},{"u":"g-s_snow.html#s10","t":"Salt, ice melt, loader","a":"Everything on Snow","x":"How much salt and ice melt went down, and the loader hours."},{"u":"g-s_snow.html#s11","t":"Site condition","a":"Everything on Snow","x":"How it was left, e.g. Clear \u00b7 icy spots by the door."},{"u":"g-s_snow.html#s12","t":"Save the visit","a":"Everything on Snow","x":"Log visit saves it to the log. The tour doesn't press it."},{"u":"g-s_snow.html#s13","t":"Close the form","a":"Everything on Snow","x":"The x closes the form without saving anything."},{"u":"g-s_snow.html#s14","t":"Bill snow","a":"Everything on Snow","x":"One draft invoice per customer for every unbilled visit on a priced plan (it asks first). Check and send them from Invoices."},{"u":"g-s_snow.html#s15","t":"A storm","a":"Everything on Snow","x":"Visits grouped by storm: the date, how many properties and visits, billed or not, and the biggest snowfall."},{"u":"g-s_snow.html#s16","t":"A visit","a":"Everything on Snow","x":"Property, times, hours, men, truck, driver, whether it came from the crew app, the site condition, what was done, and any photos."},{"u":"g-s_snow.html#s17","t":"Change a visit","a":"Everything on Snow","x":"Opens the visit in the same form."},{"u":"g-s_snow.html#s18","t":"Remove a visit","a":"Everything on Snow","x":"Removes it (it asks first). A billed visit shows its invoice number instead and can't change."},{"u":"g-s_snow.html#s19","t":"Snow plans","a":"Everything on Snow","x":"One plan per property, made on Maintenance (how often: Snow). New plan takes you there."},{"u":"g-s_snow.html#s20","t":"Visits to bill","a":"Everything on Snow","x":"Logged visits on that property not billed yet. A yellow banner warns when a plan has no pricing."},{"u":"g-s_snow.html#s21","t":"Pricing","a":"Everything on Snow","x":"How the property is billed: by snowfall or by the hour. Tour: \"Price snow by snowfall or by the hour\"."},{"u":"g-s_snow.html#s22","t":"To bill","a":"Everything on Snow","x":"Each customer's total ready to bill, priced from their plan."},{"u":"g-s_snow.html#s23","t":"See the lines","a":"Everything on Snow","x":"Click a customer to see each visit's line and price."},{"u":"g-snow_pricing.html","t":"Price snow by snowfall or by the hour","a":"Build","k":"snow price pricing rate rates accumulation inches band bands tier tiers hourly hour per storm salt calcium walks plow truck loader ice melt","v":1},{"u":"g-snow_pricing.html#s1","t":"Open the pricing","a":"Price snow by snowfall or by the hour","x":"The $ next to a snow plan."},{"u":"g-snow_pricing.html#s2","t":"Two ways to bill","a":"Price snow by snowfall or by the hour","x":"By snowfall: a price per storm by how much fell. By the hour: men \u00d7 hours, plus truck, loader, salt and ice melt."},{"u":"g-snow_pricing.html#s3","t":"Labor per man-hour","a":"Price snow by snowfall or by the hour","x":"Each visit bills men \u00d7 hours at this rate."},{"u":"g-snow_pricing.html#s4","t":"Truck and loader","a":"Price snow by snowfall or by the hour","x":"The plow truck and loader rates per hour."},{"u":"g-snow_pricing.html#s5","t":"Salt, ice melt, walks","a":"Price snow by snowfall or by the hour","x":"Salt per ton and ice melt per bag (by what was used), and a price per visit for walks."},{"u":"g-snow_pricing.html#s6","t":"By snowfall","a":"Price snow by snowfall or by the hour","x":"Switch to snowfall pricing."},{"u":"g-snow_pricing.html#s7","t":"Snowfall bands","a":"Price snow by snowfall or by the hour","x":"A price per storm for each band (0\" to 1.99\", 2\" to 3.99\" \u2026). The x removes a band."},{"u":"g-snow_pricing.html#s8","t":"Add a band","a":"Price snow by snowfall or by the hour","x":"Adds the next band."},{"u":"g-snow_pricing.html#s9","t":"Each inch over","a":"Price snow by snowfall or by the hour","x":"Above the last band, this is added for every started inch."},{"u":"g-snow_pricing.html#s10","t":"Salt, calcium, walks","a":"Price snow by snowfall or by the hour","x":"A price each time you salt or put down calcium, and per visit for walks (blank if included)."},{"u":"g-snow_pricing.html#s11","t":"Save it","a":"Price snow by snowfall or by the hour","x":"Save pricing keeps it; visits on this plan can then be billed. The tour doesn't press it."},{"u":"g-snow_pricing.html#s12","t":"Close the form","a":"Price snow by snowfall or by the hour","x":"The x closes the form without saving anything."},{"u":"g-s_timesheets.html","t":"Everything on Timesheets","a":"Build","k":"timesheet timesheets time hours payroll overtime ot clock clock-in clock-out missed punch approve approval adp export week crew tracker job tracker print break yard travel","v":0},{"u":"g-s_timesheets.html#s1","t":"Timesheets","a":"Everything on Timesheets","x":"Each person's week from the crew app: every part of the day, paid hours, overtime after 40 h, missed clock-outs. Breaks are unpaid."},{"u":"g-s_timesheets.html#s2","t":"Pick the week","a":"Everything on Timesheets","x":"The arrows go back or forward a week. This week shows up when you are on an older week."},{"u":"g-s_timesheets.html#s3","t":"Add time","a":"Everything on Timesheets","x":"Adds a forgotten punch or a paper timesheet. Tour: \"Fix a missed clock-out or add time\"."},{"u":"g-s_timesheets.html#s4","t":"Approve the week","a":"Everything on Timesheets","x":"Approves everyone whose week has no missed clock-out. Payroll gets approved hours only."},{"u":"g-s_timesheets.html#s5","t":"Weekly job tracker","a":"Everything on Timesheets","x":"The paper landscape job tracker, filled in from the crew app: each day, each job with start, end, men and man-hours."},{"u":"g-s_timesheets.html#s6","t":"Crew","a":"Everything on Timesheets","x":"One crew, or all of them."},{"u":"g-s_timesheets.html#s7","t":"Print","a":"Everything on Timesheets","x":"Prints the tracker."},{"u":"g-s_timesheets.html#s8","t":"Close the form","a":"Everything on Timesheets","x":"The x closes the form without saving anything."},{"u":"g-s_timesheets.html#s9","t":"ADP export","a":"Everything on Timesheets","x":"Shows the approved week as pay data for ADP Workforce Now, to copy or download. Set the ADP company code under Settings first."},{"u":"g-s_timesheets.html#s10","t":"Paid hours","a":"Everything on Timesheets","x":"Paid hours for everyone this week (breaks left out)."},{"u":"g-s_timesheets.html#s11","t":"Overtime","a":"Everything on Timesheets","x":"Hours past 40 in the week, across all jobs."},{"u":"g-s_timesheets.html#s12","t":"On jobs","a":"Everything on Timesheets","x":"The share of paid time on site. Yard, loading and travel are shared across the day's jobs for costing."},{"u":"g-s_timesheets.html#s13","t":"Missed clock-outs","a":"Everything on Timesheets","x":"Missed clock-outs to fix before approving. When there are none, how many people are approved."},{"u":"g-s_timesheets.html#s14","t":"The colours","a":"Everything on Timesheets","x":"Yard, Loading, Travel, On a job, Unloading, Break. Click a block in a ribbon to correct it; \u270e = corrected by the office."},{"u":"g-s_timesheets.html#s15","t":"One person's week","a":"Everything on Timesheets","x":"Name, ADP file #, paid hours (regular + OT), hours on jobs, shop, travel and breaks. Click the row to fold or open the days."},{"u":"g-s_timesheets.html#s16","t":"Their state","a":"Everything on Timesheets","x":"Missed clock-out (fix it first), To approve, or Approved."},{"u":"g-s_timesheets.html#s17","t":"Approve one person","a":"Everything on Timesheets","x":"Approves just this person's week. An approved week shows an undo arrow instead."},{"u":"g-s_timesheets.html#s18","t":"ADP file #","a":"Everything on Timesheets","x":"The person's file number in ADP; the export uses it."},{"u":"g-s_timesheets.html#s19","t":"File #","a":"Everything on Timesheets","x":"Type it as it is in ADP Workforce Now."},{"u":"g-s_timesheets.html#s20","t":"Save it","a":"Everything on Timesheets","x":"Save keeps it. The tour doesn't press it."},{"u":"g-s_timesheets.html#s21","t":"Close the form","a":"Everything on Timesheets","x":"The x closes the form without saving anything."},{"u":"g-s_timesheets.html#s22","t":"A day as a ribbon","a":"Everything on Timesheets","x":"5 am to 9 pm; each block is a part of the day, and the day's paid total is on the right. Hover a block for its times and job."},{"u":"g-s_timesheets.html#s23","t":"A missed clock-out","a":"Everything on Timesheets","x":"The red dashed block never closed. Click it to put in the real end time."},{"u":"g-timesheets_fix.html","t":"Fix a missed clock-out or add time","a":"Build","k":"missed clock clock-out clockout forgot forgotten punch fix correct correction edit time add paper timesheet phone dead hours wrong job","v":1},{"u":"g-timesheets_fix.html#s1","t":"A missed clock-out","a":"Fix a missed clock-out or add time","x":"Click the red dashed block."},{"u":"g-timesheets_fix.html#s2","t":"No clock-out","a":"Fix a missed clock-out or add time","x":"It says when the block started and that it was never closed."},{"u":"g-timesheets_fix.html#s3","t":"What","a":"Fix a missed clock-out or add time","x":"Yard, Loading, Travel, On a job, Unloading or Break."},{"u":"g-timesheets_fix.html#s4","t":"Start","a":"Fix a missed clock-out or add time","x":"When it started, on the company clock (Eastern)."},{"u":"g-timesheets_fix.html#s5","t":"End","a":"Fix a missed clock-out or add time","x":"When they really finished. For a block still running, leave it empty."},{"u":"g-timesheets_fix.html#s6","t":"Job","a":"Fix a missed clock-out or add time","x":"For On a job: which job. The hours go to that job's costing."},{"u":"g-timesheets_fix.html#s7","t":"Why","a":"Fix a missed clock-out or add time","x":"Why it changed, e.g. Forgot to clock out; left at 4:30 per the lead. The original times are kept too."},{"u":"g-timesheets_fix.html#s8","t":"Remove this entry","a":"Fix a missed clock-out or add time","x":"Takes the block off their week (it asks first)."},{"u":"g-timesheets_fix.html#s9","t":"Save the correction","a":"Fix a missed clock-out or add time","x":"Save correction marks it \u270e. If the week was approved, approve it again. The tour doesn't press it."},{"u":"g-timesheets_fix.html#s10","t":"Close the form","a":"Fix a missed clock-out or add time","x":"The x closes the form without saving anything."},{"u":"g-timesheets_fix.html#s11","t":"Add time","a":"Fix a missed clock-out or add time","x":"For a forgotten punch or a paper timesheet."},{"u":"g-timesheets_fix.html#s12","t":"Who","a":"Fix a missed clock-out or add time","x":"The person."},{"u":"g-timesheets_fix.html#s13","t":"Day","a":"Fix a missed clock-out or add time","x":"The day."},{"u":"g-timesheets_fix.html#s14","t":"What","a":"Fix a missed clock-out or add time","x":"Yard, Loading, Travel, On a job, Unloading or Break."},{"u":"g-timesheets_fix.html#s15","t":"From and to","a":"Fix a missed clock-out or add time","x":"The start and end times. Split a shift that runs past midnight."},{"u":"g-timesheets_fix.html#s16","t":"Job","a":"Fix a missed clock-out or add time","x":"For On a job: which job."},{"u":"g-timesheets_fix.html#s17","t":"Note","a":"Fix a missed clock-out or add time","x":"e.g. Paper timesheet \u00b7 phone was dead."},{"u":"g-timesheets_fix.html#s18","t":"Add it","a":"Fix a missed clock-out or add time","x":"Add time adds it, shown as corrected by the office. The tour doesn't press it."},{"u":"g-timesheets_fix.html#s19","t":"Close the form","a":"Fix a missed clock-out or add time","x":"The x closes the form without saving anything."},{"u":"g-timesheets_fix.html#s20","t":"Correct any block","a":"Fix a missed clock-out or add time","x":"Any block opens the same form: change what it was, its times or its job."},{"u":"g-s_invoices.html","t":"Everything on Invoices","a":"Money","k":"invoices invoice list bills billing screen everything open overdue late drafts draft paid all aging owed receivable search quickbooks export new month-end monthly maintenance card cards charge batch","v":0},{"u":"g-s_invoices.html#s1","t":"Invoices","a":"Everything on Invoices","x":"Every bill in one place. The line under the title is the total still open across all customers."},{"u":"g-s_invoices.html#s2","t":"QuickBooks export","a":"Everything on Invoices","x":"Makes the files QuickBooks Online imports: customers, invoices or payments for a date range. Let's open it."},{"u":"g-s_invoices.html#s3","t":"Customers, invoices or payments","a":"Everything on Invoices","x":"Pick what goes in the file. Export customers before invoices so the names match in QuickBooks. Payments come out as a deposit list for the bookkeeper."},{"u":"g-s_invoices.html#s4","t":"Make the file","a":"Everything on Invoices","x":"Builds the file for the dates you pick, then offers Download and Copy. The QuickBooks tour shows every option. The tour doesn't make a file."},{"u":"g-s_invoices.html#s5","t":"Close the panel","a":"Everything on Invoices","x":"The X closes it without exporting anything."},{"u":"g-s_invoices.html#s6","t":"New invoice","a":"Everything on Invoices","x":"For work outside a job: a service call, extras. Job invoices come from the job's payment schedule instead."},{"u":"g-s_invoices.html#s7","t":"Which customer?","a":"Everything on Invoices","x":"Type a name, phone or street. Clicking a customer in the list makes a new draft invoice for them right away and opens it, ready for its lines."},{"u":"g-s_invoices.html#s8","t":"Close it","a":"Everything on Invoices","x":"Close it if you only wanted to look. Nothing is made until you pick a customer."},{"u":"g-s_invoices.html#s9","t":"How late the money is","a":"Everything on Invoices","x":"Open money by age. Current is not due yet; 1-30 and 31-60 days late turn amber; 61-90 and Over 90 turn red."},{"u":"g-s_invoices.html#s10","t":"Month-end run","a":"Everything on Invoices","x":"When customers billed monthly have finished jobs, a Month-end run bar shows above the tabs. Create \u2026 invoices makes the drafts after asking. No bar = nothing to bill."},{"u":"g-s_invoices.html#s11","t":"Maintenance to bill","a":"Everything on Invoices","x":"Finished maintenance visits and monthly fees show in a green bar. Create the invoices makes one draft per customer, a line per visit or month, with no extra question."},{"u":"g-s_invoices.html#s12","t":"Drafts","a":"Everything on Invoices","x":"Invoices not sent yet. Open one to change the lines, dates and note, then Email now or Print now."},{"u":"g-s_invoices.html#s13","t":"Open","a":"Everything on Invoices","x":"Sent and not fully paid, overdue ones included. The list to work from every day."},{"u":"g-s_invoices.html#s14","t":"Overdue","a":"Everything on Invoices","x":"Past the due date. The red number next to the status is how many days late."},{"u":"g-s_invoices.html#s15","t":"Paid","a":"Everything on Invoices","x":"Paid in full."},{"u":"g-s_invoices.html#s16","t":"All","a":"Everything on Invoices","x":"Every invoice: drafts, open, paid and void."},{"u":"g-s_invoices.html#s17","t":"Search the list","a":"Everything on Invoices","x":"Type an invoice number, customer or job number. It filters the tab you're on."},{"u":"g-s_invoices.html#s18","t":"Back to Open","a":"Everything on Invoices","x":"Charging cards on file works from the Open and Overdue tabs."},{"u":"g-s_invoices.html#s19","t":"Charge cards on file","a":"Everything on Invoices","x":"When open invoices have a card on file, rows get a tick box and 'Select all with a card' shows here. Then 'Charge N cards' charges them in one batch, after asking."},{"u":"g-s_invoices.html#s20","t":"The columns","a":"Everything on Invoices","x":"Invoice number with its kind and job, the customer (\ud83d\udcb3 = card on file), date issued, status with days late and emailed or printed, the total and what's still open."},{"u":"g-s_invoices.html#s21","t":"Open an invoice","a":"Everything on Invoices","x":"Click any row to open it: lines, the customer copy, payments. The tour 'Everything on an invoice' walks through that screen."},{"u":"g-invoices_quickbooks.html","t":"Make the QuickBooks export file","a":"Money","k":"quickbooks qb qbo export file csv accounting accountant bookkeeper bookkeeping import customers invoices payments deposits sync","v":1},{"u":"g-invoices_quickbooks.html#s1","t":"QuickBooks export","a":"Make the QuickBooks export file","x":"Until QuickBooks is connected directly, the office sends it files. Open the export panel."},{"u":"g-invoices_quickbooks.html#s2","t":"Where it goes","a":"Make the QuickBooks export file","x":"In QuickBooks Online: Settings, then Import data. This line also says when you last exported."},{"u":"g-invoices_quickbooks.html#s3","t":"Customers first","a":"Make the QuickBooks export file","x":"Export customers before invoices, so every invoice finds its customer in QuickBooks."},{"u":"g-invoices_quickbooks.html#s4","t":"Then invoices","a":"Make the QuickBooks export file","x":"The invoices sent in the date range, ready for QuickBooks' invoice import."},{"u":"g-invoices_quickbooks.html#s5","t":"Payments","a":"Make the QuickBooks export file","x":"Payments received in the range, as a deposit list the bookkeeper matches to the bank. Click it when that's the file you need."},{"u":"g-invoices_quickbooks.html#s6","t":"From and To","a":"Make the QuickBooks export file","x":"The date range. It starts on the 1st of this month and runs to today; change either date."},{"u":"g-invoices_quickbooks.html#s7","t":"Only what wasn't exported yet","a":"Make the QuickBooks export file","x":"Leave it ticked so nothing goes into QuickBooks twice. Untick it to export the whole range again."},{"u":"g-invoices_quickbooks.html#s8","t":"Mark these as exported","a":"Make the QuickBooks export file","x":"Remembers what went into this file, so 'Only what wasn't exported yet' skips it next time."},{"u":"g-invoices_quickbooks.html#s9","t":"Make the file","a":"Make the QuickBooks export file","x":"Builds the file and shows its name and row count, with Download (a .csv file) and Copy. Then import it in QuickBooks. The tour doesn't make one."},{"u":"g-invoices_quickbooks.html#s10","t":"Close","a":"Make the QuickBooks export file","x":"The X closes the panel."},{"u":"g-invoices_month_end.html","t":"Month-end billing: monthly accounts and maintenance","a":"Money","k":"month-end month end monthly billing bill accounts commercial maintenance recurring visits fees run batch drafts invoices end of month","v":1},{"u":"g-invoices_month_end.html#s1","t":"Month-end run","a":"Month-end billing: monthly accounts and maintenance","x":"Customers set to 'Invoicing: Monthly' get their completed jobs billed at month end. This bar lists them with the total. No bar = nothing to bill."},{"u":"g-invoices_month_end.html#s2","t":"Create the drafts","a":"Month-end billing: monthly accounts and maintenance","x":"Create \u2026 invoices asks first, then makes one draft per job. They land on the Drafts tab to check before sending. The tour doesn't press it."},{"u":"g-invoices_month_end.html#s3","t":"Maintenance to bill","a":"Month-end billing: monthly accounts and maintenance","x":"Finished maintenance visits and monthly fees waiting to be billed, with how many customers and the amount before tax."},{"u":"g-invoices_month_end.html#s4","t":"Create the invoices","a":"Month-end billing: monthly accounts and maintenance","x":"Makes one draft per customer straight away, a line per visit or monthly fee. They land on Drafts too. The tour doesn't press it."},{"u":"g-invoices_month_end.html#s5","t":"Check the drafts","a":"Month-end billing: monthly accounts and maintenance","x":"Every new month-end invoice waits here as a draft."},{"u":"g-invoices_month_end.html#s6","t":"Open, check, send","a":"Month-end billing: monthly accounts and maintenance","x":"Open each draft, check the lines, then Email now or Print now. That marks it sent and it moves to Open."},{"u":"g-invoices_cards.html","t":"Charge cards on file, one or many, and log a declined card","a":"Money","k":"card cards credit debit on file charge charging batch autopay auto pay declined decline expired update processor surcharge fee terminal","v":1},{"u":"g-invoices_cards.html#s1","t":"Open invoices","a":"Charge cards on file, one or many, and log a declined card","x":"Cards are charged from the Open or Overdue tab."},{"u":"g-invoices_cards.html#s2","t":"Who has a card on file","a":"Charge cards on file, one or many, and log a declined card","x":"A \ud83d\udcb3 and the last 4 digits next to the customer means a card is on file. Those rows get a tick box on the left."},{"u":"g-invoices_cards.html#s3","t":"Charge many at once","a":"Charge cards on file, one or many, and log a declined card","x":"'Select all with a card' ticks them all (or tick rows one by one). 'Charge N cards' charges what's open on each and records card payments, after asking."},{"u":"g-invoices_cards.html#s4","t":"Or one invoice","a":"Charge cards on file, one or many, and log a declined card","x":"Open the invoice to charge just that one."},{"u":"g-invoices_cards.html#s5","t":"Charge card","a":"Charge cards on file, one or many, and log a declined card","x":"With a card on file and money open, 'Charge card \u2022\u20221234' shows here. It charges what's still open and records it as a card payment, after asking."},{"u":"g-invoices_cards.html#s6","t":"Card declined","a":"Charge cards on file, one or many, and log a declined card","x":"Declined at the terminal or in the batch? Card declined: note what the processor said. Record it emails the customer to update the card and puts a call on the office list."},{"u":"g-invoices_cards.html#s7","t":"Paid by card at the terminal","a":"Charge cards on file, one or many, and log a declined card","x":"Record payment, then pick Card."},{"u":"g-invoices_cards.html#s8","t":"Card and the surcharge","a":"Charge cards on file, one or many, and log a declined card","x":"With Card picked, the card fee from Settings (Contract terms) shows as its own surcharge before you record it. Untick it to waive the fee."},{"u":"g-invoices_cards.html#s9","t":"Close","a":"Charge cards on file, one or many, and log a declined card","x":"The X closes the form without recording anything."},{"u":"g-s_invoice.html","t":"Everything on an invoice","a":"Money","k":"invoice bill screen everything email print pdf record payment check cash card ach charge declined void lines customer copy document balance account paid due reminders","v":0},{"u":"g-s_invoice.html#s1","t":"Open an invoice","a":"Everything on an invoice","x":"Click any invoice in the list. We'll open an overdue one."},{"u":"g-s_invoice.html#s2","t":"Back to the customer","a":"Everything on an invoice","x":"The customer's name above the number opens their screen."},{"u":"g-s_invoice.html#s3","t":"Number, status and dates","a":"Everything on an invoice","x":"Next to it: the kind of invoice and its job, the status, the date issued, when it's due (or due on receipt) and when it was emailed or printed."},{"u":"g-s_invoice.html#s4","t":"Email","a":"Everything on an invoice","x":"Emails the invoice to the customer. On a draft it's Email now and marks it sent. While live email is off it goes to the test address instead."},{"u":"g-s_invoice.html#s5","t":"Print","a":"Everything on an invoice","x":"Prints it exactly as the customer gets it. On a draft it's Print now and marks it sent (printed)."},{"u":"g-s_invoice.html#s6","t":"Record payment","a":"Everything on an invoice","x":"A check, cash, card or bank transfer came in. Let's open the form."},{"u":"g-s_invoice.html#s7","t":"Amount","a":"Everything on an invoice","x":"Starts at what's still open. Enter less for a part payment. It can't be more than what's open."},{"u":"g-s_invoice.html#s8","t":"Method","a":"Everything on an invoice","x":"Check, Card, Cash, Bank transfer or Other. With Card, the card fee from Settings shows as its own surcharge; untick it to waive it."},{"u":"g-s_invoice.html#s9","t":"Check # / reference","a":"Everything on an invoice","x":"The check number or a reference, so the bookkeeper can match it to the deposit."},{"u":"g-s_invoice.html#s10","t":"Received","a":"Everything on an invoice","x":"The day the money came in. Today unless you change it."},{"u":"g-s_invoice.html#s11","t":"Save the payment","a":"Everything on an invoice","x":"Record payment saves it: the invoice shows what's left or Paid in full, and the customer's balance updates. The tour doesn't save it."},{"u":"g-s_invoice.html#s12","t":"Close the form","a":"Everything on an invoice","x":"The X (or Cancel) closes it without recording anything."},{"u":"g-s_invoice.html#s13","t":"Card on file","a":"Everything on an invoice","x":"If the customer has a card on file, 'Charge card \u2022\u20221234' and Card declined show here. Charge card charges what's open, after asking."},{"u":"g-s_invoice.html#s14","t":"Card declined, void","a":"Everything on an invoice","x":"Card declined logs a decline: the customer is asked to update the card and the office gets a call. Before any payment, a bin icon here voids the invoice."},{"u":"g-s_invoice.html#s15","t":"Test mode","a":"Everything on an invoice","x":"Shows while live email is off: emails go to the test address, not the customer. Turn live email on in Settings, Email."},{"u":"g-s_invoice.html#s16","t":"Lines","a":"Everything on an invoice","x":"What's billed: description, quantity, price, taxable or not, amount. A sent invoice is locked; to change it, void it and make a new one."},{"u":"g-s_invoice.html#s17","t":"The customer copy","a":"Everything on an invoice","x":"Exactly what the customer gets by email or on paper. The invoice total and their account balance are kept apart."},{"u":"g-s_invoice.html#s18","t":"Open full size","a":"Everything on an invoice","x":"Opens the customer copy full width to read it."},{"u":"g-s_invoice.html#s19","t":"Print / PDF","a":"Everything on an invoice","x":"Prints this copy; choose Save as PDF in the print window to attach it to your own email. This doesn't mark the invoice sent."},{"u":"g-s_invoice.html#s20","t":"Close it","a":"Everything on an invoice","x":"The X closes the full-size copy."},{"u":"g-s_invoice.html#s21","t":"Print / PDF","a":"Everything on an invoice","x":"The same print or PDF, straight from the card."},{"u":"g-s_invoice.html#s22","t":"This invoice","a":"Everything on an invoice","x":"Subtotal, sales tax, the invoice total, what's been paid, and what's still due on this invoice alone."},{"u":"g-s_invoice.html#s23","t":"The customer's account","a":"Everything on an invoice","x":"When they have other open invoices, an account box shows the whole balance and lists the others (click one to open it)."},{"u":"g-s_invoice.html#s24","t":"Payments","a":"Everything on an invoice","x":"Every payment on this invoice: date, method, check number or batch, who recorded it, and any card surcharge."},{"u":"g-s_invoice.html#s25","t":"Reminders","a":"Everything on an invoice","x":"Past-due reminders and other messages about this invoice: sent, waiting or skipped, and when. They're set up on Automations."},{"u":"g-invoice_draft.html","t":"Check a draft invoice, then email or print it","a":"Money","k":"draft drafts edit change fix invoice lines line description quantity price tax taxable exempt due date note email now print now send void","v":1},{"u":"g-invoice_draft.html#s1","t":"Drafts","a":"Check a draft invoice, then email or print it","x":"Invoices not sent yet: from a job's payment schedule, the month-end run or New invoice."},{"u":"g-invoice_draft.html#s2","t":"Open a draft","a":"Check a draft invoice, then email or print it","x":"Click the draft to open it."},{"u":"g-invoice_draft.html#s3","t":"Lines","a":"Check a draft invoice, then email or print it","x":"A draft can be changed until it's sent. Each line: description, quantity, price, a Tax tick and the amount."},{"u":"g-invoice_draft.html#s4","t":"Change a line","a":"Check a draft invoice, then email or print it","x":"Type straight into the boxes; the amount updates as you type. Untick Tax for a tax-exempt line. The X at the end removes the line."},{"u":"g-invoice_draft.html#s5","t":"Add line","a":"Check a draft invoice, then email or print it","x":"Adds an empty line at the bottom."},{"u":"g-invoice_draft.html#s6","t":"Invoice date","a":"Check a draft invoice, then email or print it","x":"The date printed on the invoice."},{"u":"g-invoice_draft.html#s7","t":"Due","a":"Check a draft invoice, then email or print it","x":"The same day as the invoice date reads 'due on receipt'. A later date prints as the due date and counts for overdue."},{"u":"g-invoice_draft.html#s8","t":"Note on the invoice","a":"Check a draft invoice, then email or print it","x":"Printed on the invoice: a thank-you, who to make checks payable to."},{"u":"g-invoice_draft.html#s9","t":"Save draft","a":"Check a draft invoice, then email or print it","x":"Saves your changes. Every line needs a description, and the due date can't be before the invoice date."},{"u":"g-invoice_draft.html#s10","t":"Email now","a":"Check a draft invoice, then email or print it","x":"Saves any changes, emails it to the customer and marks it sent. While live email is off it goes to the test address."},{"u":"g-invoice_draft.html#s11","t":"Print now","a":"Check a draft invoice, then email or print it","x":"Saves, opens the print window and marks it sent (printed)."},{"u":"g-invoice_draft.html#s12","t":"Preview","a":"Check a draft invoice, then email or print it","x":"The customer copy. After changing lines, save to refresh it."},{"u":"g-invoice_draft.html#s13","t":"The customer's account","a":"Check a draft invoice, then email or print it","x":"Their whole balance across every open invoice, kept apart from this invoice. Click another invoice listed here to open it."},{"u":"g-invoice_draft.html#s14","t":"Void","a":"Check a draft invoice, then email or print it","x":"Voids it, after asking. It stays on file as void, and a job milestone it billed can be invoiced again. Only before any payment is recorded."},{"u":"g-s_reports.html","t":"Everything on Reports","a":"Money","k":"reports report numbers screen everything sales salespeople money owed aging receivable call list commissions job costing profit margin timesheets export excel kpi close rate year","v":0},{"u":"g-s_reports.html#s1","t":"Reports","a":"Everything on Reports","x":"The year's numbers: sales, salespeople, money owed, commissions and job profit. Only roles that see money can open it."},{"u":"g-s_reports.html#s2","t":"Sales to date","a":"Everything on Reports","x":"Invoiced this year before tax, and how it compares with the same point last year."},{"u":"g-s_reports.html#s3","t":"Won this year","a":"Everything on Reports","x":"Estimates won this year, before tax, and how many jobs."},{"u":"g-s_reports.html#s4","t":"Close rate","a":"Everything on Reports","x":"Won out of won plus lost estimates this year."},{"u":"g-s_reports.html#s5","t":"Owed to us","a":"Everything on Reports","x":"Everything open on invoices and how much is past due. Click it to jump to Money owed."},{"u":"g-s_reports.html#s6","t":"Sales by month","a":"Everything on Reports","x":"The Sales tab: this year's bars next to last year's, month by month, invoiced before tax. Hover a bar for the amount."},{"u":"g-s_reports.html#s7","t":"Export","a":"Everything on Reports","x":"Every table here has Export: it downloads the numbers as an Excel file."},{"u":"g-s_reports.html#s8","t":"Won by category","a":"Everything on Reports","x":"What sells: estimate sections won this year, by catalogue category (or the section name)."},{"u":"g-s_reports.html#s9","t":"Salespeople","a":"Everything on Reports","x":"Each salesperson's year."},{"u":"g-s_reports.html#s10","t":"Each salesperson","a":"Everything on Reports","x":"Won and lost by decision date, jobs, close rate, and what's out now (open estimates: amount and how many). Export it for Excel."},{"u":"g-s_reports.html#s11","t":"Money owed","a":"Everything on Reports","x":"Who owes what, and how late."},{"u":"g-s_reports.html#s12","t":"By age","a":"Everything on Reports","x":"All customers together: Current, then 1-30, 31-60, 61-90 and Over 90 days past due."},{"u":"g-s_reports.html#s13","t":"Print the call list","a":"Everything on Reports","x":"Every week or two: each customer who owes, oldest past due first, with phone numbers and room to note the call. The tour doesn't print."},{"u":"g-s_reports.html#s14","t":"By customer","a":"Everything on Reports","x":"One row per customer, split by age, with the total. Click a customer to open them. Export it for Excel."},{"u":"g-s_reports.html#s15","t":"Commissions","a":"Everything on Reports","x":"What salespeople have earned."},{"u":"g-s_reports.html#s16","t":"Earned and paid","a":"Everything on Reports","x":"Per salesperson: earned but not paid yet, and paid this year. The line above says how it's worked out; rates are in Settings, Money."},{"u":"g-s_reports.html#s17","t":"Mark paid","a":"Everything on Reports","x":"After you pay a salesperson, Mark paid moves all their earned entries to paid. It asks first."},{"u":"g-s_reports.html#s18","t":"Commission report","a":"Everything on Reports","x":"One row per job with the commission on it, filtered by salesperson and dates, and exported for payroll. The commissions tour covers each filter."},{"u":"g-s_reports.html#s19","t":"Job costing","a":"Everything on Reports","x":"Profit on each job."},{"u":"g-s_reports.html#s20","t":"Date range","a":"Everything on Reports","x":"This month, last month, this year, last year or the last 12 months. The dates in use show next to it."},{"u":"g-s_reports.html#s21","t":"Revenue, costs, profit, hours","a":"Everything on Reports","x":"Revenue with change orders, job costs (labor at the burn rate, materials, subs), gross profit and margin, and crew hours against the estimate."},{"u":"g-s_reports.html#s22","t":"Job profit","a":"Everything on Reports","x":"Each job finished in the range, plus those still running: revenue, cost, hours, profit, margin against the estimate. Click a job to open it."},{"u":"g-s_reports.html#s23","t":"Jobs, salespeople or crews","a":"Everything on Reports","x":"Adds the same numbers up by salesperson or by crew instead of by job. Export downloads every job's details."},{"u":"g-s_reports.html#s24","t":"Burn rates","a":"Everything on Reports","x":"What one man-hour costs: wages, taxes, comp, benefits, overhead. Owner and office add a New rate from a date. The job costing tour shows the form."},{"u":"g-s_reports.html#s25","t":"Timesheets","a":"Everything on Reports","x":"Crew hours have their own screen."},{"u":"g-s_reports.html#s26","t":"Open Timesheets","a":"Everything on Reports","x":"Each person's week from the crew app: every segment, overtime past 40 h, missed clock-outs, corrections, approval and the ADP export."},{"u":"g-reports_commissions.html","t":"Commission report: filter, check, export for payroll","a":"Money","k":"commission commissions report salesperson salespeople rep payroll pay paid full sold completed between dates filter export excel mark paid profit rate earned","v":1},{"u":"g-reports_commissions.html#s1","t":"Commissions","a":"Commission report: filter, check, export for payroll","x":"Open the Commissions tab on Reports."},{"u":"g-reports_commissions.html#s2","t":"Earned and paid","a":"Commission report: filter, check, export for payroll","x":"The salesperson on the estimate earns it. The line above says when and on what (profit or sale); rates per salesperson are in Settings, Money."},{"u":"g-reports_commissions.html#s3","t":"Mark paid","a":"Commission report: filter, check, export for payroll","x":"After paying a salesperson, Mark paid moves all their earned entries to paid, after asking. The tour doesn't press it."},{"u":"g-reports_commissions.html#s4","t":"Commission report","a":"Commission report: filter, check, export for payroll","x":"Every job by salesperson: contract, change orders, invoiced, paid, paid in full, and the commission on it."},{"u":"g-reports_commissions.html#s5","t":"Salesperson","a":"Commission report: filter, check, export for payroll","x":"Every salesperson, or pick one. Owner and office see this filter; a salesperson sees their own jobs."},{"u":"g-reports_commissions.html#s6","t":"Which date","a":"Commission report: filter, check, export for payroll","x":"Paid in full between, Completed between or Sold between: the date the range below filters on."},{"u":"g-reports_commissions.html#s7","t":"From and To","a":"Commission report: filter, check, export for payroll","x":"The date range. It starts at January 1st of this year through today. The list updates as soon as you change it."},{"u":"g-reports_commissions.html#s8","t":"Only jobs paid in full","a":"Commission report: filter, check, export for payroll","x":"Untick it to see every job in the range, paid or not; unpaid ones show 'Not yet'."},{"u":"g-reports_commissions.html#s9","t":"One row per job","a":"Commission report: filter, check, export for payroll","x":"Contract, change orders, completed, invoiced, paid, paid-in-full date, the base (profit or sale), rate and commission, with its status. Click the customer to open the job."},{"u":"g-reports_commissions.html#s10","t":"Totals","a":"Commission report: filter, check, export for payroll","x":"The totals for everything in the list: jobs, contract, change orders, invoiced, paid, profit and commission."},{"u":"g-reports_commissions.html#s11","t":"Export for payroll","a":"Commission report: filter, check, export for payroll","x":"Downloads the report as an Excel file, one row per job. The tour doesn't download it."},{"u":"g-reports_costing.html","t":"Job costing: profit by job, salesperson and crew","a":"Money","k":"job costing cost costs profit margin gross burn rate rates labor labour man-hour hours estimated actual crew crews salesperson change orders budget overhead wages","v":1},{"u":"g-reports_costing.html#s1","t":"Job costing","a":"Job costing: profit by job, salesperson and crew","x":"Open the Job costing tab on Reports."},{"u":"g-reports_costing.html#s2","t":"Pick the dates","a":"Job costing: profit by job, salesperson and crew","x":"This month, last month, this year, last year or the last 12 months. The dates in use show next to it."},{"u":"g-reports_costing.html#s3","t":"Last 12 months","a":"Job costing: profit by job, salesperson and crew","x":"Click a range and the whole tab recalculates for it."},{"u":"g-reports_costing.html#s4","t":"Revenue","a":"Job costing: profit by job, salesperson and crew","x":"Contracts plus approved change orders for jobs with costs. Jobs with no crew time or costs yet aren't counted, so they don't show a false 100%."},{"u":"g-reports_costing.html#s5","t":"Job costs","a":"Job costing: profit by job, salesperson and crew","x":"Crew hours at the burn rate, plus materials and subcontractors."},{"u":"g-reports_costing.html#s6","t":"Gross profit","a":"Job costing: profit by job, salesperson and crew","x":"Revenue minus job costs, and the margin."},{"u":"g-reports_costing.html#s7","t":"Crew hours","a":"Job costing: profit by job, salesperson and crew","x":"Hours the crews logged against the hours estimated. Going over is what eats the margin."},{"u":"g-reports_costing.html#s8","t":"Job profit","a":"Job costing: profit by job, salesperson and crew","x":"Jobs finished in the range plus those still running."},{"u":"g-reports_costing.html#s9","t":"One job","a":"Job costing: profit by job, salesperson and crew","x":"CO = change orders in the revenue. Red hours = more than estimated. Margin shows the estimate's margin next to it. Click a job to open it."},{"u":"g-reports_costing.html#s10","t":"By salesperson","a":"Job costing: profit by job, salesperson and crew","x":"The same numbers added up per salesperson."},{"u":"g-reports_costing.html#s11","t":"By crew","a":"Job costing: profit by job, salesperson and crew","x":"Per crew. A job two crews worked on counts for both."},{"u":"g-reports_costing.html#s12","t":"Back to jobs","a":"Job costing: profit by job, salesperson and crew","x":"One row per job again."},{"u":"g-reports_costing.html#s13","t":"Export","a":"Job costing: profit by job, salesperson and crew","x":"Downloads every job as an Excel file: estimated and actual hours, labor, material, subs, other, total cost, profit and margins."},{"u":"g-reports_costing.html#s14","t":"Burn rates","a":"Job costing: profit by job, salesperson and crew","x":"What one man-hour costs: wages, payroll taxes, workers' comp, benefits and overhead. Types of work without their own rate use the company-wide one."},{"u":"g-reports_costing.html#s15","t":"Rate cards","a":"Job costing: profit by job, salesperson and crew","x":"Each card: the rate today and since when. A rate that starts later shows in amber; History lists older rates."},{"u":"g-reports_costing.html#s16","t":"New rate","a":"Job costing: profit by job, salesperson and crew","x":"Owner and office can add a rate, for example when wages or comp change."},{"u":"g-reports_costing.html#s17","t":"For","a":"Job costing: profit by job, salesperson and crew","x":"Company-wide, or one type of work such as Hardscape or Landscape."},{"u":"g-reports_costing.html#s18","t":"Per man-hour","a":"Job costing: profit by job, salesperson and crew","x":"The full cost of one man-hour, all in."},{"u":"g-reports_costing.html#s19","t":"From","a":"Job costing: profit by job, salesperson and crew","x":"Work from this date costs at the new rate. Earlier work keeps the rate it had."},{"u":"g-reports_costing.html#s20","t":"Note","a":"Job costing: profit by job, salesperson and crew","x":"What's in it, for example '2027 wages + comp'."},{"u":"g-reports_costing.html#s21","t":"Save rate","a":"Job costing: profit by job, salesperson and crew","x":"Saves the rate and job profit recalculates. The tour doesn't save it."},{"u":"g-reports_costing.html#s22","t":"Close","a":"Job costing: profit by job, salesperson and crew","x":"The X closes the form without saving."},{"u":"g-s_catalogue.html","t":"Everything on Catalogue","a":"Setup","k":"catalogue catalog products product services service materials material items item price prices pricing cost margin kit kits unit hours category inactive equipment fee fees price list new item change price","v":0},{"u":"g-s_catalogue.html#s1","t":"Catalogue","a":"Everything on Catalogue","x":"Every service, material, equipment item and fee your estimates pick from (Service Autopilot's products). The number under the title counts the active items."},{"u":"g-s_catalogue.html#s2","t":"Add an item","a":"Everything on Catalogue","x":"New item opens a blank form. Only people who see money can add or change items."},{"u":"g-s_catalogue.html#s3","t":"Name","a":"Everything on Catalogue","x":"The name on estimates and in the list. It's the only thing you must fill in."},{"u":"g-s_catalogue.html#s4","t":"Kind","a":"Everything on Catalogue","x":"Service (labor), Material, Equipment or Fee. Only a service can carry a kit of materials. The Kind filter on the list uses it too."},{"u":"g-s_catalogue.html#s5","t":"Category","a":"Everything on Catalogue","x":"Hardscape, Plants, Irrigation\u2026 It groups the list. A crew whose kind of work matches the category gets won sections of it first."},{"u":"g-s_catalogue.html#s6","t":"Unit","a":"Everything on Catalogue","x":"What one of it is: ea, sq ft, ton, job. The quantity on an estimate counts these."},{"u":"g-s_catalogue.html#s7","t":"Cost and price","a":"Everything on Catalogue","x":"Price is what the customer pays per unit; Cost, just before it, is what it costs you. The list works out the margin from the two."},{"u":"g-s_catalogue.html#s8","t":"Crew-hours per unit","a":"Everything on Catalogue","x":"How many crew-hours one unit takes. It fills the hours on estimates, and the schedule turns those hours into days for a crew."},{"u":"g-s_catalogue.html#s9","t":"Description","a":"Everything on Catalogue","x":"What the customer reads on the estimate line. It fills in when the item is added to an estimate."},{"u":"g-s_catalogue.html#s10","t":"Taxable","a":"Everything on Catalogue","x":"Ticked: sales tax applies to it. Untick it for items that are never taxed."},{"u":"g-s_catalogue.html#s11","t":"Active","a":"Everything on Catalogue","x":"Active items are offered in estimates. Untick to retire one: estimates that have it keep it, and the list hides it unless Show inactive is ticked."},{"u":"g-s_catalogue.html#s12","t":"Add item","a":"Everything on Catalogue","x":"Add item saves it (prices can't be negative). Cancel, or the X at the top, closes the form without saving."},{"u":"g-s_catalogue.html#s13","t":"Close the form","a":"Everything on Catalogue","x":"The tour closes it without saving anything."},{"u":"g-s_catalogue.html#s14","t":"Search the catalogue","a":"Everything on Catalogue","x":"Type part of a name, an item code or a word from the description; the list narrows as you type."},{"u":"g-s_catalogue.html#s15","t":"Filter by kind","a":"Everything on Catalogue","x":"Show only services, materials, equipment or fees."},{"u":"g-s_catalogue.html#s16","t":"Filter by category","a":"Everything on Catalogue","x":"Show one category. The number beside each category is how many items it has."},{"u":"g-s_catalogue.html#s17","t":"Show inactive","a":"Everything on Catalogue","x":"Tick it to include the items you switched off. They carry an Inactive tag."},{"u":"g-s_catalogue.html#s18","t":"The list","a":"Everything on Catalogue","x":"Each row: name, code and description, category, kind, unit, and Used (how many estimate lines use it). Click a row to change the item. 60 rows a page."},{"u":"g-s_catalogue.html#s19","t":"Cost, price and margin","a":"Everything on Catalogue","x":"Cost, Price and Margin show only for people who see money. A margin in red means the price is below the cost."},{"u":"g-s_catalogue.html#s20","t":"Open an item","a":"Everything on Catalogue","x":"Click a row to open the same form, filled in. Changing a price never changes estimates already written. Here: a service."},{"u":"g-s_catalogue.html#s21","t":"A service's kit","a":"Everything on Catalogue","x":"Its kit: the materials that come with this service on every estimate, hidden from the customer unless ticked. The tour \"Set up a service's kit\" shows each part."},{"u":"g-s_catalogue.html#s22","t":"Close it","a":"Everything on Catalogue","x":"The tour closes it without saving. That's the whole Catalogue."},{"u":"g-catalogue_kits.html","t":"Set up a service's kit of materials","a":"Setup","k":"kit kits materials material service bundle assembly base sand edge restraint hidden show customer quantity per unit catalogue estimate","v":1},{"u":"g-catalogue_kits.html#s1","t":"Find the service","a":"Set up a service's kit of materials","x":"Only services have a kit. Any kind \u2192 Services lists just the services."},{"u":"g-catalogue_kits.html#s2","t":"Open the service","a":"Set up a service's kit of materials","x":"Click the service to open it. Here: Paver Patio Installation."},{"u":"g-catalogue_kits.html#s3","t":"It must be a service","a":"Set up a service's kit of materials","x":"Kind must be Service (labor). A new service gets its kit after its first save."},{"u":"g-catalogue_kits.html#s4","t":"The kit","a":"Set up a service's kit of materials","x":"The materials that come with this service on every estimate it is added to."},{"u":"g-catalogue_kits.html#s5","t":"How much per unit","a":"Set up a service's kit of materials","x":"How much of the material goes with one unit of the service, e.g. tons of base per sq ft of patio. The estimate works out the amount from the service's quantity."},{"u":"g-catalogue_kits.html#s6","t":"Show it to the customer?","a":"Set up a service's kit of materials","x":"Tick Show to list that material on the customer's copy. Unticked, it stays hidden from the customer."},{"u":"g-catalogue_kits.html#s7","t":"Take one out","a":"Set up a service's kit of materials","x":"The x takes that material out of the kit. Nothing changes until you press Save."},{"u":"g-catalogue_kits.html#s8","t":"Add a material","a":"Set up a service's kit of materials","x":"Pick a material, equipment item or fee to add it to the kit at 1 per unit, then set the amount."},{"u":"g-catalogue_kits.html#s9","t":"Save","a":"Set up a service's kit of materials","x":"Save keeps the item and its kit. New estimates get the new kit; estimates already written don't change."},{"u":"g-catalogue_kits.html#s10","t":"Close it","a":"Set up a service's kit of materials","x":"The tour closes it without saving."},{"u":"g-s_fleet.html","t":"Everything on Fleet","a":"Setup","k":"fleet trucks truck equipment machines machine vehicles oil change inspection tires service log mileage odometer reading engine hours repair crew report problem due overdue skid steer excavator track","v":0},{"u":"g-s_fleet.html#s1","t":"Fleet & equipment","a":"Everything on Fleet","x":"Every truck and machine: how many, how many are overdue or due soon, and the fleet manager, who gets the Monday due list and the crews' truck reports (set in Settings)."},{"u":"g-s_fleet.html#s2","t":"Log service","a":"Everything on Fleet","x":"Records an oil change, inspection, tire service or repair for any unit. The tour \"Log a service, oil change or repair\" shows the form."},{"u":"g-s_fleet.html#s3","t":"Add unit","a":"Everything on Fleet","x":"Adds a truck or machine with its service intervals. The tour \"Add or change a truck or machine\" shows the form."},{"u":"g-s_fleet.html#s4","t":"Reported by the crews","a":"Everything on Fleet","x":"Problems crew leads report from the phone (the truck form under More), with photos. The fleet manager hears about them right away."},{"u":"g-s_fleet.html#s5","t":"Log the fix","a":"Everything on Fleet","x":"Opens Log service for that unit with the problem filled in. Logging the fix closes the report."},{"u":"g-s_fleet.html#s6","t":"Close without a fix","a":"Everything on Fleet","x":"The x closes a report that needs no repair. Nothing is logged."},{"u":"g-s_fleet.html#s7","t":"Filter the units","a":"Everything on Fleet","x":"All (everything not sold), Overdue, Due soon, Trucks, Equipment and Sold. The numbers say how many are overdue and due soon."},{"u":"g-s_fleet.html#s8","t":"Overdue","a":"Everything on Fleet","x":"Only the units with something past due."},{"u":"g-s_fleet.html#s9","t":"All","a":"Everything on Fleet","x":"Back to every unit. Sold ones stay under Sold."},{"u":"g-s_fleet.html#s10","t":"A truck","a":"Everything on Fleet","x":"Oil and Tires: miles left (red = over). Inspect: the next inspection. Miles: the last odometer. A red card has something overdue, an amber one something due soon."},{"u":"g-s_fleet.html#s11","t":"A machine","a":"Everything on Fleet","x":"Machines count engine hours. Service: hours left to the next service. Hours: the meter. L and R track: the hours on each track."},{"u":"g-s_fleet.html#s12","t":"Open a unit","a":"Everything on Fleet","x":"Click a unit to open it."},{"u":"g-s_fleet.html#s13","t":"Its details","a":"Everything on Fleet","x":"Vehicle, type, VIN or serial, plate, crew or driver, status, what its maintenance has cost and notes."},{"u":"g-s_fleet.html#s14","t":"New reading","a":"Everything on Fleet","x":"Type today's odometer (engine hours for a machine) so the due dates stay right. The date of the last reading is below."},{"u":"g-s_fleet.html#s15","t":"Fix a wrong reading","a":"Everything on Fleet","x":"Tick it only to correct a typo: it allows a number lower than the last reading."},{"u":"g-s_fleet.html#s16","t":"Save reading","a":"Everything on Fleet","x":"Saves the number and works out again what is due."},{"u":"g-s_fleet.html#s17","t":"Service history","a":"Everything on Fleet","x":"Every service on this unit: date, service, miles or hours, the work, who did it and the cost."},{"u":"g-s_fleet.html#s18","t":"Edit unit","a":"Everything on Fleet","x":"Changes its details and intervals, or marks it Sold."},{"u":"g-s_fleet.html#s19","t":"Log service for this unit","a":"Everything on Fleet","x":"Opens the service form with this unit and its last reading filled in."},{"u":"g-s_fleet.html#s20","t":"Close it","a":"Everything on Fleet","x":"The tour closes it."},{"u":"g-s_fleet.html#s21","t":"Service log","a":"Everything on Fleet","x":"Everything serviced in the last 13 months, newest first: date, unit, service, work, miles or hours and cost. 20 rows a page."},{"u":"g-fleet_units.html","t":"Add or change a truck or machine","a":"Setup","k":"add new truck vehicle equipment machine unit fleet vin plate interval oil tires inspection crew driver sold remove edit change","v":1},{"u":"g-fleet_units.html#s1","t":"Add unit","a":"Add or change a truck or machine","x":"Opens the form. Its fields match your fleet spreadsheet."},{"u":"g-fleet_units.html#s2","t":"Unit number","a":"Add or change a truck or machine","x":"The number on the truck or machine (T-01, E-02). It's the only thing you must fill in."},{"u":"g-fleet_units.html#s3","t":"Truck or equipment","a":"Add or change a truck or machine","x":"Truck / vehicle counts miles (oil, tires, inspection). Equipment counts engine hours."},{"u":"g-fleet_units.html#s4","t":"Type","a":"Add or change a truck or machine","x":"Dump truck, pickup, skid steer\u2026 It shows under the name on its card."},{"u":"g-fleet_units.html#s5","t":"Status","a":"Add or change a truck or machine","x":"Active, In shop, Out of service, Spare, Reserved or Sold. Sold units leave the main list (see them under Sold)."},{"u":"g-fleet_units.html#s6","t":"Year, make, model, VIN","a":"Add or change a truck or machine","x":"Year, make and model, then the VIN or serial number."},{"u":"g-fleet_units.html#s7","t":"Plate","a":"Add or change a truck or machine","x":"The licence plate."},{"u":"g-fleet_units.html#s8","t":"Crew or driver","a":"Add or change a truck or machine","x":"The crew that usually takes it, or a driver's name. Its card shows it."},{"u":"g-fleet_units.html#s9","t":"Next inspection","a":"Add or change a truck or machine","x":"The date of the next inspection. It shows amber when close and red when past."},{"u":"g-fleet_units.html#s10","t":"Oil every","a":"Add or change a truck or machine","x":"Miles between oil changes. The next one is due this many miles after the last oil change you log."},{"u":"g-fleet_units.html#s11","t":"Tires every","a":"Add or change a truck or machine","x":"Miles between tire services."},{"u":"g-fleet_units.html#s12","t":"Equipment service every","a":"Add or change a truck or machine","x":"Engine hours between services, for machines."},{"u":"g-fleet_units.html#s13","t":"Notes","a":"Add or change a truck or machine","x":"Anything else worth knowing about it."},{"u":"g-fleet_units.html#s14","t":"Add unit","a":"Add or change a truck or machine","x":"Saves it. Then log its last oil change so its due dates start."},{"u":"g-fleet_units.html#s15","t":"Close the form","a":"Add or change a truck or machine","x":"The tour closes it without saving."},{"u":"g-fleet_units.html#s16","t":"Change a unit","a":"Add or change a truck or machine","x":"To change one, open it\u2026"},{"u":"g-fleet_units.html#s17","t":"Edit unit","a":"Add or change a truck or machine","x":"\u2026and press Edit unit: the same form, filled in."},{"u":"g-fleet_units.html#s18","t":"Remove unit","a":"Add or change a truck or machine","x":"Owner or office only. It asks first. Mark the unit Sold instead to keep its history."},{"u":"g-fleet_units.html#s19","t":"Save","a":"Add or change a truck or machine","x":"Save keeps the changes."},{"u":"g-fleet_units.html#s20","t":"Close it","a":"Add or change a truck or machine","x":"The tour closes it without saving."},{"u":"g-fleet_service.html","t":"Log a service, oil change or repair","a":"Setup","k":"log service oil change repair inspection tires tire rotation brakes track replacement mechanic shop parts labor cost fix truck report problem maintenance","v":1},{"u":"g-fleet_service.html#s1","t":"Log service","a":"Log a service, oil change or repair","x":"Opens the service form."},{"u":"g-fleet_service.html#s2","t":"Unit","a":"Log a service, oil change or repair","x":"Pick the truck or machine."},{"u":"g-fleet_service.html#s3","t":"Date","a":"Log a service, oil change or repair","x":"When it was done. It starts at today."},{"u":"g-fleet_service.html#s4","t":"Service","a":"Log a service, oil change or repair","x":"Oil & Filter, Tire Rotation, Brakes, Annual Inspection, Repair, Seasonal, Track Replacement or Other. Oil, inspection and tire services reset that item's due date."},{"u":"g-fleet_service.html#s5","t":"Which track","a":"Log a service, oil change or repair","x":"For a track replacement: Left, Right or Both. It must be filled in for that service."},{"u":"g-fleet_service.html#s6","t":"Miles or hours","a":"Log a service, oil change or repair","x":"The odometer for a truck, or the engine hours for a machine, at the service. Opened from a unit, they start at its last reading."},{"u":"g-fleet_service.html#s7","t":"Parts and labor","a":"Log a service, oil change or repair","x":"What the parts and the labor cost. Together they make the cost in the service log and the unit's maintenance cost."},{"u":"g-fleet_service.html#s8","t":"Work performed","a":"Log a service, oil change or repair","x":"What was done, in a few words."},{"u":"g-fleet_service.html#s9","t":"Performed by","a":"Log a service, oil change or repair","x":"The shop or the mechanic."},{"u":"g-fleet_service.html#s10","t":"Next due","a":"Log a service, oil change or repair","x":"Optional: a date for the next one."},{"u":"g-fleet_service.html#s11","t":"Log service","a":"Log a service, oil change or repair","x":"Saves it and moves the due dates on."},{"u":"g-fleet_service.html#s12","t":"Close the form","a":"Log a service, oil change or repair","x":"The tour closes it without saving."},{"u":"g-fleet_service.html#s13","t":"A problem a crew reported","a":"Log a service, oil change or repair","x":"For a problem a crew reported from the phone, use its own button."},{"u":"g-fleet_service.html#s14","t":"Log the fix","a":"Log a service, oil change or repair","x":"Opens the same form for that unit\u2026"},{"u":"g-fleet_service.html#s15","t":"The problem is filled in","a":"Log a service, oil change or repair","x":"\u2026with \"Fixed:\" and the problem already written. Logging it closes the report."},{"u":"g-fleet_service.html#s16","t":"Close it","a":"Log a service, oil change or repair","x":"The tour closes it without saving."},{"u":"g-s_team.html","t":"Everything on Team & crews","a":"Setup","k":"team people person staff employees users crews crew roles role login money sees money appointments hourly cost leads lead colour color add person new crew access permissions inactive","v":0},{"u":"g-s_team.html#s1","t":"Team & crews","a":"Everything on Team & crews","x":"Who works here and the crews the schedule plans with. Only the owner and the office open it. The line under the title counts crews and active people."},{"u":"g-s_team.html#s2","t":"New crew","a":"Everything on Team & crews","x":"Adds a crew: name, kind of work, lead, size, hours a day, colour and members. The tour \"Set up a crew\" shows each part."},{"u":"g-s_team.html#s3","t":"Add person","a":"Everything on Team & crews","x":"Gives someone a role in the office app or the crew phone app."},{"u":"g-s_team.html#s4","t":"Name","a":"Everything on Team & crews","x":"Their name as it shows on appointments, crews and the schedule."},{"u":"g-s_team.html#s5","t":"Login id","a":"Everything on Team & crews","x":"Their FieldProxy login (lower case, no spaces). It ties the person to their login and can't be changed later."},{"u":"g-s_team.html#s6","t":"Role","a":"Everything on Team & crews","x":"Owner, Office, Sales, Project manager, Crew lead or Field: it decides what they can open. For a new person, the four office roles tick Takes appointments."},{"u":"g-s_team.html#s7","t":"Phone","a":"Everything on Team & crews","x":"Their phone number."},{"u":"g-s_team.html#s8","t":"Hourly cost","a":"Everything on Team & crews","x":"What an hour of their time costs you; job costing uses it. Only people who see money see this."},{"u":"g-s_team.html#s9","t":"Sees prices and money","a":"Everything on Team & crews","x":"Ticked: they see prices, margins, invoices and payments. Unticked: all of that is hidden from them."},{"u":"g-s_team.html#s10","t":"Takes appointments","a":"Everything on Team & crews","x":"Ticked: they're in the \"With\" list when you book a visit or a phone call. A task can go to anyone."},{"u":"g-s_team.html#s11","t":"Office app or phone app","a":"Everything on Team & crews","x":"Crew leads and field staff use the crew phone app and never see money there. Office roles open this app."},{"u":"g-s_team.html#s12","t":"Add person","a":"Everything on Team & crews","x":"Saves them. Cancel, or the X at the top, closes without saving."},{"u":"g-s_team.html#s13","t":"Close the form","a":"Everything on Team & crews","x":"The tour closes it without saving."},{"u":"g-s_team.html#s14","t":"Crews","a":"Everything on Team & crews","x":"Your crews, one card each."},{"u":"g-s_team.html#s15","t":"A crew","a":"Everything on Team & crews","x":"Its colour on the schedule, kind of work, lead, people \u00d7 hours a day = the crew-hours a day the schedule checks against, and members (\u2605 = lead). Click it to change it."},{"u":"g-s_team.html#s16","t":"People","a":"Everything on Team & crews","x":"Everyone with a role: login (\"no login yet\" until they have one), role, sees money, takes appointments, the crew they lead and phone. Inactive people are tagged."},{"u":"g-s_team.html#s17","t":"Hourly cost","a":"Everything on Team & crews","x":"What each person's hour costs, for job costing. Only people who see money see this column."},{"u":"g-s_team.html#s18","t":"Change a person","a":"Everything on Team & crews","x":"Click a person to change their role, access or phone."},{"u":"g-s_team.html#s19","t":"Login id stays","a":"Everything on Team & crews","x":"Once saved, the login id can't be changed."},{"u":"g-s_team.html#s20","t":"Active","a":"Everything on Team & crews","x":"Untick Active when someone leaves: they come off the pick lists and their history stays."},{"u":"g-s_team.html#s21","t":"Save","a":"Everything on Team & crews","x":"Save keeps the changes."},{"u":"g-s_team.html#s22","t":"Close it","a":"Everything on Team & crews","x":"The tour closes it without saving."},{"u":"g-s_team.html#s23","t":"Logins without a role","a":"Everything on Team & crews","x":"FieldProxy logins that have no role here yet. Add each one with Add person, using the same login id, to let them in."},{"u":"g-team_crews.html","t":"Set up a crew: lead, size, hours, colour, members","a":"Setup","k":"crew crews new crew lead size people hours capacity colour color members schedule specialization kind of work hardscape landscape inactive","v":1},{"u":"g-team_crews.html#s1","t":"New crew","a":"Set up a crew: lead, size, hours, colour, members","x":"Opens the crew form."},{"u":"g-team_crews.html#s2","t":"Crew name","a":"Set up a crew: lead, size, hours, colour, members","x":"What the schedule calls it, e.g. Hardscape 1. It must be filled in."},{"u":"g-team_crews.html#s3","t":"Kind of work","a":"Set up a crew: lead, size, hours, colour, members","x":"hardscape, landscape, lighting\u2026 Won estimate sections from a matching catalogue category get this crew first. Customer notices in Settings go by it too."},{"u":"g-team_crews.html#s4","t":"Crew lead","a":"Set up a crew: lead, size, hours, colour, members","x":"Who leads it (\u2605). The lead is added to the members when you save."},{"u":"g-team_crews.html#s5","t":"People on the crew","a":"Set up a crew: lead, size, hours, colour, members","x":"How many usually work on it."},{"u":"g-team_crews.html#s6","t":"Hours a day","a":"Set up a crew: lead, size, hours, colour, members","x":"Their working day. People \u00d7 hours = the crew-hours a day; the schedule warns above it. The line under the colours works it out."},{"u":"g-team_crews.html#s7","t":"Colour on the schedule","a":"Set up a crew: lead, size, hours, colour, members","x":"Each crew gets its own colour. A swatch with a dot is taken by another crew: pick one without a dot so crews look different."},{"u":"g-team_crews.html#s8","t":"Any other colour","a":"Set up a crew: lead, size, hours, colour, members","x":"Or pick any colour here. If it looks like another crew's, a red line says so."},{"u":"g-team_crews.html#s9","t":"Members","a":"Set up a crew: lead, size, hours, colour, members","x":"Tick everyone on the crew."},{"u":"g-team_crews.html#s10","t":"Add crew","a":"Set up a crew: lead, size, hours, colour, members","x":"Saves the crew. People and hours a day must be above zero."},{"u":"g-team_crews.html#s11","t":"Close the form","a":"Set up a crew: lead, size, hours, colour, members","x":"The tour closes it without saving."},{"u":"g-team_crews.html#s12","t":"Change a crew","a":"Set up a crew: lead, size, hours, colour, members","x":"To change a crew, click its card."},{"u":"g-team_crews.html#s13","t":"Active","a":"Set up a crew: lead, size, hours, colour, members","x":"Untick to take the crew off the schedule without deleting it."},{"u":"g-team_crews.html#s14","t":"Save crew","a":"Set up a crew: lead, size, hours, colour, members","x":"Saves the changes and the member list."},{"u":"g-team_crews.html#s15","t":"Close it","a":"Set up a crew: lead, size, hours, colour, members","x":"The tour closes it without saving."},{"u":"g-s_automations.html","t":"Everything on Automations","a":"Setup","k":"automations automatic automation reminders reminder follow-ups followup notices emails email texts sms queue sent wording template message engine run live email test address runs online estimate","v":0},{"u":"g-s_automations.html#s1","t":"Automations","a":"Everything on Automations","x":"What the system does without anyone pressing a button: follow-ups, reminders and notices. Every message waits in the queue first, where you can stop it."},{"u":"g-s_automations.html#s2","t":"At a glance","a":"Everything on Automations","x":"How many of the 9 automations are switched on, messages sent today and in the last 30 days, and how many are waiting to go."},{"u":"g-s_automations.html#s3","t":"Run now","a":"Everything on Automations","x":"Runs the checks straight away instead of waiting for the next run: whatever is due gets queued and its call tickets made. A message says what it did."},{"u":"g-s_automations.html#s4","t":"Wording","a":"Everything on Automations","x":"Opens the Wording tab: the words of every email and text."},{"u":"g-s_automations.html#s5","t":"Today's clock","a":"Everything on Automations","x":"Each dot is a message sent today, at the hour it went. The red hand is now."},{"u":"g-s_automations.html#s6","t":"Engine","a":"Everything on Automations","x":"Green when the automatic run is connected (every 10 minutes). Until then the checks run whenever the office opens the app."},{"u":"g-s_automations.html#s7","t":"Last run","a":"Everything on Automations","x":"When the checks last ran. Amber if it was over an hour ago."},{"u":"g-s_automations.html#s8","t":"Sending","a":"Everything on Automations","x":"When the last message went out. Amber if a message has waited more than 20 minutes."},{"u":"g-s_automations.html#s9","t":"Live email","a":"Everything on Automations","x":"On: messages go to customers. Off: they go to the test address. Change it under Sending setup."},{"u":"g-s_automations.html#s10","t":"Texts","a":"Everything on Automations","x":"Whether text messages are switched on (Sending setup)."},{"u":"g-s_automations.html#s11","t":"Online estimates","a":"Everything on Automations","x":"Whether the online estimate links, where customers view and accept online, are installed."},{"u":"g-s_automations.html#s12","t":"What runs","a":"Everything on Automations","x":"Every automation, with its switch and timing."},{"u":"g-s_automations.html#s13","t":"One automation","a":"Everything on Automations","x":"What it does, its flow (what starts it, the wait, what goes out), its timing, how many went out in 30 days and Edit wording. Change a number and a Save button appears."},{"u":"g-s_automations.html#s14","t":"On or off","a":"Everything on Automations","x":"The switch turns it on or off and saves straight away. The tour \"Switch reminders and notices on or off\" goes through all nine."},{"u":"g-s_automations.html#s15","t":"Queue","a":"Everything on Automations","x":"Messages waiting to go."},{"u":"g-s_automations.html#s16","t":"Waiting to go","a":"Everything on Automations","x":"Each message, customer, subject and address, and when it goes. The eye shows it, the arrow sends it now, the x cancels it. If its reason goes away (paid, answered) it cancels itself."},{"u":"g-s_automations.html#s17","t":"Sent","a":"Everything on Automations","x":"What went out."},{"u":"g-s_automations.html#s18","t":"What went out","a":"Everything on Automations","x":"The last 80 messages, newest first, with All / Sent / Not sent. The eye shows a message; the round arrow sends a failed, cancelled or skipped one again."},{"u":"g-s_automations.html#s19","t":"Wording","a":"Everything on Automations","x":"The words of every message."},{"u":"g-s_automations.html#s20","t":"The words","a":"Everything on Automations","x":"Pick a message under Every message, change its subject and text, and see it on the right as a customer gets it. The tour \"Change the wording of an email or text\" shows each part."},{"u":"g-s_automations.html#s21","t":"Sending setup","a":"Everything on Automations","x":"The Sending setup tab: how messages are sent."},{"u":"g-s_automations.html#s22","t":"How sending is set up","a":"Everything on Automations","x":"Live email, the test address, the address customers write to, texts, links in messages, crew photo rules and QuickBooks items. Save setup keeps them."},{"u":"g-s_automations.html#s23","t":"Runs","a":"Everything on Automations","x":"The Runs tab: every run of the checks."},{"u":"g-s_automations.html#s24","t":"Automation runs","a":"Everything on Automations","x":"When each run happened, what started it (the timer, the office or Run now), how long it took and what it did. A red tag means a part failed."},{"u":"g-s_automations.html#s25","t":"Online estimate events","a":"Everything on Automations","x":"Online estimates opened, accepted and declined, as the platform reported them. Click one to open the estimate."},{"u":"g-automations_what.html","t":"Switch reminders and notices on or off, and set their timing","a":"Setup","k":"switch on off turn enable disable automation automations reminder reminders timing days follow-up followups past due dunning statement appointment reminder job notice arrived deposit card declined survey website requests","v":1},{"u":"g-automations_what.html#s1","t":"What runs","a":"Switch reminders and notices on or off, and set their timing","x":"Every automation, one card each."},{"u":"g-automations_what.html#s2","t":"Estimate follow-ups","a":"Switch reminders and notices on or off, and set their timing","x":"No answer to an estimate: Email 1 after the days you set, Email 2 later, then a call ticket for the office. Estimates older than the last number are skipped."},{"u":"g-automations_what.html#s3","t":"The switch","a":"Switch reminders and notices on or off, and set their timing","x":"Turns it on or off and saves at once."},{"u":"g-automations_what.html#s4","t":"Its timing","a":"Switch reminders and notices on or off, and set their timing","x":"Change a number and the flow above follows it. Press the Save button that appears on the card to keep it."},{"u":"g-automations_what.html#s5","t":"Past-due reminders","a":"Switch reminders and notices on or off, and set their timing","x":"One statement per customer listing what's open: first after the days past due, then every few days, up to the number set; then a collection call. It can include SA balances."},{"u":"g-automations_what.html#s6","t":"Appointment reminders","a":"Switch reminders and notices on or off, and set their timing","x":"The day before, at the hour you set (0\u201323, 10 = 10 am), by email and by text when texts are on. Moving the appointment sends the new time."},{"u":"g-automations_what.html#s7","t":"Job start notice","a":"Switch reminders and notices on or off, and set their timing","x":"The day before a crew's first day on a job. \"Crews usually arrive\" is the wording for when they come. Maintenance visits don't get one."},{"u":"g-automations_what.html#s8","t":"\"We've arrived\"","a":"Switch reminders and notices on or off, and set their timing","x":"Sent when the crew lead starts the job on the phone, with the arrival photo. Once a day per job."},{"u":"g-automations_what.html#s9","t":"Accepted online \u2192 deposit","a":"Switch reminders and notices on or off, and set their timing","x":"When a customer signs the online estimate, the job, contract and payment schedule are made and the deposit invoice is emailed."},{"u":"g-automations_what.html#s10","t":"Card declined","a":"Switch reminders and notices on or off, and set their timing","x":"Marking a card as declined emails the customer to update it and gives the office a call ticket."},{"u":"g-automations_what.html#s11","t":"Satisfaction survey","a":"Switch reminders and notices on or off, and set their timing","x":"A short survey link the days you set after a job is complete. A score at or below your number opens a ticket so someone calls the customer."},{"u":"g-automations_what.html#s12","t":"Website requests","a":"Switch reminders and notices on or off, and set their timing","x":"Off: requests wait on My day for someone to accept. On: genuine-looking ones become a customer and a ticket at once, for the person in \"Tickets go to\"."},{"u":"g-automations_what.html#s13","t":"Sent and wording","a":"Switch reminders and notices on or off, and set their timing","x":"Each card says how many went out in the last 30 days. Edit wording opens its message."},{"u":"g-automations_wording.html","t":"Change the wording of an email or text","a":"Setup","k":"wording words text message email template subject body placeholder placeholders sms change edit reminder letter preview button send it","v":1},{"u":"g-automations_wording.html#s1","t":"Start from a card","a":"Change the wording of an email or text","x":"Every automation card has its own wording (the Wording button at the top opens the same place)."},{"u":"g-automations_wording.html#s2","t":"Edit wording","a":"Change the wording of an email or text","x":"Opens that message. Here: the appointment reminder."},{"u":"g-automations_wording.html#s3","t":"The message","a":"Change the wording of an email or text","x":"Its name, and when it was last changed and by whom (\"Standard wording\" if never)."},{"u":"g-automations_wording.html#s4","t":"Send it","a":"Change the wording of an email or text","x":"Switches this one message off without stopping its automation. Kept when you press Save wording."},{"u":"g-automations_wording.html#s5","t":"Subject","a":"Change the wording of an email or text","x":"The email's subject line. {placeholders} work here too."},{"u":"g-automations_wording.html#s6","t":"Message","a":"Change the wording of an email or text","x":"The email text. A blank line starts a new paragraph. The preview follows as you type."},{"u":"g-automations_wording.html#s7","t":"Placeholders","a":"Change the wording of an email or text","x":"Click one to put it where the cursor is: first name, appointment day and time, who with, address\u2026 Each customer gets their own."},{"u":"g-automations_wording.html#s8","t":"Text message version","a":"Change the wording of an email or text","x":"The text version, sent only when texts are switched on. Keep it under 160 characters; the hint counts them."},{"u":"g-automations_wording.html#s9","t":"Preview","a":"Change the wording of an email or text","x":"Below: the message as a real customer would get it, with sample numbers. It follows your changes as you type."},{"u":"g-automations_wording.html#s10","t":"Save wording","a":"Change the wording of an email or text","x":"Keeps it; the next messages use it."},{"u":"g-automations_wording.html#s11","t":"Undo changes","a":"Change the wording of an email or text","x":"Goes back to the saved wording."},{"u":"g-automations_wording.html#s12","t":"Every message","a":"Change the wording of an email or text","x":"Every message the system sends, including some with no switch of their own (You're on the schedule, the yearly maintenance price change). \"Off\" marks one switched off."},{"u":"g-automations_wording.html#s13","t":"Pick another one","a":"Change the wording of an email or text","x":"Click a message to change it."},{"u":"g-automations_wording.html#s14","t":"Button","a":"Change the wording of an email or text","x":"A message with a link has a button; this is its wording, e.g. View your estimate."},{"u":"g-automations_queue.html","t":"See what is waiting and what went out (stop or resend a message)","a":"Setup","k":"queue waiting sent outbox messages message emails texts stop cancel send now resend failed skipped log history view what went out","v":1},{"u":"g-automations_queue.html#s1","t":"Queue","a":"See what is waiting and what went out (stop or resend a message)","x":"Messages waiting to go."},{"u":"g-automations_queue.html#s2","t":"Waiting to go","a":"See what is waiting and what went out (stop or resend a message)","x":"Each message, customer, subject and address, and when it goes. The eye shows it, the arrow sends it now, the x cancels it. If its reason goes away (paid, answered) it cancels itself."},{"u":"g-automations_queue.html#s3","t":"Sent","a":"See what is waiting and what went out (stop or resend a message)","x":"What went out."},{"u":"g-automations_queue.html#s4","t":"What went out","a":"See what is waiting and what went out (stop or resend a message)","x":"The last 80 messages, newest first. Messages marked test went to the test address."},{"u":"g-automations_queue.html#s5","t":"Not sent","a":"See what is waiting and what went out (stop or resend a message)","x":"The ones that failed, were cancelled or were skipped, with the reason."},{"u":"g-automations_queue.html#s6","t":"Send again","a":"See what is waiting and what went out (stop or resend a message)","x":"Queues that message once more."},{"u":"g-automations_queue.html#s7","t":"Sent","a":"See what is waiting and what went out (stop or resend a message)","x":"Only the ones that went out."},{"u":"g-automations_queue.html#s8","t":"All","a":"See what is waiting and what went out (stop or resend a message)","x":"Everything again."},{"u":"g-automations_queue.html#s9","t":"The customer","a":"See what is waiting and what went out (stop or resend a message)","x":"The name opens the customer."},{"u":"g-automations_queue.html#s10","t":"View it","a":"See what is waiting and what went out (stop or resend a message)","x":"The eye shows the message."},{"u":"g-automations_queue.html#s11","t":"The message","a":"See what is waiting and what went out (stop or resend a message)","x":"Its subject, who it went (or was meant) to and, if it didn't go, why. Below: the message itself."},{"u":"g-automations_queue.html#s12","t":"Close it","a":"See what is waiting and what went out (stop or resend a message)","x":"The tour closes it."},{"u":"g-automations_setup.html","t":"Set up sending: live email, test address, texts, links","a":"Setup","k":"sending setup live email test address sandbox office email mailbox texts sms text messages links payment page request form crew photo quickbooks qb maintenance","v":1},{"u":"g-automations_setup.html#s1","t":"Sending setup","a":"Set up sending: live email, test address, texts, links","x":"The Sending setup tab: how messages are sent."},{"u":"g-automations_setup.html#s2","t":"Email","a":"Set up sending: live email, test address, texts, links","x":"While live email is off, everything goes to the test address (a few a day at most) with the real address in the subject."},{"u":"g-automations_setup.html#s3","t":"Live email to customers","a":"Set up sending: live email, test address, texts, links","x":"Switch it on once the wording is right: then automations write to real customers. It needs the office email first."},{"u":"g-automations_setup.html#s4","t":"Test address","a":"Set up sending: live email, test address, texts, links","x":"Where emails go while live email is off."},{"u":"g-automations_setup.html#s5","t":"Test emails a day","a":"Set up sending: live email, test address, texts, links","x":"The most test emails a day while live email is off."},{"u":"g-automations_setup.html#s6","t":"Where customers write","a":"Set up sending: live email, test address, texts, links","x":"Shown in every email so replies reach a person."},{"u":"g-automations_setup.html#s7","t":"Send from our mailbox","a":"Set up sending: live email, test address, texts, links","x":"Blank: emails come from the Fieldproxy no-reply. Connect the office mailbox in Fieldproxy, then put its account number here."},{"u":"g-automations_setup.html#s8","t":"Line under the name","a":"Set up sending: live email, test address, texts, links","x":"The line under the company name in emails."},{"u":"g-automations_setup.html#s9","t":"Marketing emails per hour","a":"Set up sending: live email, test address, texts, links","x":"Mailbox providers limit bulk sends; 200 an hour is safe for most."},{"u":"g-automations_setup.html#s10","t":"Text messages","a":"Set up sending: live email, test address, texts, links","x":"Switch texts on for appointment reminders, job notices and \"we've arrived\". Needs the SMS number set up. Customers who reply STOP are never texted again."},{"u":"g-automations_setup.html#s11","t":"Test mobile number","a":"Set up sending: live email, test address, texts, links","x":"Where texts go while live email is off."},{"u":"g-automations_setup.html#s12","t":"Online payment page","a":"Set up sending: live email, test address, texts, links","x":"Optional: where customers pay a deposit online. Shown after they accept."},{"u":"g-automations_setup.html#s13","t":"Request form link","a":"Set up sending: live email, test address, texts, links","x":"The public request form, used by campaign buttons and the website."},{"u":"g-automations_setup.html#s14","t":"Crew photos","a":"Set up sending: live email, test address, texts, links","x":"Yes: crews can't start or finish a job without a photo."},{"u":"g-automations_setup.html#s15","t":"Too far from the job","a":"Set up sending: live email, test address, texts, links","x":"Starts or finishes further than this from the address (in meters) are flagged on the job."},{"u":"g-automations_setup.html#s16","t":"Maintenance ahead","a":"Set up sending: live email, test address, texts, links","x":"How many days ahead maintenance visits are put on the schedule."},{"u":"g-automations_setup.html#s17","t":"QuickBooks items","a":"Set up sending: live email, test address, texts, links","x":"The QuickBooks product/service names for invoice lines, deposits and milestones, and maintenance visits, used in the QuickBooks file."},{"u":"g-automations_setup.html#s18","t":"Save setup","a":"Set up sending: live email, test address, texts, links","x":"Keeps everything on this tab. It checks the addresses and links first."},{"u":"g-s_settings.html","t":"Everything on Settings","a":"Setup","k":"settings company details name phone email address license licence time zone tax sales tax card fee surcharge payment schedule schedules deposit commission rate terms invoice footer late fee overtime payroll adp fleet manager snow salt email live setup","v":0},{"u":"g-s_settings.html#s1","t":"Settings","a":"Everything on Settings","x":"Company details, tax, contract terms, payroll, fleet, payment schedules, commission and the text on documents. Only the owner and the office open it."},{"u":"g-s_settings.html#s2","t":"Save settings","a":"Everything on Settings","x":"Nothing here is kept until you press it (payment schedules have their own Save). It checks the numbers first."},{"u":"g-s_settings.html#s3","t":"Company","a":"Everything on Settings","x":"Company name, phone, email, office address, licence line and time zone, printed on estimates, invoices and emails."},{"u":"g-s_settings.html#s4","t":"Estimates","a":"Everything on Settings","x":"How long estimates are valid, the days to the first and second follow-up, and the amount above which a contract needs a signature."},{"u":"g-s_settings.html#s5","t":"Sales tax","a":"Everything on Settings","x":"The NJ sales tax rate added to taxable work."},{"u":"g-s_settings.html#s6","t":"Labour cost per crew-hour","a":"Everything on Settings","x":"What a crew-hour costs you, for the margins on estimates. Job costing uses the burn rates under Reports."},{"u":"g-s_settings.html#s7","t":"How commission works","a":"Everything on Settings","x":"Commission on the job's gross profit or on the sale; earned when the whole job is paid, or on each paid invoice (sale only)."},{"u":"g-s_settings.html#s8","t":"Card surcharge","a":"Everything on Settings","x":"The % added to card payments, shown on invoices and contracts. Blank: no surcharge, and it isn't mentioned."},{"u":"g-s_settings.html#s9","t":"Extras rate","a":"Everything on Settings","x":"The rate per man-hour for extra work not in the estimate, printed in the contract terms."},{"u":"g-s_settings.html#s10","t":"Late charge","a":"Everything on Settings","x":"A % a month added to late invoices once a month, once they are late by the days below. Blank = off."},{"u":"g-s_settings.html#s11","t":"Payroll","a":"Everything on Settings","x":"Overtime after how many hours a week, and the ADP company code for the pay-data file from Timesheets."},{"u":"g-s_settings.html#s12","t":"Customer notices","a":"Everything on Settings","x":"Which types of work (crew specializations) get the \"you're on the schedule for \u2026\" email. Each job can override it."},{"u":"g-s_settings.html#s13","t":"Fleet manager","a":"Everything on Settings","x":"Who gets the Monday due list and the crews' truck reports."},{"u":"g-s_settings.html#s14","t":"When \"due soon\" starts","a":"Everything on Settings","x":"How close oil and tires (miles), inspections (days) and machine service (engine hours) must be to count as due soon."},{"u":"g-s_settings.html#s15","t":"Snow","a":"Everything on Settings","x":"The units for salt and ice melt, and whether snow work is taxed."},{"u":"g-s_settings.html#s16","t":"Payment schedules","a":"Everything on Settings","x":"The payments an estimate is split into (each picks one, by type of work). Each card shows them and what they come to on a $20,000 job."},{"u":"g-s_settings.html#s17","t":"A schedule","a":"Everything on Settings","x":"Click one to change it. The top line says whether it's the default or which work it is for."},{"u":"g-s_settings.html#s18","t":"New schedule","a":"Everything on Settings","x":"Makes another one. The tour \"Set up a payment schedule\" shows the editor."},{"u":"g-s_settings.html#s19","t":"Commission rates","a":"Everything on Settings","x":"The rate for everyone, plus any salesperson with their own rate."},{"u":"g-s_settings.html#s20","t":"Add a salesperson rate","a":"Everything on Settings","x":"Adds a row: pick the salesperson and their %. The x removes one. Kept with Save settings."},{"u":"g-s_settings.html#s21","t":"Text on documents","a":"Everything on Settings","x":"The standard terms printed on estimates, and the footer on invoices."},{"u":"g-s_settings.html#s22","t":"Open Automations","a":"Everything on Settings","x":"Follow-ups, reminders, texts and the sending mailbox are set up under Automations, with the wording of every message."},{"u":"g-s_settings.html#s23","t":"Live email","a":"Everything on Settings","x":"Off: every email goes to the test address instead of the customer. Turn it on when ready; it needs the company email. Kept with Save settings."},{"u":"g-s_settings.html#s24","t":"Test address","a":"Everything on Settings","x":"Where emails go while live email is off."},{"u":"g-s_settings.html#s25","t":"Customer quote link","a":"Everything on Settings","x":"Optional: a link customers can open; {token} is replaced for each estimate."},{"u":"g-settings_schedules.html","t":"Set up a payment schedule (deposit, progress payments, final)","a":"Setup","k":"payment schedule schedules deposit progress final balance percent percentage fixed due signing completion start 50/50 30/60/10 milestones payments terms","v":1},{"u":"g-settings_schedules.html#s1","t":"Payment schedules","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Each estimate picks one, by type of work. A fixed first deposit is allowed; the percentages share what is left."},{"u":"g-settings_schedules.html#s2","t":"New schedule","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Opens the editor with a 30 / 60 / 10 start."},{"u":"g-settings_schedules.html#s3","t":"Name","a":"Set up a payment schedule (deposit, progress payments, final)","x":"What it's called on the estimate, e.g. Paver / hardscape (7 payments)."},{"u":"g-settings_schedules.html#s4","t":"Default for these types of work","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Crew specializations, with commas (hardscape, landscape\u2026). Estimates for that work start with this schedule."},{"u":"g-settings_schedules.html#s5","t":"The default schedule","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Tick it for the schedule every other estimate starts with."},{"u":"g-settings_schedules.html#s6","t":"Start from","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Ready-made schedules: 30 / 60 / 10, 50 / 50, Deposit + final, Due on receipt. Pick one, then change it."},{"u":"g-settings_schedules.html#s7","t":"Deposit + final","a":"Set up a payment schedule (deposit, progress payments, final)","x":"For example a fixed deposit, then the balance."},{"u":"g-settings_schedules.html#s8","t":"One payment","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Its number and name, as the customer reads it."},{"u":"g-settings_schedules.html#s9","t":"How much","a":"Set up a payment schedule (deposit, progress payments, final)","x":"% of the rest (a share of what's left after fixed amounts), Fixed $ or The balance (whatever is left; only one)."},{"u":"g-settings_schedules.html#s10","t":"The amount","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Dollars for a fixed payment, a percentage for \"% of the rest\"."},{"u":"g-settings_schedules.html#s11","t":"When it's due","a":"Set up a payment schedule (deposit, progress payments, final)","x":"At signing, on receipt, days before the start, when work starts, on completion, or on a date."},{"u":"g-settings_schedules.html#s12","t":"Order","a":"Set up a payment schedule (deposit, progress payments, final)","x":"The arrows move a payment up or down; the x removes it."},{"u":"g-settings_schedules.html#s13","t":"Add a payment","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Adds another payment at the end."},{"u":"g-settings_schedules.html#s14","t":"Does it add up?","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Green when it works. Red says what to fix, e.g. percentages that don't make 100%."},{"u":"g-settings_schedules.html#s15","t":"Save schedule","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Saves it. Open estimates can pick it straight away."},{"u":"g-settings_schedules.html#s16","t":"Close the editor","a":"Set up a payment schedule (deposit, progress payments, final)","x":"The tour closes it without saving."},{"u":"g-settings_schedules.html#s17","t":"Change one","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Click a schedule to change it."},{"u":"g-settings_schedules.html#s18","t":"Delete","a":"Set up a payment schedule (deposit, progress payments, final)","x":"Removes it after asking. Open estimates using it go back to their default; signed contracts keep their payments."},{"u":"g-settings_schedules.html#s19","t":"Close it","a":"Set up a payment schedule (deposit, progress payments, final)","x":"The tour closes it without saving."},{"u":"g-s_guide.html","t":"Everything on Guide","a":"Setup","k":"guide help how to howto learn path of a job where things are menu screens tour take the tour show me workflow","v":0},{"u":"g-s_guide.html#s1","t":"The Guide","a":"Everything on Guide","x":"How it all fits together: the path of a job, how to do the everyday things, and what each part of the menu is for."},{"u":"g-s_guide.html#s2","t":"Quick tour of the app","a":"Everything on Guide","x":"Plays a short tour of the main screens, one after another."},{"u":"g-s_guide.html#s3","t":"The path of a job","a":"Everything on Guide","x":"From the first call to the commission, in nine steps."},{"u":"g-s_guide.html#s4","t":"Each step opens its screen","a":"Everything on Guide","x":"Click a step, like 1 \u00b7 A call or a request, to open the screen where it happens."},{"u":"g-s_guide.html#s5","t":"Crew on site","a":"Everything on Guide","x":"This one happens on the crew's phone. It opens the Schedule, where you see who is where."},{"u":"g-s_guide.html#s6","t":"How to \u2026","a":"Everything on Guide","x":"The everyday jobs, step by step. The bold words are the buttons to press."},{"u":"g-s_guide.html#s7","t":"An open how-to","a":"Everything on Guide","x":"Numbered steps, with who usually does it under the title."},{"u":"g-s_guide.html#s8","t":"Take the tour","a":"Everything on Guide","x":"Plays that how-to on the real screens, pointing at each button, like this tour."},{"u":"g-s_guide.html#s9","t":"Show me","a":"Everything on Guide","x":"Just opens the screen where it happens."},{"u":"g-s_guide.html#s10","t":"Open another","a":"Everything on Guide","x":"Click a title to open it; the one that was open closes."},{"u":"g-s_guide.html#s11","t":"Now open","a":"Everything on Guide","x":"Its steps, and its own Take the tour."},{"u":"g-s_guide.html#s12","t":"Where things are","a":"Everything on Guide","x":"Every part of the menu, what it's for and how often you'll use it."},{"u":"g-s_guide.html#s13","t":"Sell","a":"Everything on Guide","x":"My day, Customers, Appointments, Estimates and Marketing."},{"u":"g-s_guide.html#s14","t":"Build","a":"Everything on Guide","x":"Jobs, Schedule, Maintenance, Deliveries, Snow and Timesheets."},{"u":"g-s_guide.html#s15","t":"Money","a":"Everything on Guide","x":"Invoices and Reports, for people who see money."},{"u":"g-s_guide.html#s16","t":"Setup","a":"Everything on Guide","x":"Catalogue, Fleet and, for the owner and office, Team & crews, Automations and Settings."},{"u":"g-s_guide.html#s17","t":"Open a screen","a":"Everything on Guide","x":"Click a row to open that screen. The tag says how often it's used."},{"u":"g-s_guide.html#s18","t":"Help on every screen","a":"Everything on Guide","x":"Ask in your own words, or pick \"Show me everything on this screen\" for a tour like this one."},{"u":"g-s_guide.html#s19","t":"Search","a":"Everything on Guide","x":"Finds customers, phones, streets and EST-, JOB- or INV- numbers from any screen (\u2318K)."},{"u":"g-templates_ai.html","t":"Design an email template with AI (or a ready layout)","a":"Sell","k":"email template design designer ai artificial intelligence layout photo photos picture pictures campaign marketing newsletter ad advert look nice branded save template","v":1},{"u":"g-templates_ai.html#s1","t":"Design an email with AI","a":"Design an email template with AI (or a ready layout)","x":"Opens the email designer. You describe the email and add photos; the design builds on the left."},{"u":"g-templates_ai.html#s2","t":"The email, live","a":"Design an email template with AI (or a ready layout)","x":"Exactly what customers will get: the design, your words, and our footer with the unsubscribe line. Computer and Phone switch the width."},{"u":"g-templates_ai.html#s3","t":"Say what you want","a":"Design an email template with AI (or a ready layout)","x":"What it's for, the feel, the colours and what to show. For example: a spring cleanup email for our regular customers, my patio photo across the top, fresh greens."},{"u":"g-templates_ai.html#s4","t":"Ideas to start from","a":"Design an email template with AI (or a ready layout)","x":"Tap one to fill the box, then change it to suit."},{"u":"g-templates_ai.html#s5","t":"Attach your photos","a":"Design an email template with AI (or a ready layout)","x":"Up to six photos of your work. Write what each one shows, so the design puts the right one on top."},{"u":"g-templates_ai.html#s6","t":"Main colour","a":"Design an email template with AI (or a ready layout)","x":"Pick one of your colours, or let the design choose."},{"u":"g-templates_ai.html#s7","t":"Design it","a":"Design an email template with AI (or a ready layout)","x":"The AI makes the design and its words. Then ask for any change, like a bigger headline; each change is a version you can go back to. AI has to be switched on for your account; until then, the ready layouts below do the same job."},{"u":"g-templates_ai.html#s8","t":"Or pick a ready layout","a":"Design an email template with AI (or a ready layout)","x":"Four proven designs that take your photos, colour and words. Click Photo on top."},{"u":"g-templates_ai.html#s9","t":"The words","a":"Design an email template with AI (or a ready layout)","x":"Subject, headline, the line under it, the message and the button. Every campaign made from this template starts with these, and can change them."},{"u":"g-templates_ai.html#s10","t":"Name it","a":"Design an email template with AI (or a ready layout)","x":"A name you'll recognise, like Spring photo hero."},{"u":"g-templates_ai.html#s11","t":"Save as template","a":"Design an email template with AI (or a ready layout)","x":"Keeps it in Email templates, ready for any campaign. The tour doesn't save anything: press it yourself when it's right."},{"u":"g-templates_use.html","t":"Use a saved email template in a campaign","a":"Sell","k":"template templates use pick choose campaign email design my templates saved rename delete","v":1},{"u":"g-templates_use.html#s1","t":"Email templates","a":"Use a saved email template in a campaign","x":"Every saved template, with a picture of it, who changed it last and how many campaigns use it."},{"u":"g-templates_use.html#s2","t":"A template","a":"Use a saved email template in a campaign","x":"Use in a campaign starts a new campaign with it. Edit opens it in the designer. The pen renames it; the bin deletes it, and campaigns already made with it keep their look."},{"u":"g-templates_use.html#s3","t":"From any campaign","a":"Use a saved email template in a campaign","x":"A campaign can also pick a template in its Design card."},{"u":"g-templates_use.html#s4","t":"New campaign","a":"Use a saved email template in a campaign","x":"Opens the composer."},{"u":"g-templates_use.html#s5","t":"My templates","a":"Use a saved email template in a campaign","x":"In the Design card, pick My templates."},{"u":"g-templates_use.html#s6","t":"Pick one","a":"Use a saved email template in a campaign","x":"Click a template's picture. The preview becomes the template with this campaign's own words, and you can still change the headline or the button colour here."},{"u":"g-templates_use.html#s7","t":"What they'll see","a":"Use a saved email template in a campaign","x":"The email exactly as customers get it, footer and unsubscribe line included."},{"u":"g-estimate_invoice.html","t":"Invoice an estimate in one click (small jobs, cleanups)","a":"Money","k":"invoice it estimate to invoice turn convert quote into invoice small job cleanup done bill now one click","v":1},{"u":"g-estimate_invoice.html#s1","t":"Open the estimate","a":"Invoice an estimate in one click (small jobs, cleanups)","x":"A small job or a cleanup that's done? Open its estimate."},{"u":"g-estimate_invoice.html#s2","t":"Invoice it","a":"Invoice an estimate in one click (small jobs, cleanups)","x":"Marks the estimate won, so the job is made and commission and job costing follow it, then makes a draft invoice for the whole amount, line by line as the customer saw it. You check the draft, then email or print it. On a won estimate the green banner has Invoice the job."},{"u":"g-estimate_invoice.html#s3","t":"Design pictures","a":"Invoice an estimate in one click (small jobs, cleanups)","x":"Drawings or photos of the design. Add puts them in the proposal under Your design, with a caption if you like."},{"u":"g-estimate_invoice.html#s4","t":"The customer copy","a":"Invoice an estimate in one click (small jobs, cleanups)","x":"Open the customer copy shows the A4 pages exactly as the customer gets them. Print or PDF prints them, or saves a PDF to attach."},{"u":"g-documents_copy.html","t":"The customer copy: A4 invoices and proposals","a":"Money","k":"a4 customer copy preview print pdf invoice proposal estimate document page pages letterhead logo key figures what the customer sees","v":1},{"u":"g-documents_copy.html#s1","t":"Open an invoice","a":"The customer copy: A4 invoices and proposals","x":"Click any invoice."},{"u":"g-documents_copy.html#s2","t":"What the customer gets","a":"The customer copy: A4 invoices and proposals","x":"The invoice exactly as it's printed and emailed: A4 pages, with the invoice total, what's paid, what's due and when it was issued across the top. The account balance stays in its own box at the bottom."},{"u":"g-documents_copy.html#s3","t":"Open full size","a":"The customer copy: A4 invoices and proposals","x":"The pages at real size."},{"u":"g-documents_copy.html#s4","t":"Print or PDF","a":"The customer copy: A4 invoices and proposals","x":"Print it, or choose Save as PDF in the print window to attach it to an email. Proposals work the same way, from the estimate's Customer copy card."},{"u":"g-appt_email.html","t":"Email an appointment to someone","a":"Sell","k":"email appointment ticket forward send details someone else cover colleague share visit call task","v":1},{"u":"g-appt_email.html#s1","t":"Open an appointment","a":"Email an appointment to someone","x":"Click any appointment."},{"u":"g-appt_email.html#s2","t":"Email it","a":"Email an appointment to someone","x":"Sends the details to anyone: when, the customer, their phone and address, and the notes. Click it and a small form opens: the address to send it to, a note from you if you like (Can you cover this one?), and Send. It is logged on the appointment."},{"u":"g-invoices_drafts_all.html","t":"Email or print all the draft invoices at once","a":"Money","k":"email all print all drafts month end batch many invoices send at once together","v":1},{"u":"g-invoices_drafts_all.html#s1","t":"Drafts","a":"Email or print all the draft invoices at once","x":"The invoices not sent yet, for example after the month-end run."},{"u":"g-invoices_drafts_all.html#s2","t":"Email all","a":"Email or print all the draft invoices at once","x":"Emails each customer their own invoice, one after another. Any customer without an email address is listed so you can print theirs."},{"u":"g-invoices_drafts_all.html#s3","t":"Print all","a":"Email or print all the draft invoices at once","x":"One print job with every draft, a page each; they're marked sent."},{"u":"g-settings_logo.html","t":"Put your logo on every estimate, invoice and email","a":"Setup","k":"logo letterhead brand company upload picture settings crew days week six days","v":1},{"u":"g-settings_logo.html#s1","t":"Logo","a":"Put your logo on every estimate, invoice and email","x":"Upload your logo, a PNG or JPG with a white or clear background. It goes at the top of every estimate, invoice and email."},{"u":"g-settings_logo.html#s2","t":"Most days a crew works","a":"Put your logo on every estimate, invoice and email","x":"Scheduling warns when a crew would work more days than this in a week, for example a Saturday on top of a full week."},{"u":"g-settings_logo.html#s3","t":"Save settings","a":"Put your logo on every estimate, invoice and email","x":"Keeps the logo and your changes."},{"u":"g-crew_appts.html","t":"Visits and phone calls on the phone","a":"Crew phone app","k":"","v":1},{"u":"g-crew_appts.html#s1","t":"My appointments","a":"Visits and phone calls on the phone","x":"Visits, call-backs and tasks the office booked for you, today first."},{"u":"g-crew_appts.html#s2","t":"A visit","a":"Visits and phone calls on the phone","x":"The customer, what it's for and when, with Directions and Call."},{"u":"g-crew_appts.html#s3","t":"Notes from the visit","a":"Visits and phone calls on the phone","x":"What the customer wants, access, the gate code."},{"u":"g-crew_appts.html#s4","t":"Measurements","a":"Visits and phone calls on the phone","x":"Write them as you take them."},{"u":"g-crew_appts.html#s5","t":"Photos","a":"Visits and phone calls on the phone","x":"The yard and the area to quote. They show in the office straight away."},{"u":"g-crew_appts.html#s6","t":"Save","a":"Visits and phone calls on the phone","x":"Everything you saved is on the appointment in the office, for whoever writes the estimate."},{"u":"g-crew_appts.html#s7","t":"Visit done, estimate pending","a":"Visits and phone calls on the phone","x":"The office sees the visit is done and the quote is waiting."},{"u":"g-crew_appts.html#s8","t":"A phone call","a":"Visits and phone calls on the phone","x":"A call shows one big button with the number. Write what was said, then mark it done."},{"u":"g-crew_day.html","t":"The crew lead's day on the phone","a":"Crew phone app","k":"","v":1},{"u":"g-crew_day.html#s1","t":"Today","a":"The crew lead's day on the phone","x":"The crew lead's phone. Each morning starts here: your crew, today's jobs, and the one thing to do next. Big buttons, made for gloves and sunshine."},{"u":"g-crew_day.html#s2","t":"Who is here today?","a":"The crew lead's day on the phone","x":"Your usual crew is listed. Switch off anyone who didn't come, so their hours and the job costs stay right."},{"u":"g-crew_day.html#s3","t":"Start the crew's day","a":"The crew lead's day on the phone","x":"One tap clocks in everyone who is here, at the yard."},{"u":"g-crew_day.html#s4","t":"What the crew is doing","a":"The crew lead's day on the phone","x":"Yard, loading, on the road, on the job, unloading, break. One tap moves everyone's time, so the office sees where the day went."},{"u":"g-crew_day.html#s5","t":"Leave for the job","a":"The crew lead's day on the phone","x":"The whole crew is now on the road."},{"u":"g-crew_day.html#s6","t":"We're here","a":"The crew lead's day on the phone","x":"Opens the job to take the arrival photo."},{"u":"g-crew_day.html#s7","t":"The arrival photo","a":"The crew lead's day on the phone","x":"Needed to start: the house and the work area, stamped with the time and where you are."},{"u":"g-crew_day.html#s8","t":"Start the job","a":"The crew lead's day on the phone","x":"Records the start with the photo and G.P.S. The customer gets a message that the crew has arrived, and the crew's time moves onto the job."},{"u":"g-crew_day.html#s9","t":"Work, photos and notes","a":"The crew lead's day on the phone","x":"What we're doing and the materials to load, the job's photos, and notes for the office."},{"u":"g-crew_day.html#s10","t":"Finish the job","a":"The crew lead's day on the phone","x":"When the work is done."},{"u":"g-crew_day.html#s11","t":"The finish photo","a":"The crew lead's day on the phone","x":"The finished work, wide enough to see it all."},{"u":"g-crew_day.html#s12","t":"A note for the office","a":"The crew lead's day on the phone","x":"Anything left to do, or what the customer said."},{"u":"g-crew_day.html#s13","t":"Done","a":"The crew lead's day on the phone","x":"The job is complete, and the office is told straight away."},{"u":"g-crew_day.html#s14","t":"Breaks","a":"The crew lead's day on the phone","x":"Break stops the clock on the work. Back to work picks up where the crew left off."},{"u":"g-crew_day.html#s15","t":"Back to work","a":"The crew lead's day on the phone","x":"One big button."},{"u":"g-crew_day.html#s16","t":"End the day","a":"The crew lead's day on the phone","x":"Tap it twice: it clocks out the whole crew. My hours shows the day as a timeline."},{"u":"g-crew_job.html","t":"A job on the phone: materials, photos, notes, problems","a":"Crew phone app","k":"","v":1},{"u":"g-crew_job.html#s1","t":"The job","a":"A job on the phone: materials, photos, notes, problems","x":"The job number, the day of the job, the customer and the address, with Directions and Call."},{"u":"g-crew_job.html#s2","t":"Directions","a":"A job on the phone: materials, photos, notes, problems","x":"Opens maps with the address. Call rings the customer."},{"u":"g-crew_job.html#s3","t":"What we're doing","a":"A job on the phone: materials, photos, notes, problems","x":"The work, in the office's words, and any note for the crew. No prices: the crew phone never shows money."},{"u":"g-crew_job.html#s4","t":"Materials to load","a":"A job on the phone: materials, photos, notes, problems","x":"Tap each item when it's on the truck. The office sees what was loaded."},{"u":"g-crew_job.html#s5","t":"Photos","a":"A job on the phone: materials, photos, notes, problems","x":"The arrival and finish photos, and any you add."},{"u":"g-crew_job.html#s6","t":"Add photos","a":"A job on the phone: materials, photos, notes, problems","x":"Take as many as you need, add what they show, and save."},{"u":"g-crew_job.html#s7","t":"Notes","a":"A job on the phone: materials, photos, notes, problems","x":"A note for the office: it shows on the job in the office straight away."},{"u":"g-crew_job.html#s8","t":"Write a note","a":"A job on the phone: materials, photos, notes, problems","x":"Type it, then Save the note."},{"u":"g-crew_job.html#s9","t":"Report a problem","a":"A job on the phone: materials, photos, notes, problems","x":"A broken pipe, the wrong pavers, an unhappy customer: it becomes an office ticket, with photos."},{"u":"g-crew_job.html#s10","t":"What's wrong","a":"A job on the phone: materials, photos, notes, problems","x":"Say what's wrong, add photos if they help, and send it to the office."},{"u":"g-crew_more.html","t":"Snow log, truck problems and my hours","a":"Crew phone app","k":"","v":1},{"u":"g-crew_more.html#s1","t":"Snow sites","a":"Snow log, truck problems and my hours","x":"Every snow site, the ones not done today first. Anyone signed in can log one."},{"u":"g-crew_more.html#s2","t":"Times","a":"Snow log, truck problems and my hours","x":"Time in and time out, like five thirty A.M."},{"u":"g-crew_more.html#s3","t":"What was done","a":"Snow log, truck problems and my hours","x":"Plowed, salted, shoveled walks, calcium: tap each one."},{"u":"g-crew_more.html#s4","t":"Save the visit","a":"Snow log, truck problems and my hours","x":"The office can bill it straight away."},{"u":"g-crew_more.html#s5","t":"A truck problem","a":"Snow log, truck problems and my hours","x":"Pick the truck or machine, say what's wrong, add a photo: the fleet manager gets it straight away."},{"u":"g-crew_more.html#s6","t":"My hours","a":"Snow log, truck problems and my hours","x":"Today, this week and the days worked, with the day as a timeline: yard, road, job and breaks."},{"u":"g-crew_runs.html","t":"The driver's runs: deliveries and containers","a":"Crew phone app","k":"","v":1},{"u":"g-crew_runs.html#s1","t":"My runs","a":"The driver's runs: deliveries and containers","x":"Deliveries, container drops, pickups and swaps, today first."},{"u":"g-crew_runs.html#s2","t":"The run","a":"The driver's runs: deliveries and containers","x":"When, the load, the container and the truck, with Directions."},{"u":"g-crew_runs.html#s3","t":"On my way","a":"The driver's runs: deliveries and containers","x":"The office sees you are on the road."},{"u":"g-crew_runs.html#s4","t":"A photo","a":"The driver's runs: deliveries and containers","x":"Where you left it."},{"u":"g-crew_runs.html#s5","t":"Mark it done","a":"The driver's runs: deliveries and containers","x":"Pick the container that went out if it asks, add a note, and mark it done."}];